INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20492, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "一步一步地做事情。", "primary_collocate": null, "pronunciation": "zhú bù", "ipa": "ʈʂu˧˥ pu˥˩", "syllable_count": 2, "sentences": [{"text": "我们要逐步提高汉语水平。", "target_word": "逐步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气逐步变暖，花也开了。", "target_word": "逐步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司逐步增加了新的工作。", "target_word": "逐步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的身体逐步好起来了。", "target_word": "逐步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生逐步习惯了新学校的生活。", "target_word": "逐步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们逐步把旧房子拆了。", "target_word": "逐步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的空气逐步变好了。", "target_word": "逐步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让孩子逐步学会自己做饭。", "target_word": "逐步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，你要逐步增加运动。", "target_word": "逐步", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格逐步下降，大家都很高兴。", "target_word": "逐步", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "一步接一步、渐渐地进行或变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '352aafc0-c763-41dd-ae5f-940379d8e408') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20492, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "逐步", "is_correct": true, "explanation": "正确：“逐步”表示一步步进行，与“提高汉语水平”相合。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”指已经完成，与“要”表示的将来意愿矛盾。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”指过去，与“要”表示的将来不符。"}, {"text": "很", "is_correct": false, "explanation": "搭配：“很”修饰形容词，不能修饰“提高”这类动词。"}], "explanations": {"逐步": "正确：“逐步”表示一步步进行，与“提高汉语水平”相合。", "已经": "语义：“已经”指已经完成，与“要”表示的将来意愿矛盾。", "曾经": "语义：“曾经”指过去，与“要”表示的将来不符。", "很": "搭配：“很”修饰形容词，不能修饰“提高”这类动词。"}, "sentence_index": 0, "correct_answer": "逐步"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他逐步跳下了水。", "explanation": "这里应该用〈突然〉。“逐步”指一步步进行，跳水是一下完成的动作，不能用“逐步”。"}, {"text": "他逐步打了个喷嚏。", "explanation": "这里应该用〈突然〉。“逐步”指一步步进行，打喷嚏是一下子发生的，不能用“逐步”。"}, {"text": "他逐步挂断了电话。", "explanation": "这里应该用〈立即〉。挂断电话是一下完成的动作，“逐步”指一步步进行，不能用于此处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfc5fd7-604e-4dfe-a8ae-4874ca58b5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20492, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "逐步", "is_correct": true, "explanation": "正确：“逐步”表示渐渐地变化，与“变好了”相合。"}, {"text": "险些", "is_correct": false, "explanation": "语义：“险些”表示差一点没发生，与“变好了”的完成意思矛盾。"}, {"text": "从未", "is_correct": false, "explanation": "语义：“从未”表示从来没有，与“变好了”的变化不符。"}, {"text": "最", "is_correct": false, "explanation": "搭配：“最”修饰形容词，不能直接修饰“变好”。"}], "explanations": {"逐步": "正确：“逐步”表示渐渐地变化，与“变好了”相合。", "险些": "语义：“险些”表示差一点没发生，与“变好了”的完成意思矛盾。", "从未": "语义：“从未”表示从来没有，与“变好了”的变化不符。", "最": "搭配：“最”修饰形容词，不能直接修饰“变好”。"}, "sentence_index": 6, "correct_answer": "逐步"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "炸弹逐步爆炸了。", "explanation": "这里应该用〈瞬间〉。“逐步”指一步步进行，爆炸是一下子发生的，不能用“逐步”。"}, {"text": "一道闪电逐步划破了夜空。", "explanation": "这里应该用〈瞬间〉。“逐步”指一步步进行，闪电划破夜空是一瞬间发生的，不能用“逐步”。"}, {"text": "一声枪响，他逐步倒地。", "explanation": "这里应该用〈应声〉。倒地是一下子发生的，应该用“应声”，不能用“逐步”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfc5fd7-604e-4dfe-a8ae-4874ca58b5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20492, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们把逐步改善了环境。", "corrected_sentence": "他们逐步改善了环境。", "error_description": "错误：“把”字句中“把”后应接宾语，副词“逐步”不能直接放在“把”后，应删去“把”。正确：“他们逐步改善了环境”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfc5fd7-604e-4dfe-a8ae-4874ca58b5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20492, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的成绩很逐步提高了。", "corrected_sentence": "他的成绩逐步提高了。", "error_description": "“很”是程度副词，不能修饰副词“逐步”，应删去“很”。错误形式是“很逐步提高”，正确形式是“逐步提高”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfc5fd7-604e-4dfe-a8ae-4874ca58b5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
