INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20498, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "手机是一种可以拿着打电话、发信息的小机器。", "primary_collocate": null, "pronunciation": "shǒu jī", "ipa": "ʂou˨˩˦ tɕi˥", "syllable_count": 2, "sentences": [{"text": "我的手机放在桌子上。", "target_word": "手机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手机给妈妈打电话。", "target_word": "手机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部手机很新，也很轻。", "target_word": "手机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机没电了，我要充电。", "target_word": "手机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在地铁上看着手机。", "target_word": "手机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把手机忘在出租车里了。", "target_word": "手机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把手机关了，电影要开始了。", "target_word": "手机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了一部新手机，用了一年。", "target_word": "手机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用手机拍了很多照片。", "target_word": "手机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机屏幕坏了，要去修一修。", "target_word": "手机", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一部手机", "label": "量词"}, {"form": "手機", "label": "繁体"}], "register": "中性", "sense_fingerprint": "可以拿着打电话、发信息的小机器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '245aa18a-045a-46cc-b4fa-b7de9581fe19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20498, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "手机", "is_correct": true, "explanation": "正确：手机是可以拿着打电话、发信息的小机器。"}, {"text": "收集", "is_correct": false, "explanation": "shōují 与 shǒujī 两个音节的声调都不同，意思是把东西聚在一起。"}, {"text": "手迹", "is_correct": false, "explanation": "shǒujì（第四声）与 shǒujī（第一声）第二音节声调不同，意思是人写下的字迹。"}, {"text": "首级", "is_correct": false, "explanation": "shǒují（第二声）与 shǒujī（第一声）第二音节声调不同，意思是古代战争中砍下的人头。"}], "explanations": {"手机": "正确：手机是可以拿着打电话、发信息的小机器。", "收集": "shōují 与 shǒujī 两个音节的声调都不同，意思是把东西聚在一起。", "手迹": "shǒujì（第四声）与 shǒujī（第一声）第二音节声调不同，意思是人写下的字迹。", "首级": "shǒují（第二声）与 shǒujī（第一声）第二音节声调不同，意思是古代战争中砍下的人头。"}, "sentence_index": null, "correct_answer": "手机"}, "level_3": {"options": [{"text": "手机", "is_correct": true, "explanation": "正确：手机是可以放在桌子上的物品，符合句意。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：「太阳」是天体，不能被放在桌子上。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：「放」不能与「声音」搭配，声音不能被放置。"}, {"text": "梦想", "is_correct": false, "explanation": "语义：「梦想」是抽象的东西，不能放在桌子上。"}], "explanations": {"手机": "正确：手机是可以放在桌子上的物品，符合句意。", "太阳": "语义：「太阳」是天体，不能被放在桌子上。", "声音": "搭配：「放」不能与「声音」搭配，声音不能被放置。", "梦想": "语义：「梦想」是抽象的东西，不能放在桌子上。"}, "sentence_index": 0, "correct_answer": "手机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我用手机煮了一碗面。", "explanation": "这里把〈手机〉当成了锅，手机是打电话、发信息的机器，不能用来煮面。"}, {"text": "他每天用手机来洗衣服。", "explanation": "这里把〈手机〉当成了洗衣机，手机是打电话、发信息的机器，不能用来洗衣服，洗衣服应该用〈洗衣机〉。"}, {"text": "我买了一张手机。", "explanation": "这里应该用〈部〉。「张」多用于纸、桌子等平的东西，不用于手机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e68fea7-3f48-4414-8e82-b156083ca382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20498, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "手机", "is_correct": true, "explanation": "正确：手机是可以拿着打电话、发信息的小机器。"}, {"text": "受击", "is_correct": false, "explanation": "shòujī（第四声）与 shǒujī（第三声）第一音节声调不同，意思是遭受打击。"}, {"text": "手记", "is_correct": false, "explanation": "shǒujì（第四声）与 shǒujī（第一声）第二音节声调不同，意思是随手写下的记录。"}, {"text": "首期", "is_correct": false, "explanation": "shǒuqī 与 shǒujī 只有声母不同（q 与 j），意思是第一期。"}], "explanations": {"手机": "正确：手机是可以拿着打电话、发信息的小机器。", "受击": "shòujī（第四声）与 shǒujī（第三声）第一音节声调不同，意思是遭受打击。", "手记": "shǒujì（第四声）与 shǒujī（第一声）第二音节声调不同，意思是随手写下的记录。", "首期": "shǒuqī 与 shǒujī 只有声母不同（q 与 j），意思是第一期。"}, "sentence_index": null, "correct_answer": "手机"}, "level_3": {"options": [{"text": "手机", "is_correct": true, "explanation": "正确：「请把手机关了」指关掉手机，符合句意。"}, {"text": "烦恼", "is_correct": false, "explanation": "搭配：「关」一般不与「烦恼」搭配，不能说关掉烦恼。"}, {"text": "空气", "is_correct": false, "explanation": "语义：「空气」不是可以关掉的东西，句子不成立。"}, {"text": "树叶", "is_correct": false, "explanation": "语义：「树叶」不是可以关掉的东西，句子不成立。"}], "explanations": {"手机": "正确：「请把手机关了」指关掉手机，符合句意。", "烦恼": "搭配：「关」一般不与「烦恼」搭配，不能说关掉烦恼。", "空气": "语义：「空气」不是可以关掉的东西，句子不成立。", "树叶": "语义：「树叶」不是可以关掉的东西，句子不成立。"}, "sentence_index": 6, "correct_answer": "手机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一本手机。", "explanation": "这里应该用〈部〉。「本」多用于书籍、本子，手机不用「本」。"}, {"text": "他用手机做了一顿饭，很好吃。", "explanation": "这里把〈手机〉当成了炊具，手机是打电话、发信息的机器，不能用来做饭。"}, {"text": "他把手机穿在身上，很暖和。", "explanation": "这里把〈手机〉当成了衣服，手机是打电话、发信息的机器，不能穿在身上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e68fea7-3f48-4414-8e82-b156083ca382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20498, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张手机很新，也很轻。", "corrected_sentence": "这部手机很新，也很轻。", "error_description": "量词错误：错误形式为「张」，正确形式为「部」。「张」用于纸、桌子等平的东西，手机要用「部」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e68fea7-3f48-4414-8e82-b156083ca382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20498, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把手机被摔坏了，我要买一部新的。", "corrected_sentence": "我把手机摔坏了，我要买一部新的。", "error_description": "句式错误：「把」字句中不能再加「被」，「我把手机被摔坏了」应去掉「被」，写作「我把手机摔坏了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e68fea7-3f48-4414-8e82-b156083ca382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
