INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20500, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "吃药后身体出现的不好的感觉。", "primary_collocate": null, "pronunciation": "fù zuò yòng", "ipa": "fu˥˩ tswɔ˥˩ jʊŋ˥˩", "syllable_count": 3, "sentences": [{"text": "吃了药以后，我觉得很困，这是副作用。", "target_word": "副作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药的副作用是想睡觉。", "target_word": "副作用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他吃药后肚子疼，可能是副作用。", "target_word": "副作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说这药有副作用，要饭后吃。", "target_word": "副作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药的副作用让我一直想吐。", "target_word": "副作用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你吃药后有什么副作用吗？", "target_word": "副作用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她怕药的副作用，不敢多吃。", "target_word": "副作用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个药的副作用不大，只是有点口干。", "target_word": "副作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生问我：吃药后有没有副作用？", "target_word": "副作用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "感冒药的副作用是头晕。", "target_word": "副作用", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副作用：吃药后身体出现的不舒服的感觉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c708da23-8b74-483b-bea2-78da0da78450') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20500, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "副作用", "is_correct": true, "explanation": "副作用：吃药后身体出现的不舒服的感觉，与句中“很困”相符。"}, {"text": "疗效", "is_correct": false, "explanation": "语义：“疗效”指治疗的好效果，不能指“很困”这种不舒服的感觉。"}, {"text": "药方", "is_correct": false, "explanation": "语义：“药方”是开药的书面内容，不能用来说明身体的感觉。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”指身体的重量，不能用来说明困倦的感觉。"}], "explanations": {"副作用": "副作用：吃药后身体出现的不舒服的感觉，与句中“很困”相符。", "疗效": "语义：“疗效”指治疗的好效果，不能指“很困”这种不舒服的感觉。", "药方": "语义：“药方”是开药的书面内容，不能用来说明身体的感觉。", "体重": "搭配：“体重”指身体的重量，不能用来说明困倦的感觉。"}, "sentence_index": 0, "correct_answer": "副作用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他吃药后有了舒服的副作用。", "explanation": "这里应该用〈感觉〉。副作用指不好的感觉，不能用来形容舒服的感受。"}, {"text": "这种药的副作用很好，我的病很快就好了。", "explanation": "这里应该用〈疗效〉。副作用指吃药后身体出现的不舒服感觉，治好病的好效果要说疗效。"}, {"text": "这种药的副作用很快就见效了。", "explanation": "这里应该用〈药效〉。副作用指吃药后身体出现的不舒服感觉，药物很快起效要说药效。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9887ccc-ea02-4a69-9a01-abd713e7242c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20500, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "副作用", "is_correct": true, "explanation": "副作用：吃药后身体出现的不好的感觉，符合“她怕药的”后面的语义。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“她怕药的天气”不成立，天气与吃药的不适无关。"}, {"text": "工作", "is_correct": false, "explanation": "语义：“她怕药的工作”不成立，工作不是药物引起的感觉。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”指人的身体高度，不能与“怕”的对象搭配。"}], "explanations": {"副作用": "副作用：吃药后身体出现的不好的感觉，符合“她怕药的”后面的语义。", "天气": "语义：“她怕药的天气”不成立，天气与吃药的不适无关。", "工作": "语义：“她怕药的工作”不成立，工作不是药物引起的感觉。", "身高": "搭配：“身高”指人的身体高度，不能与“怕”的对象搭配。"}, "sentence_index": 6, "correct_answer": "副作用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种药的副作用含有很多钙。", "explanation": "这里应该用〈成分〉。副作用指吃药后身体出现的不舒服感觉，不是药物所含的物质，所含的物质要说成分。"}, {"text": "这项副作用让病人很快恢复了。", "explanation": "这里应该用〈治疗〉。副作用是不舒服的感觉，不能让病人恢复健康。"}, {"text": "医生的副作用很准确。", "explanation": "这里应该用〈诊断〉。“副作用”不能用来形容“准确”，准确的是诊断。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9887ccc-ea02-4a69-9a01-abd713e7242c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20500, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "吃药后我偶尔会有一些的副作用。", "corrected_sentence": "吃药后我偶尔会有一些副作用。", "error_description": "错误形式：“一些的副作用”；正确形式：“一些副作用”。“一些”是数量词，直接修饰名词，中间不能加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9887ccc-ea02-4a69-9a01-abd713e7242c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20500, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "吃这种药要注意一只副作用。", "corrected_sentence": "吃这种药要注意一种副作用。", "error_description": "错误形式：“一只副作用”；正确形式：“一种副作用”。“只”用于动物或成对的物件，“副作用”要用量词“种”或“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9887ccc-ea02-4a69-9a01-abd713e7242c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20502, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "次要", "is_correct": true, "explanation": "反义：「次要」指不太重要，与「意思很大、很要紧」相反。"}, {"text": "明亮", "is_correct": false, "explanation": "无关：「明亮」形容光线或颜色，与「重要」没有反义关系。"}, {"text": "陈旧", "is_correct": false, "explanation": "无关：「陈旧」指过时、破旧，与「重要」的意义没有反义关系。"}, {"text": "清脆", "is_correct": false, "explanation": "无关：「清脆」形容声音，与「重要」没有反义关系。"}], "correct_answer": "次要", "explanations": {"次要": "反义：「次要」指不太重要，与「意思很大、很要紧」相反。", "明亮": "无关：「明亮」形容光线或颜色，与「重要」没有反义关系。", "陈旧": "无关：「陈旧」指过时、破旧，与「重要」的意义没有反义关系。", "清脆": "无关：「清脆」形容声音，与「重要」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf547d32-8b5d-4cb6-ba99-fc20c022708c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
