INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20502, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "意思很大，很要紧。", "primary_collocate": null, "pronunciation": "zhòng yào", "ipa": "ʈʂʊŋ˥˩ jaʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这件事对我很重要。", "target_word": "重要", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "睡觉对身体非常重要。", "target_word": "重要", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "最重要的是你开心。", "target_word": "重要", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今天有一个重要的会议。", "target_word": "重要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学好汉语的重要方法是多说。", "target_word": "重要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这封信很重要，请别丢了。", "target_word": "重要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在公司里的位置很重要。", "target_word": "重要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "家人比钱重要。", "target_word": "重要", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "考试前，复习最重要。", "target_word": "重要", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这是一个重要的日子，我们去吃大餐。", "target_word": "重要", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "作用或意义很大、很要紧", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '305dd323-afa7-44a8-b982-43b80d121d49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20502, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "重要", "is_correct": true, "explanation": "正确：「重要」读作 zhòng yào，意思是意义大、很要紧。"}, {"text": "中药", "is_correct": false, "explanation": "zhōng（第一声）与 zhòng（第四声）声调不同，意思是中药。"}, {"text": "总要", "is_correct": false, "explanation": "zǒng 与 zhòng 声母、声调都不同，意思是总得、总是要。"}, {"text": "正要", "is_correct": false, "explanation": "zhèng 与 zhòng 韵母不同（eng 与 ong），意思是正要、刚要。"}], "explanations": {"重要": "正确：「重要」读作 zhòng yào，意思是意义大、很要紧。", "中药": "zhōng（第一声）与 zhòng（第四声）声调不同，意思是中药。", "总要": "zǒng 与 zhòng 声母、声调都不同，意思是总得、总是要。", "正要": "zhèng 与 zhòng 韵母不同（eng 与 ong），意思是正要、刚要。"}, "sentence_index": null, "correct_answer": "重要"}, "level_3": {"options": [{"text": "重要", "is_correct": true, "explanation": "正确：「重要」表示很要紧，「这件事对我很重要」符合句意。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：「明亮」说光线、颜色，不说事情对人的意义。"}, {"text": "陈旧", "is_correct": false, "explanation": "语义：「陈旧」指过时、破旧，与「这件事对我」的意义说不通。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：「清脆」形容声音，不能用来说事情的份量。"}], "explanations": {"重要": "正确：「重要」表示很要紧，「这件事对我很重要」符合句意。", "明亮": "搭配：「明亮」说光线、颜色，不说事情对人的意义。", "陈旧": "语义：「陈旧」指过时、破旧，与「这件事对我」的意义说不通。", "清脆": "搭配：「清脆」形容声音，不能用来说事情的份量。"}, "sentence_index": 0, "correct_answer": "重要"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个箱子很重要，我一个人搬不动。", "explanation": "这里应该用〈重〉。重指分量大，搬不动说明分量重；重要说事物的意义，不能用来形容分量。"}, {"text": "我们应该重要学习汉语。", "explanation": "这里应该用〈重视〉。重要是形容词，不能带宾语；看重某事要用重视。"}, {"text": "这件衣服太重要了，我买不起。", "explanation": "这里应该用〈贵〉。买不起说明价格高，应说贵；重要说事物的意义，不能用来形容价格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf547d32-8b5d-4cb6-ba99-fc20c022708c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20502, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重要", "is_correct": true, "explanation": "正确：「重要」指位置对工作或发展的作用很大，「他在公司里的位置很重要」符合句意。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：「高大」形容人或物体的外形，不能用来形容位置的作用。"}, {"text": "柔软", "is_correct": false, "explanation": "搭配：「柔软」说质地，不说位置很柔软。"}, {"text": "湿润", "is_correct": false, "explanation": "搭配：「湿润」形容空气、土壤或皮肤，不用于说公司里的位置。"}], "explanations": {"重要": "正确：「重要」指位置对工作或发展的作用很大，「他在公司里的位置很重要」符合句意。", "高大": "体貌：「高大」形容人或物体的外形，不能用来形容位置的作用。", "柔软": "搭配：「柔软」说质地，不说位置很柔软。", "湿润": "搭配：「湿润」形容空气、土壤或皮肤，不用于说公司里的位置。"}, "sentence_index": 6, "correct_answer": "重要"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这里的噪音很重要，夜里很难睡。", "explanation": "这里应该用〈严重〉。噪音的程度说严重，重要说事物的意义，不能用来形容噪音。"}, {"text": "这箱书很重要，他一个人搬不动。", "explanation": "这里应该用〈重〉。重指分量大，搬不动说明分量重；重要不能用来形容分量。"}, {"text": "他感冒得很重要，整天躺在床上。", "explanation": "这里应该用〈严重〉。感冒的程度说严重，重要不能用来形容病的轻重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf547d32-8b5d-4cb6-ba99-fc20c022708c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20502, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份工作把他的未来很重要。", "corrected_sentence": "这份工作对他的未来很重要。", "error_description": "介词错误：「重要」是形容词，不能用「把」字句引出它的对象，应用介词「对」，说「对他的未来很重要」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf547d32-8b5d-4cb6-ba99-fc20c022708c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20502, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一个重要地决定，要慎重考虑。", "corrected_sentence": "这是一个重要的决定，要慎重考虑。", "error_description": "的地混用：「重要」修饰名词时要用「的」，不用「地」（「地」用于修饰动词或作状语）。应说「重要的决定」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf547d32-8b5d-4cb6-ba99-fc20c022708c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
