INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20504, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "能带来根本性改变的特性。", "primary_collocate": null, "pronunciation": "gé mìng xìng", "ipa": "kɤ³⁵ miŋ⁵¹ ɕiŋ⁵¹", "syllable_count": 3, "sentences": [{"text": "这项新技术很有革命性。", "target_word": "革命性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机的出现具有革命性的意义。", "target_word": "革命性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药的革命性在于治疗时间短。", "target_word": "革命性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他提出了一个有革命性的想法。", "target_word": "革命性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "印刷术的革命性在于，书可以大量生产。", "target_word": "革命性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑的革命性让工作方式变了。", "target_word": "革命性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的新产品没有什么革命性。", "target_word": "革命性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说，这次改革有革命性的意义。", "target_word": "革命性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个发明的革命性，大家一开始都没看出来。", "target_word": "革命性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器的革命性，是它能自己学习。", "target_word": "革命性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "带来根本性改变的特性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d56d81d-7b32-4ed2-b81f-faaa77360a2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20504, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "革命性", "is_correct": true, "explanation": "「革命性」指带来根本改变的特性，放在「很有」后面，符合句意。"}, {"text": "保守性", "is_correct": false, "explanation": "语义：「保守性」指守旧，与「新技术」的新颖相反。"}, {"text": "季节性", "is_correct": false, "explanation": "搭配：「季节性」多用于农产品、天气等随季节变化的事物，不用来形容新技术。"}, {"text": "地域性", "is_correct": false, "explanation": "语义：「地域性」指受地方限制的特点，与「新技术」的描述不搭。"}], "explanations": {"革命性": "「革命性」指带来根本改变的特性，放在「很有」后面，符合句意。", "保守性": "语义：「保守性」指守旧，与「新技术」的新颖相反。", "季节性": "搭配：「季节性」多用于农产品、天气等随季节变化的事物，不用来形容新技术。", "地域性": "语义：「地域性」指受地方限制的特点，与「新技术」的描述不搭。"}, "sentence_index": 0, "correct_answer": "革命性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每次比赛都很拼，革命性很强。", "explanation": "这里应该用〈干劲〉。革命性指带来根本改变的性质，不指做事的积极性；形容人做事用力要说干劲。"}, {"text": "这座老房子的革命性很长，已经有两百年了。", "explanation": "这里应该用〈历史〉。革命性指带来根本改变，不指存在的时间；说建筑存在了多久要用历史。"}, {"text": "这件衣服的革命性很便宜，只要十块钱。", "explanation": "这里应该用〈价格〉。革命性指根本性的改变，不指价钱高低；说东西便宜要说价格低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b664e9ad-97d3-45f2-b78a-e8211ea03883') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20504, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "革命性", "is_correct": true, "explanation": "「革命性」指带来根本改变的特性，放在「没有什么」后面，符合句意。"}, {"text": "阶级性", "is_correct": false, "explanation": "语域：「阶级性」是政治术语，用来形容公司的产品很突兀。"}, {"text": "思想性", "is_correct": false, "explanation": "语义：「思想性」指作品或理论的思想内容，不是产品的特点。"}, {"text": "宗教性", "is_correct": false, "explanation": "搭配：「宗教性」多用于宗教活动和场所，不用来形容产品。"}], "explanations": {"革命性": "「革命性」指带来根本改变的特性，放在「没有什么」后面，符合句意。", "阶级性": "语域：「阶级性」是政治术语，用来形容公司的产品很突兀。", "思想性": "语义：「思想性」指作品或理论的思想内容，不是产品的特点。", "宗教性": "搭配：「宗教性」多用于宗教活动和场所，不用来形容产品。"}, "sentence_index": 6, "correct_answer": "革命性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这杯咖啡的革命性很烫，我没法喝。", "explanation": "这里应该用〈温度〉。革命性指根本改变，不指冷热；描述咖啡烫不烫要说温度。"}, {"text": "这个箱子的革命性很大，装不下衣服。", "explanation": "这里应该用〈体积〉。革命性指根本改变，不指大小；箱子大不大、能装多少要说体积。"}, {"text": "这辆车的革命性很快，五分钟就到了。", "explanation": "这里应该用〈速度〉。革命性指根本改变，不指快慢；说车跑得快要用速度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b664e9ad-97d3-45f2-b78a-e8211ea03883') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20504, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个方案很革命性，值得试一试。", "corrected_sentence": "这个方案很有革命性，值得试一试。", "error_description": "错误：「很革命性」；正确：「很有革命性」。「革命性」是名词，前面要加「有」，不能直接用「很」修饰。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b664e9ad-97d3-45f2-b78a-e8211ea03883') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20504, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个团队提出了一个有革命性方案。", "corrected_sentence": "这个团队提出了一个有革命性的方案。", "error_description": "错误：「有革命性方案」漏了「的」；正确：「有革命性的方案」。「革命性」作定语修饰名词时，后面要加「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b664e9ad-97d3-45f2-b78a-e8211ea03883') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
