INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20506, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人们把新闻印在大张纸上，这种纸就叫报纸。", "primary_collocate": null, "pronunciation": "bào zhǐ", "ipa": "pɑʊ˥˩ ʈʂɿ˨˩˦", "syllable_count": 2, "sentences": [{"text": "爸爸每天早上都看报纸。", "target_word": "报纸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报纸今天有很多新闻。", "target_word": "报纸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在车站买了一份报纸。", "target_word": "报纸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上放着一张旧报纸。", "target_word": "报纸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢一边喝茶一边读报纸。", "target_word": "报纸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在很少有人买报纸了。", "target_word": "报纸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用旧报纸包着水果。", "target_word": "报纸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上说明天会下大雨。", "target_word": "报纸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷订了一年的报纸。", "target_word": "报纸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸的头版是一条重要新闻。", "target_word": "报纸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "张", "label": "量词"}, {"form": "報紙", "label": "繁体"}], "register": "中性", "sense_fingerprint": "印着新闻的大张纸，每天或定期出版的读物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e64b3b0f-81c3-4b52-bcde-e97b5fd7793c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20506, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "报纸", "is_correct": true, "explanation": "正确答案。报纸（bào zhǐ）指印着新闻、定期出版的大张纸。"}, {"text": "报时", "is_correct": false, "explanation": "报时（bào shí）与报纸的第二音节声母不同（shí 与 zhǐ），声调也不同，意思是报告时间。"}, {"text": "白纸", "is_correct": false, "explanation": "白纸（bái zhǐ）与报纸的第一音节韵母不同（ái 与 ào），声调也不同，意思是白色的纸。"}, {"text": "薄纸", "is_correct": false, "explanation": "薄纸（báo zhǐ）只有第一音节声调不同（第二声与第四声），意思是薄的纸。"}, {"text": "保质", "is_correct": false, "explanation": "保质（bǎo zhì）两个音节的声调都与报纸不同，意思是保证质量。"}], "explanations": {"报纸": "正确答案。报纸（bào zhǐ）指印着新闻、定期出版的大张纸。", "报时": "报时（bào shí）与报纸的第二音节声母不同（shí 与 zhǐ），声调也不同，意思是报告时间。", "白纸": "白纸（bái zhǐ）与报纸的第一音节韵母不同（ái 与 ào），声调也不同，意思是白色的纸。", "薄纸": "薄纸（báo zhǐ）只有第一音节声调不同（第二声与第四声），意思是薄的纸。", "保质": "保质（bǎo zhì）两个音节的声调都与报纸不同，意思是保证质量。"}, "sentence_index": null, "correct_answer": "报纸"}, "level_3": {"options": [{"text": "牛奶", "is_correct": false, "explanation": "搭配：“看”搭配可以阅读或观看的对象，不说“看牛奶”，句中不成立。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包是食物，早上应该吃，不是“看”的对象。"}, {"text": "报纸", "is_correct": true, "explanation": "正确答案。“看报纸”指阅读报纸，符合句中“看”的动作。"}, {"text": "牙刷", "is_correct": false, "explanation": "语义：牙刷是日用品，不是可以阅读或观看的东西，句意不通。"}], "explanations": {"牛奶": "搭配：“看”搭配可以阅读或观看的对象，不说“看牛奶”，句中不成立。", "面包": "语义：面包是食物，早上应该吃，不是“看”的对象。", "报纸": "正确答案。“看报纸”指阅读报纸，符合句中“看”的动作。", "牙刷": "语义：牙刷是日用品，不是可以阅读或观看的东西，句意不通。"}, "sentence_index": 0, "correct_answer": "报纸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只报纸。", "explanation": "这里应该用〈份〉或〈张〉。〈只〉多用于动物，报纸不能用“只”来数。"}, {"text": "我在广播里听了今天的报纸。", "explanation": "这里应该用〈新闻〉。广播里“听”的是新闻，报纸是纸质印刷品，应该说“看报纸”。"}, {"text": "我在路上捡到了一棵报纸。", "explanation": "这里应该用〈张〉。〈棵〉用于树木等植物，不能用来数报纸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20506, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是乐器，不能用来包裹水果，句意不通。"}, {"text": "墨水", "is_correct": false, "explanation": "搭配：“包”的对象要能包裹东西，墨水是液体，不说用墨水包水果。"}, {"text": "报纸", "is_correct": true, "explanation": "正确答案。“用旧报纸包着水果”指用旧报纸包裹水果，符合句意。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板又大又硬，不能用来包裹水果，句意不通。"}], "explanations": {"钢琴": "语义：钢琴是乐器，不能用来包裹水果，句意不通。", "墨水": "搭配：“包”的对象要能包裹东西，墨水是液体，不说用墨水包水果。", "报纸": "正确答案。“用旧报纸包着水果”指用旧报纸包裹水果，符合句意。", "黑板": "语义：黑板又大又硬，不能用来包裹水果，句意不通。"}, "sentence_index": 6, "correct_answer": "报纸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "电视台播出了今天的报纸。", "explanation": "这里应该用〈报道〉。电视台“播出”的是新闻报道，报纸是印刷品，不能播出。"}, {"text": "他早上吃了今天的报纸。", "explanation": "这里应该用〈面包〉。“吃”的是食物，报纸是印刷品，不能吃。"}, {"text": "他今天穿的报纸很漂亮。", "explanation": "这里应该用〈衣服〉。“穿”的是衣物，报纸不能穿在身上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20506, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我早上买了一本报纸。", "corrected_sentence": "我早上买了一份报纸。", "error_description": "量词错误：报纸的量词应为“份”或“张”。“本”用于书籍，不能说“一本报纸”，应改为“一份报纸”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20506, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爷爷每天早上都在报纸上听新闻。", "corrected_sentence": "爷爷每天早上都在报纸上看新闻。", "error_description": "动词错误：报纸是印刷品，看新闻要用“看”，不能说“听”，应改为“在报纸上看新闻”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
