INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20510, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情变得不一样的那个时候。", "primary_collocate": null, "pronunciation": "zhuǎn zhé diǎn", "ipa": "ʈʂwan˨˩ ʈʂɤ˧˥ tjɛn˨˩", "syllable_count": 3, "sentences": [{"text": "这次考试是他学习的转折点。", "target_word": "转折点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那一年是公司发展的转折点。", "target_word": "转折点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "搬到北京是我生活的一个转折点。", "target_word": "转折点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这场比赛成了球队的转折点。", "target_word": "转折点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "遇到那位老师，是她人生的转折点。", "target_word": "转折点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "生病那一年成了他一生的转折点。", "target_word": "转折点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个消息是整个故事的转折点。", "target_word": "转折点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说，这几天是病情的转折点。", "target_word": "转折点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战争在这一年到了转折点。", "target_word": "转折点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们终于等到了市场的转折点。", "target_word": "转折点", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "轉折點", "label": "繁体"}, {"form": "一个转折点", "label": "量词"}], "register": "中性", "sense_fingerprint": "事情发生变化的关键时刻", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb662756-0b78-4edf-9c5e-051c04c57dff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20510, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "转折点", "is_correct": true, "explanation": "正确答案。“转折点”指事情变化的关键时刻，与“这次考试是他学习的”搭配。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是家用电器，不能作“学习”的阶段或时刻。"}, {"text": "饭馆", "is_correct": false, "explanation": "语义：“饭馆”指餐饮场所，与“学习的”搭配不通。"}, {"text": "手套", "is_correct": false, "explanation": "搭配：“学习的”后不接“手套”，这个句子无法成立。"}], "explanations": {"转折点": "正确答案。“转折点”指事情变化的关键时刻，与“这次考试是他学习的”搭配。", "冰箱": "语义：“冰箱”是家用电器，不能作“学习”的阶段或时刻。", "饭馆": "语义：“饭馆”指餐饮场所，与“学习的”搭配不通。", "手套": "搭配：“学习的”后不接“手套”，这个句子无法成立。"}, "sentence_index": 0, "correct_answer": "转折点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个转折点很好吃，我还想再吃一个。", "explanation": "“转折点”指事情变化的关键时刻，不是食物，不能说“好吃”，这里误用了它的含义。"}, {"text": "我把转折点放进了书包里。", "explanation": "“转折点”是抽象的时刻，不是能拿在手里的东西，不能“放进书包”。"}, {"text": "这个转折点有三米长，很重。", "explanation": "“转折点”指关键时刻，没有长度和重量，这里误用了它的含义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ba7baf-aaec-45a2-9742-dd8089de9ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20510, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "转折点", "is_correct": true, "explanation": "正确答案。“转折点”指事情变化的关键时刻，与“这个消息是整个故事的”搭配。"}, {"text": "卡车", "is_correct": false, "explanation": "语义：“卡车”是运输工具，不能作故事的关键时刻。"}, {"text": "地毯", "is_correct": false, "explanation": "语义：“地毯”是铺在地上的织物，不能指故事的转折。"}, {"text": "白菜", "is_correct": false, "explanation": "搭配：“白菜”与“整个故事的”搭配不通。"}], "explanations": {"转折点": "正确答案。“转折点”指事情变化的关键时刻，与“这个消息是整个故事的”搭配。", "卡车": "语义：“卡车”是运输工具，不能作故事的关键时刻。", "地毯": "语义：“地毯”是铺在地上的织物，不能指故事的转折。", "白菜": "搭配：“白菜”与“整个故事的”搭配不通。"}, "sentence_index": 6, "correct_answer": "转折点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次旅行的转折点很便宜，我们花的钱不多。", "explanation": "“转折点”指事情变化的关键时刻，不能用来形容价格；说东西便宜应用于商品等具体的东西。"}, {"text": "他一口气吃完了那个转折点。", "explanation": "“转折点”指关键时刻，不能被吃掉；“吃完”要求宾语是食物，这里误用了“转折点”的含义。"}, {"text": "他的转折点跑得很快。", "explanation": "“转折点”指关键时刻，不是能跑动的事物，不能说“跑得很快”，这里误用了它的含义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ba7baf-aaec-45a2-9742-dd8089de9ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20510, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是他人生的一棵转折点。", "corrected_sentence": "这是他人生的一个转折点。", "error_description": "量词错误：“棵”用于树木等植物，不能修饰“转折点”，正确为“一个转折点”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ba7baf-aaec-45a2-9742-dd8089de9ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20510, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次合作是公司发展的一根转折点。", "corrected_sentence": "这次合作是公司发展的一个转折点。", "error_description": "量词错误：“根”用于细长的东西，不能修饰“转折点”，正确为“一个转折点”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ba7baf-aaec-45a2-9742-dd8089de9ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
