INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20512, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "技术是做好事情的方法。", "primary_collocate": null, "pronunciation": "jì shù", "ipa": "tɕi˥˩ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "他的电脑技术很好。", "target_word": "技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司有先进的技术。", "target_word": "技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学游泳要先学基本技术。", "target_word": "技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新技术让工作变得简单。", "target_word": "技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他踢球的技术比我好。", "target_word": "技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想学做面包的技术。", "target_word": "技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项技术可以省很多时间。", "target_word": "技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生的技术好，病人很放心。", "target_word": "技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个工厂用了新技术。", "target_word": "技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画画不只要有技术，还要有想法。", "target_word": "技术", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "技術", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做好某件事所需的方法和本领", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662c7823-51e1-46b7-b4e3-759c04a652e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20512, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "技术", "is_correct": true, "explanation": "技术：做好事情的方法和本领。"}, {"text": "季度", "is_correct": false, "explanation": "shù 与 dù 的声母不同（sh 与 d），“季度”指一年中的一个时间段，如第一季度。"}, {"text": "寄书", "is_correct": false, "explanation": "shū（第一声）与 shù（第四声）声调不同，“寄书”指把书邮寄出去。"}, {"text": "集数", "is_correct": false, "explanation": "jí（第二声）与 jì（第四声）声调不同，“集数”指电视剧等作品的集数。"}], "explanations": {"技术": "技术：做好事情的方法和本领。", "季度": "shù 与 dù 的声母不同（sh 与 d），“季度”指一年中的一个时间段，如第一季度。", "寄书": "shū（第一声）与 shù（第四声）声调不同，“寄书”指把书邮寄出去。", "集数": "jí（第二声）与 jì（第四声）声调不同，“集数”指电视剧等作品的集数。"}, "sentence_index": null, "correct_answer": "技术"}, "level_3": {"options": [{"text": "技术", "is_correct": true, "explanation": "“技术”指做好事情的方法和本领，他的电脑技术很好，填入后句意通顺。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指人或动物的身体高度，电脑没有身高。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指人的性情，不能用来形容电脑。"}, {"text": "感情", "is_correct": false, "explanation": "搭配：“感情很好”用于人与人之间，不能用来形容电脑。"}], "explanations": {"技术": "“技术”指做好事情的方法和本领，他的电脑技术很好，填入后句意通顺。", "身高": "语义：“身高”指人或动物的身体高度，电脑没有身高。", "脾气": "语义：“脾气”指人的性情，不能用来形容电脑。", "感情": "搭配：“感情很好”用于人与人之间，不能用来形容电脑。"}, "sentence_index": 0, "correct_answer": "技术"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把锤子是修车的技术。", "explanation": "这里应该用〈工具〉。“技术”指做事的方法和本领，锤子这样的器物要用“工具”。"}, {"text": "妈妈把技术放进了冰箱。", "explanation": "这里应该用〈食物〉。“技术”指做事的方法和本领，不是能放进冰箱的东西，放进冰箱的应该是“食物”。"}, {"text": "他吃了一碗技术。", "explanation": "这里应该用〈面条〉。“技术”指做事的方法和本领，不是食物，不能用“吃”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb92d47d-b163-42b2-9991-7720f4cd034a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20512, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "技术", "is_correct": true, "explanation": "“技术”指做好事情的方法和本领，这项技术可以省很多时间，填入后句意通顺。"}, {"text": "荣誉", "is_correct": false, "explanation": "语义：“荣誉”是得到的表彰，不能帮人省时间。"}, {"text": "疾病", "is_correct": false, "explanation": "语义：“疾病”指身体的毛病，与省时间无关。"}, {"text": "爱好", "is_correct": false, "explanation": "搭配：“省很多时间”的主语应是做事的方法或工具，不能与“爱好”搭配。"}], "explanations": {"技术": "“技术”指做好事情的方法和本领，这项技术可以省很多时间，填入后句意通顺。", "荣誉": "语义：“荣誉”是得到的表彰，不能帮人省时间。", "疾病": "语义：“疾病”指身体的毛病，与省时间无关。", "爱好": "搭配：“省很多时间”的主语应是做事的方法或工具，不能与“爱好”搭配。"}, "sentence_index": 6, "correct_answer": "技术"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首诗充满了技术。", "explanation": "这里应该用〈灵感〉。“充满”后接情感或想法，“技术”不能用“充满”来形容。"}, {"text": "这位厨师做了一桌好技术。", "explanation": "这里应该用〈菜〉。“菜”是做好的食物，“技术”指做事的方法，不能说做出一桌“技术”。"}, {"text": "这幅画的技术很鲜艳。", "explanation": "这里应该用〈颜色〉。“鲜艳”用来形容颜色，“技术”不能是鲜艳的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb92d47d-b163-42b2-9991-7720f4cd034a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20512, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他学会了一件新技术。", "corrected_sentence": "他学会了一项新技术。", "error_description": "量词错误：“技术”应用量词“项”，写成“件”不对，“件”多用于衣物、事情等具体物品。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb92d47d-b163-42b2-9991-7720f4cd034a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20512, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他对这只技术很有信心。", "corrected_sentence": "他对这门技术很有信心。", "error_description": "量词错误：“技术”应用量词“门”或“项”，不能用“只”（“只”多用于动物或成对的东西）。正确说法：这门技术。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb92d47d-b163-42b2-9991-7720f4cd034a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
