INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20514, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "雕版是在木板上刻字或画，用来印书。", "primary_collocate": null, "pronunciation": "diāo bǎn", "ipa": "tjɑʊ̯˥ pan˨˩˦", "syllable_count": 2, "sentences": [{"text": "这块雕版很旧了，上面的字还很清楚。", "target_word": "雕版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代人用雕版印书。", "target_word": "雕版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有一块宋代的雕版。", "target_word": "雕版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想看看雕版是怎么印出书来的。", "target_word": "雕版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人在木板上刻字，做成雕版。", "target_word": "雕版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书是用雕版印的，不是用机器印的。", "target_word": "雕版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅把墨涂在雕版上，再盖上纸。", "target_word": "雕版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刻一块雕版要花很长时间。", "target_word": "雕版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在书店买了一本介绍雕版的书。", "target_word": "雕版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雕版用久了，字会变得不清楚。", "target_word": "雕版", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "雕版印刷", "label": "复合"}], "register": "书面", "sense_fingerprint": "木板上刻字或画、用来印书的印版", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c13fba2-698e-4727-b25b-42f4c360e701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20514, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "雕版", "is_correct": true, "explanation": "正确：雕版是刻有字的木板，可以“很旧”，上面的字还能看清楚。"}, {"text": "冰", "is_correct": false, "explanation": "语义：冰会融化，刻不了字，也谈不上“上面的字还很清楚”。"}, {"text": "煤", "is_correct": false, "explanation": "语义：煤上不会刻字，“上面的字还很清楚”不成立。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：“很旧”多用于器物，面包通常说“放久了”，不说“很旧”。"}], "explanations": {"雕版": "正确：雕版是刻有字的木板，可以“很旧”，上面的字还能看清楚。", "冰": "语义：冰会融化，刻不了字，也谈不上“上面的字还很清楚”。", "煤": "语义：煤上不会刻字，“上面的字还很清楚”不成立。", "面包": "搭配：“很旧”多用于器物，面包通常说“放久了”，不说“很旧”。"}, "sentence_index": 0, "correct_answer": "雕版"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在博物馆看到一本雕版。", "explanation": "这里应该用〈块〉。〈本〉用于书，雕版是刻字的木板，应该用〈块〉。"}, {"text": "他用雕版煮面条。", "explanation": "这里应该用〈锅〉。雕版是印书用的木板，不能用来煮面，煮面要用〈锅〉。"}, {"text": "我在街上捡到一只雕版。", "explanation": "这里应该用〈块〉。〈只〉用于动物，雕版是木板，不能用“一只”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb992c-4cb3-4d2d-b363-c122f580b353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20514, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雕版", "is_correct": true, "explanation": "正确：墨要涂在有字的版面上，再盖纸印出，句子成立。"}, {"text": "冰", "is_correct": false, "explanation": "语义：墨不能涂在会融化的冰上，再盖纸也印不出字。"}, {"text": "水", "is_correct": false, "explanation": "语义：水没有可以承墨的表面，“涂在水上”不成立。"}, {"text": "空气", "is_correct": false, "explanation": "配价：“涂”要求有可以承受涂抹的表面，空气不能。"}], "explanations": {"雕版": "正确：墨要涂在有字的版面上，再盖纸印出，句子成立。", "冰": "语义：墨不能涂在会融化的冰上，再盖纸也印不出字。", "水": "语义：水没有可以承墨的表面，“涂在水上”不成立。", "空气": "配价：“涂”要求有可以承受涂抹的表面，空气不能。"}, "sentence_index": 6, "correct_answer": "雕版"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了一座雕版。", "explanation": "这里应该用〈块〉。〈座〉用于山、楼等大型固定物，雕版是木板，应该用〈块〉。"}, {"text": "他把一盏雕版带回了家。", "explanation": "这里应该用〈块〉。〈盏〉用于灯，雕版不能用“一盏”。"}, {"text": "他在桌子上放了一把雕版。", "explanation": "这里应该用〈块〉。〈把〉用于有柄的器具，雕版不能用“一把”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb992c-4cb3-4d2d-b363-c122f580b353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20514, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那台雕版是宋朝留下的。", "corrected_sentence": "那块雕版是宋朝留下的。", "error_description": "量词错误：雕版是块状的木板，应用〈块〉，〈台〉用于机器，不能用于雕版。错误形式“那台雕版”，正确形式“那块雕版”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb992c-4cb3-4d2d-b363-c122f580b353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20514, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他买了两块雕版们。", "corrected_sentence": "他买了两块雕版。", "error_description": "错误在于“雕版”后多加了复数词尾“们”。“两块”已表示数量，名词后不能再加“们”，应说“两块雕版”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb992c-4cb3-4d2d-b363-c122f580b353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
