INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20516, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "非常，特别，比‘很’还要厉害。", "primary_collocate": null, "pronunciation": "jí dù", "ipa": "tɕi˧˥ tu˥˩", "syllable_count": 2, "sentences": [{"text": "他今天极度疲劳。", "target_word": "极度", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "比赛前，我极度紧张。", "target_word": "极度", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这里极度危险，别进去。", "target_word": "极度", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "沙漠里极度缺水。", "target_word": "极度", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "听到这个消息，她极度失望。", "target_word": "极度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看到大狗，孩子极度害怕。", "target_word": "极度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一晚没睡，今天极度困倦。", "target_word": "极度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他极度讨厌别人说谎。", "target_word": "极度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气极度干燥，大家都要多喝水。", "target_word": "极度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为压力太大，他最近的精神极度疲惫。", "target_word": "极度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "副词：程度极高，比“很”更强", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9421cf6-24de-499f-a0bb-a94d3893ac19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20516, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "极度", "is_correct": true, "explanation": "正确：极度表示程度极深，与“疲劳”搭配自然。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”指过去，与“今天”矛盾，句子说不通。"}, {"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示一直不这样，与“今天”这个具体时间冲突。"}, {"text": "不断", "is_correct": false, "explanation": "搭配：“不断”修饰持续的动作，不能修饰疲劳这种状态。"}], "explanations": {"极度": "正确：极度表示程度极深，与“疲劳”搭配自然。", "曾经": "语义：“曾经”指过去，与“今天”矛盾，句子说不通。", "从不": "语义：“从不”表示一直不这样，与“今天”这个具体时间冲突。", "不断": "搭配：“不断”修饰持续的动作，不能修饰疲劳这种状态。"}, "sentence_index": 0, "correct_answer": "极度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把椅子是极度木制的。", "explanation": "这里应该用〈完全〉。极度表示程度，不能修饰“木制”这类表示材质的词，应说完全木制。"}, {"text": "这朵花极度开了三天。", "explanation": "这里应该用〈整整〉。极度表示程度，不能说明时间的长短，应说整整开了三天。"}, {"text": "她极度拿了三次奖。", "explanation": "这里应该用〈多次〉。极度表示程度，不能修饰动作的次数，应说多次拿奖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20516, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "极度", "is_correct": true, "explanation": "正确：极度表示程度极深，与“一晚没睡”后的困倦相符。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作正在进行，困倦是状态，不能说正在困倦。"}, {"text": "幸好", "is_correct": false, "explanation": "语义：“幸好”表示庆幸的好事，困倦不是好事，句子说不通。"}, {"text": "拼命", "is_correct": false, "explanation": "搭配：“拼命”修饰用力的动作，不能修饰困倦这种状态。"}], "explanations": {"极度": "正确：极度表示程度极深，与“一晚没睡”后的困倦相符。", "正在": "体貌：“正在”表示动作正在进行，困倦是状态，不能说正在困倦。", "幸好": "语义：“幸好”表示庆幸的好事，困倦不是好事，句子说不通。", "拼命": "搭配：“拼命”修饰用力的动作，不能修饰困倦这种状态。"}, "sentence_index": 6, "correct_answer": "极度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他极度老师。", "explanation": "这里应该用〈是〉。极度是程度副词，不能直接作谓语，应说“他是老师”。"}, {"text": "这场雨极度下了三天。", "explanation": "这里应该用〈足足〉。极度表示程度，不能说明时间的长短，应说足足下了三天。"}, {"text": "这部电影极度拍了三次。", "explanation": "这里应该用〈重新〉。极度表示程度，不能修饰拍摄的次数，应说重新拍了三次。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20516, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个房间很极度闷热。", "corrected_sentence": "这个房间极度闷热。", "error_description": "程度副词叠用：“很”和“极度”都表示程度，不能叠用，应去掉“很”，说“这个房间极度闷热”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20516, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "连续加班以后，她最极度疲倦。", "corrected_sentence": "连续加班以后，她极度疲倦。", "error_description": "程度副词叠用：“最”和“极度”都表示程度，不能叠用，应说“她极度疲倦”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
