INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20518, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "活字是印刷用的单个字块。", "primary_collocate": null, "pronunciation": "huó zì", "ipa": "xwɔ˧˥ tsɨ˥˩", "syllable_count": 2, "sentences": [{"text": "工人把一个个活字排在木盘里。", "target_word": "活字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些铅制的活字已经用了几十年。", "target_word": "活字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕昇用泥做活字，印出了第一本书。", "target_word": "活字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "印书以前，师傅先要挑好需要的活字。", "target_word": "活字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个活字只有一个字，可以反复使用。", "target_word": "活字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里放着很多木头做的活字。", "target_word": "活字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他小心地从盒子里拿出一个活字。", "target_word": "活字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了活字，印书比刻整块板快多了。", "target_word": "活字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "活字太小了，我一不小心就弄丢了几个。", "target_word": "活字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家老印刷厂还保存着几千个活字。", "target_word": "活字", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个活字", "label": "量词（个）"}, {"form": "木活字", "label": "复合"}, {"form": "铅活字", "label": "复合"}, {"form": "活字印刷", "label": "复合"}], "register": "中性", "sense_fingerprint": "印刷时用来排版的单个字块", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c4848e3-df86-4870-9771-0c70385a07a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20518, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "活字", "is_correct": true, "explanation": "正确：活字是印刷用的单个字块，可以一个个排进木盘。"}, {"text": "纸张", "is_correct": false, "explanation": "搭配：“纸张”是不可数名词，不能用“一个个”计数。"}, {"text": "海浪", "is_correct": false, "explanation": "语义：海浪是自然现象，工人无法把它排进木盘。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，不能被工人拿来排在木盘里。"}], "explanations": {"活字": "正确：活字是印刷用的单个字块，可以一个个排进木盘。", "纸张": "搭配：“纸张”是不可数名词，不能用“一个个”计数。", "海浪": "语义：海浪是自然现象，工人无法把它排进木盘。", "月亮": "语义：月亮是天体，不能被工人拿来排在木盘里。"}, "sentence_index": 0, "correct_answer": "活字"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天拿几个活字回家，当作课本来读。", "explanation": "这里应该用〈课本〉。活字是印刷用的字块，不能当作印好的书来阅读，“课本”才是可以阅读的印刷品。"}, {"text": "他每天在本子上写活字。", "explanation": "这里应该用〈汉字〉。活字是印刷用的字块，不能用笔写，“写”要搭配文字。"}, {"text": "我每天都查活字，记住新词。", "explanation": "这里应该用〈字典〉。活字是字块，不是可以查询的工具书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a60b13-703b-4e62-85a9-0f05821c45f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20518, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "活字", "is_correct": true, "explanation": "正确：活字是印刷用的单个字块，可以从盒子里拿出来。"}, {"text": "白糖", "is_correct": false, "explanation": "搭配：“白糖”是不可数名词，不能用“一个”计数。"}, {"text": "云朵", "is_correct": false, "explanation": "语义：云朵在天空中，不能从盒子里拿出来。"}, {"text": "闪电", "is_correct": false, "explanation": "语义：闪电是瞬间的自然现象，不能装进盒子里拿出。"}], "explanations": {"活字": "正确：活字是印刷用的单个字块，可以从盒子里拿出来。", "白糖": "搭配：“白糖”是不可数名词，不能用“一个”计数。", "云朵": "语义：云朵在天空中，不能从盒子里拿出来。", "闪电": "语义：闪电是瞬间的自然现象，不能装进盒子里拿出。"}, "sentence_index": 6, "correct_answer": "活字"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我用活字给朋友写了一封信。", "explanation": "这里应该用〈钢笔〉。活字是印刷排版用的字块，不是写字的工具。"}, {"text": "这个活字很好吃，你尝尝。", "explanation": "这里应该用〈点心〉。活字是印刷用的字块，不能吃。"}, {"text": "他打开活字，看了一晚上故事。", "explanation": "这里应该用〈书〉。活字是印刷用的单个字块，不能打开来阅读。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a60b13-703b-4e62-85a9-0f05821c45f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20518, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从盒子里取出了三本活字。", "corrected_sentence": "他从盒子里取出了三个活字。", "error_description": "“活字”的量词应用“个”，说成“三本活字”是错误的；“本”用于书籍，不能用于活字。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a60b13-703b-4e62-85a9-0f05821c45f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20518, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人从木箱里拿出了几只活字。", "corrected_sentence": "工人从木箱里拿出了几个活字。", "error_description": "“活字”应该用量词“个”，不能用“只”；“只”多用于动物或某些成对、单件的物品，不适用于活字。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a60b13-703b-4e62-85a9-0f05821c45f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
