INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20520, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西放好，不让它丢掉。", "primary_collocate": null, "pronunciation": "bǎo cún", "ipa": "pɑʊ̯²¹⁴ tsʰu̯ən³⁵", "syllable_count": 2, "sentences": [{"text": "这些旧照片要好好保存。", "target_word": "保存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛奶要放在冰箱里保存。", "target_word": "保存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把文件保存在电脑里了。", "target_word": "保存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书保存得很好，一点没坏。", "target_word": "保存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他保存着爷爷留下的旧手表。", "target_word": "保存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先保存文件，再关电脑。", "target_word": "保存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把我小时候的衣服都保存起来了。", "target_word": "保存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水果不好保存，夏天很快就坏了。", "target_word": "保存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张老地图保存了一百多年。", "target_word": "保存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个博物馆保存了很多古代的东西。", "target_word": "保存", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "保存了", "label": "体标"}, {"form": "保存着", "label": "体标"}, {"form": "保存期", "label": "复合"}], "register": "中性", "sense_fingerprint": "使东西不丢失、不损坏地留存下来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d56d81d-7b32-4ed2-b81f-faaa77360a2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20520, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "保存", "is_correct": true, "explanation": "「保存」指把照片好好留住，与「好好」搭配，符合句意。"}, {"text": "丢弃", "is_correct": false, "explanation": "语义：「丢弃」是扔掉，与「好好」要留住照片的意思相反。"}, {"text": "撕毁", "is_correct": false, "explanation": "语义：「撕毁」指弄坏，照片要好好留存，不能撕毁。"}, {"text": "遗忘", "is_correct": false, "explanation": "搭配：「遗忘」的对象是记忆、事情，不说「遗忘照片」。"}], "explanations": {"保存": "「保存」指把照片好好留住，与「好好」搭配，符合句意。", "丢弃": "语义：「丢弃」是扔掉，与「好好」要留住照片的意思相反。", "撕毁": "语义：「撕毁」指弄坏，照片要好好留存，不能撕毁。", "遗忘": "搭配：「遗忘」的对象是记忆、事情，不说「遗忘照片」。"}, "sentence_index": 0, "correct_answer": "保存"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一直保存着安静，没有说话。", "explanation": "这里应该用〈保持〉。保存指把具体的东西留住，不能用于安静这类状态。"}, {"text": "这家店的价格一直保存在很低的水平。", "explanation": "这里应该用〈维持〉。保存多指留住具体事物，价格水平要用维持。"}, {"text": "工人每天都要保存机器。", "explanation": "这里应该用〈保养〉。保存只指留住不丢失，要让机器保持良好状态应说保养。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b664e9ad-97d3-45f2-b78a-e8211ea03883') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20520, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保存", "is_correct": true, "explanation": "「保存」指留住衣服，与「都……起来了」搭配，符合句意。"}, {"text": "烧", "is_correct": false, "explanation": "语义：「烧」是用火毁掉，与妈妈留存小时候衣服的意思相反。"}, {"text": "剪", "is_correct": false, "explanation": "语义：「剪起来」不能表示留存，剪衣服是把衣服弄坏，与保留衣服不符。"}, {"text": "撕", "is_correct": false, "explanation": "语义：「撕」是把东西弄破，不能和「起来」一起表示把衣服留存好。"}], "explanations": {"保存": "「保存」指留住衣服，与「都……起来了」搭配，符合句意。", "烧": "语义：「烧」是用火毁掉，与妈妈留存小时候衣服的意思相反。", "剪": "语义：「剪起来」不能表示留存，剪衣服是把衣服弄坏，与保留衣服不符。", "撕": "语义：「撕」是把东西弄破，不能和「起来」一起表示把衣服留存好。"}, "sentence_index": 6, "correct_answer": "保存"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警察负责保存治安。", "explanation": "这里应该用〈维护〉。保存指留存物品，维护治安要用维护。"}, {"text": "奶奶保存孙子很细心。", "explanation": "这里应该用〈照顾〉。保存用于物品，不用于人，照顾孙子要用照顾。"}, {"text": "农民保存了很多鸡。", "explanation": "这里应该用〈饲养〉。保存用于物品，不用于活的动物，养鸡要说饲养。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b664e9ad-97d3-45f2-b78a-e8211ea03883') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20520, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些信保存很好，别弄丢了。", "corrected_sentence": "这些信保存得很好，别弄丢了。", "error_description": "错误：「保存很好」漏了「得」；正确：「保存得很好」。动词后接表示程度的补语，要用「得」引出。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b664e9ad-97d3-45f2-b78a-e8211ea03883') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20520, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把这些信保存抽屉里了。", "corrected_sentence": "我把这些信保存在抽屉里了。", "error_description": "错误：「保存抽屉里」漏了「在」；正确：「保存在抽屉里」。动词后表示东西放到的处所，要用「在」引出。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b664e9ad-97d3-45f2-b78a-e8211ea03883') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20522, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无关", "is_correct": true, "explanation": "「无关」是「有关」的反义，表示两件事没有关系。"}, {"text": "相处", "is_correct": false, "explanation": "语义：「相处」指人与人共同生活，不是两件事之间的关系。"}, {"text": "合作", "is_correct": false, "explanation": "语义：「合作」指人或团体共同做事，与两件事的关联无关。"}, {"text": "来往", "is_correct": false, "explanation": "语义：「来往」指人与人之间的交往，不是有关或无关的对立关系。"}], "correct_answer": "无关", "explanations": {"无关": "「无关」是「有关」的反义，表示两件事没有关系。", "相处": "语义：「相处」指人与人共同生活，不是两件事之间的关系。", "合作": "语义：「合作」指人或团体共同做事，与两件事的关联无关。", "来往": "语义：「来往」指人与人之间的交往，不是有关或无关的对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b664e9ad-97d3-45f2-b78a-e8211ea03883') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20522, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无关", "is_correct": true, "explanation": "「无关」是「有关」的反义，表示两件事没有关系。"}, {"text": "认识", "is_correct": false, "explanation": "语义：「认识」指知道某人或某事，不表示事情之间的关系。"}, {"text": "见面", "is_correct": false, "explanation": "配价：「见面」指人与人相见，不描述两件事的关系。"}, {"text": "配合", "is_correct": false, "explanation": "语义：「配合」指共同行动，与两件事是否有关系无关。"}], "correct_answer": "无关", "explanations": {"无关": "「无关」是「有关」的反义，表示两件事没有关系。", "认识": "语义：「认识」指知道某人或某事，不表示事情之间的关系。", "见面": "配价：「见面」指人与人相见，不描述两件事的关系。", "配合": "语义：「配合」指共同行动，与两件事是否有关系无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b664e9ad-97d3-45f2-b78a-e8211ea03883') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20522, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "两件事之间有联系、相互牵涉。", "primary_collocate": null, "pronunciation": "yǒu guān", "ipa": "joʊ˨˩˦ kwan˥˥", "syllable_count": 2, "sentences": [{"text": "这件事和我有关。", "target_word": "有关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的病和天气有关。", "target_word": "有关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题与钱有关吗？", "target_word": "有关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡得好不好和吃的东西有关。", "target_word": "有关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两件事有关，不能分开说。", "target_word": "有关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的成绩和努力有关。", "target_word": "有关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的名字和这座城市有关。", "target_word": "有关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事跟你有关，也跟我有关。", "target_word": "有关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "头疼可能与睡觉太少有关。", "target_word": "有关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的故事和历史有关。", "target_word": "有关", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "有關", "label": "繁体"}], "register": "中性", "sense_fingerprint": "两件事之间有关系，常说“A和B有关”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d56d81d-7b32-4ed2-b81f-faaa77360a2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20522, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有关", "is_correct": true, "explanation": "「有关」表示两件事有联系，「这件事和我」之后用它，符合句意。"}, {"text": "有用", "is_correct": false, "explanation": "搭配：「有用」要说「对……有用」，不说「和我有用」。"}, {"text": "相处", "is_correct": false, "explanation": "配价：「相处」要求人作主语，「这件事」不能和「我」相处。"}, {"text": "认识", "is_correct": false, "explanation": "语义：「认识」的对象是人，事情不能和人认识，这里不通。"}], "explanations": {"有关": "「有关」表示两件事有联系，「这件事和我」之后用它，符合句意。", "有用": "搭配：「有用」要说「对……有用」，不说「和我有用」。", "相处": "配价：「相处」要求人作主语，「这件事」不能和「我」相处。", "认识": "语义：「认识」的对象是人，事情不能和人认识，这里不通。"}, "sentence_index": 0, "correct_answer": "有关"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你最近有关新闻吗？", "explanation": "这里应该用〈关注〉。有关表示两件事之间有联系，不表示留意某事；留意新闻要说关注。"}, {"text": "老师很有关我的进步，每周都检查作业。", "explanation": "这里应该用〈关注〉。有关表示事情相连，不表示对人的注意；老师留意学生的进步要说关注。"}, {"text": "我们要和客户保持有关。", "explanation": "这里应该用〈联系〉。有关说事情之间的关系，与客户的往来要说保持联系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b664e9ad-97d3-45f2-b78a-e8211ea03883') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20522, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有关", "is_correct": true, "explanation": "「有关」表示两件事有联系，「他的名字和这座城市」之后用它，符合句意。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：「结婚」只用于人，名字和城市不能结婚。"}, {"text": "相爱", "is_correct": false, "explanation": "语义：「相爱」只用于人之间，与名字和城市的关系不符。"}, {"text": "见面", "is_correct": false, "explanation": "配价：「见面」要求两方都是人，名字不能和城市见面。"}], "explanations": {"有关": "「有关」表示两件事有联系，「他的名字和这座城市」之后用它，符合句意。", "结婚": "语义：「结婚」只用于人，名字和城市不能结婚。", "相爱": "语义：「相爱」只用于人之间，与名字和城市的关系不符。", "见面": "配价：「见面」要求两方都是人，名字不能和城市见面。"}, "sentence_index": 6, "correct_answer": "有关"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司有关很多工厂。", "explanation": "这里应该用〈拥有〉。有关表示事情之间有联系，不表示占有；公司有很多工厂要说拥有。"}, {"text": "妈妈一直有关远方的儿子，每天都打一个电话。", "explanation": "这里应该用〈挂念〉。有关表示事情相连，不表示思念人；牵挂远方的儿子要说挂念。"}, {"text": "他很有关孩子的安全。", "explanation": "这里应该用〈担心〉。有关说事情之间的联系，对孩子安全的忧虑要说担心。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b664e9ad-97d3-45f2-b78a-e8211ea03883') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20522, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事你有关，我们要认真对待。", "corrected_sentence": "这件事和你有关，我们要认真对待。", "error_description": "错误：「这件事你有关」中「你」直接接在「有关」前，缺少「和」引出关联的对象；正确：「这件事和你有关」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b664e9ad-97d3-45f2-b78a-e8211ea03883') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20522, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事和你不有关，别担心。", "corrected_sentence": "这件事和你无关，别担心。", "error_description": "错误：「不有关」；正确：「无关」。「有关」的否定形式是「无关」，不能在「有关」前面加「不」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b664e9ad-97d3-45f2-b78a-e8211ea03883') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
