INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20524, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "一个接一个地。", "primary_collocate": null, "pronunciation": "xiāng jì", "ipa": "ɕiɑŋ˥ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "老人们相继离开了这个小村子。", "target_word": "相继", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两年，几家商店相继关门了。", "target_word": "相继", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们相继来到了北京。", "target_word": "相继", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，花儿相继开了。", "target_word": "相继", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们相继跑进了教室。", "target_word": "相继", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几位老师相继发言，大家听得很认真。", "target_word": "相继", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的老同事相继退休了。", "target_word": "相继", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台风过后，电和水相继恢复了。", "target_word": "相继", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三个孩子相继长大，离开了家。", "target_word": "相继", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们相继来看我，我很高兴。", "target_word": "相继", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "多个人或事一个接一个地先后发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '578a203d-4358-4a88-a532-6eee781a844a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20524, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "相继", "is_correct": true, "explanation": "正确答案：相继（xiāng jì），意思是一个接一个地。"}, {"text": "相机", "is_correct": false, "explanation": "相机读 xiàngjī，“相”是第四声，“机”是第一声，与 xiāng jì 声调不同；“相机”意思是照相机。"}, {"text": "香气", "is_correct": false, "explanation": "qì 与 jì 声母不同（q 与 j），“香气”意思是香味。"}, {"text": "相似", "is_correct": false, "explanation": "sì 与 jì 声母不同（s 与 j），“相似”意思是像。"}], "explanations": {"相继": "正确答案：相继（xiāng jì），意思是一个接一个地。", "相机": "相机读 xiàngjī，“相”是第四声，“机”是第一声，与 xiāng jì 声调不同；“相机”意思是照相机。", "香气": "qì 与 jì 声母不同（q 与 j），“香气”意思是香味。", "相似": "sì 与 jì 声母不同（s 与 j），“相似”意思是像。"}, "sentence_index": null, "correct_answer": "相继"}, "level_3": {"options": [{"text": "相继", "is_correct": true, "explanation": "正确：“老人们相继离开”，表示一个接一个地离开。"}, {"text": "很", "is_correct": false, "explanation": "搭配：“很”是程度副词，不能直接修饰动作动词“离开”。"}, {"text": "一直", "is_correct": false, "explanation": "搭配：“一直”表示持续，不能修饰“离开”这种一次性动作。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”是程度副词，修饰形容词，不能直接修饰“离开”这样的动作动词。"}], "explanations": {"相继": "正确：“老人们相继离开”，表示一个接一个地离开。", "很": "搭配：“很”是程度副词，不能直接修饰动作动词“离开”。", "一直": "搭配：“一直”表示持续，不能修饰“离开”这种一次性动作。", "非常": "搭配：“非常”是程度副词，修饰形容词，不能直接修饰“离开”这样的动作动词。"}, "sentence_index": 0, "correct_answer": "相继"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这杯水相继热了。", "explanation": "这里应该用〈慢慢〉。“相继”表示几件事先后接连发生，不能表示一件事逐渐变化；“这杯水”只有一杯，应说“慢慢热了”。"}, {"text": "我相继离开了教室。", "explanation": "这里应该用〈先〉。“相继”需要几个人或几件事接连发生，一个人一次离开只能用“先”。"}, {"text": "他相继走回家。", "explanation": "这里应该用〈独自〉。“相继”表示接连发生，只有一个人一次走回家时要用“独自”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a181211-58db-4cd8-92c1-c013be897e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20524, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相继", "is_correct": true, "explanation": "正确：“公司的老同事相继退休”，表示一批接一批地退休。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与接连发生的“相继”语义相反。"}, {"text": "亲自", "is_correct": false, "explanation": "搭配：“亲自”要求动作由人主动亲身完成，不能修饰“退休”。"}, {"text": "连忙", "is_correct": false, "explanation": "语义：“连忙”表示急忙行动，不能修饰“退休”这一结果。"}], "explanations": {"相继": "正确：“公司的老同事相继退休”，表示一批接一批地退休。", "偶尔": "语义：“偶尔”表示不常发生，与接连发生的“相继”语义相反。", "亲自": "搭配：“亲自”要求动作由人主动亲身完成，不能修饰“退休”。", "连忙": "语义：“连忙”表示急忙行动，不能修饰“退休”这一结果。"}, "sentence_index": 6, "correct_answer": "相继"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他相继出发了。", "explanation": "这里应该用〈马上〉。“相继”要求多人或多件事接连发生，一个人只出发一次时不能用。"}, {"text": "这扇门相继开了。", "explanation": "这里应该用〈突然〉。“相继”表示几件事接连发生，一扇门只开一次时不能用“相继”，应说“突然开了”。"}, {"text": "他相继在等你。", "explanation": "这里应该用〈一直〉。“相继”表示接连发生，不能表示持续不断地进行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a181211-58db-4cd8-92c1-c013be897e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20524, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师们相继了走进了教室。", "corrected_sentence": "老师们相继走进了教室。", "error_description": "错误位置：“相继”是副词，不能直接带动态助词“了”。错误形式：“相继了走进”；正确形式：“相继走进了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a181211-58db-4cd8-92c1-c013be897e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20524, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同事们相继的离开了公司。", "corrected_sentence": "同事们相继离开了公司。", "error_description": "错误形式：“相继的离开”；正确形式：“相继离开”。“相继”作状语时直接修饰动词，中间加“的”不地道。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a181211-58db-4cd8-92c1-c013be897e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20527, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失去", "is_correct": true, "explanation": "正确答案：“失去”与“得到”相反，表示不再拥有。"}, {"text": "洗", "is_correct": false, "explanation": "“洗”指用水去除污垢，与“得到”没有反义关系。"}, {"text": "写", "is_correct": false, "explanation": "“写”指写字，与“得到”没有反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "“唱”指唱歌，与“得到”没有反义关系。"}], "correct_answer": "失去", "explanations": {"失去": "正确答案：“失去”与“得到”相反，表示不再拥有。", "洗": "“洗”指用水去除污垢，与“得到”没有反义关系。", "写": "“写”指写字，与“得到”没有反义关系。", "唱": "“唱”指唱歌，与“得到”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20527, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失去", "is_correct": true, "explanation": "正确答案：“失去”与“得到”相反，表示不再拥有。"}, {"text": "读", "is_correct": false, "explanation": "“读”指看文字并理解，与“得到”没有反义关系。"}, {"text": "打", "is_correct": false, "explanation": "“打”指用力击打，与“得到”没有反义关系。"}, {"text": "跑", "is_correct": false, "explanation": "“跑”指快速移动，与“得到”没有反义关系。"}], "correct_answer": "失去", "explanations": {"失去": "正确答案：“失去”与“得到”相反，表示不再拥有。", "读": "“读”指看文字并理解，与“得到”没有反义关系。", "打": "“打”指用力击打，与“得到”没有反义关系。", "跑": "“跑”指快速移动，与“得到”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20527, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "得到就是拿到想要的东西。", "primary_collocate": null, "pronunciation": "dé dào", "ipa": "tɤ˧˥ taʊ˥˩", "syllable_count": 2, "sentences": [{"text": "我终于得到了那本书。", "target_word": "得到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他努力学习，得到了好成绩。", "target_word": "得到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想得到什么礼物？", "target_word": "得到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明得到老师的表扬，很高兴。", "target_word": "得到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她没有得到妈妈的同意。", "target_word": "得到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做这件事，我们得到了很多帮助。", "target_word": "得到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从没得到过这么好的礼物。", "target_word": "得到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想得到别人的喜欢，先要对别人好。", "target_word": "得到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在比赛中得到了第一名。", "target_word": "得到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机会不是白白得到的。", "target_word": "得到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "得到了", "label": "体标（了）"}, {"form": "得到过", "label": "体标（过）"}, {"form": "得不到", "label": "可能补语否定"}], "register": "中性", "sense_fingerprint": "拿到想要的东西或结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fde7ad18-0ff2-44e3-844c-df7b9ce4ca9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20527, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "得到", "is_correct": true, "explanation": "正确答案：得到，表示拿到想要的东西。"}, {"text": "得当", "is_correct": false, "explanation": "dàng 与 dào 的韵母不同（ang 与 ao），得当的意思是恰当。"}, {"text": "地道", "is_correct": false, "explanation": "dì（第四声）与 dé（第二声）的韵母不同（i 与 e），地道的意思是纯正、真正。"}, {"text": "大道", "is_correct": false, "explanation": "dà（第四声）与 dé（第二声）的韵母不同（a 与 e），大道的意思是大路。"}], "explanations": {"得到": "正确答案：得到，表示拿到想要的东西。", "得当": "dàng 与 dào 的韵母不同（ang 与 ao），得当的意思是恰当。", "地道": "dì（第四声）与 dé（第二声）的韵母不同（i 与 e），地道的意思是纯正、真正。", "大道": "dà（第四声）与 dé（第二声）的韵母不同（a 与 e），大道的意思是大路。"}, "sentence_index": null, "correct_answer": "得到"}, "level_3": {"options": [{"text": "得到", "is_correct": true, "explanation": "正确答案：“得到”表示取得，与“终于”和“那本书”搭配自然。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说吃书。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是饮品，不能说喝书。"}, {"text": "游", "is_correct": false, "explanation": "配价：“游”是不及物动词，后面不能带“那本书”作宾语。"}], "explanations": {"得到": "正确答案：“得到”表示取得，与“终于”和“那本书”搭配自然。", "吃": "搭配：“吃”的对象是食物，不能说吃书。", "喝": "搭配：“喝”的对象是饮品，不能说喝书。", "游": "配价：“游”是不及物动词，后面不能带“那本书”作宾语。"}, "sentence_index": 0, "correct_answer": "得到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他终于得到了北京。", "explanation": "这里应该用〈到达〉。得到用于取得东西或结果，表示到某地要用到达或去。"}, {"text": "我们在路上得到了麻烦。", "explanation": "这里应该用〈遇到〉。麻烦是遇到的，不能说得到。"}, {"text": "他得到了一场病。", "explanation": "这里应该用〈得〉。生病要说“得了一场病”，不能说得到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20527, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "得到", "is_correct": true, "explanation": "正确答案：得到，表示取得想要的结果。"}, {"text": "大盗", "is_correct": false, "explanation": "dà（第四声）与 dé（第二声）的韵母不同（a 与 e），大盗的意思是大强盗。"}, {"text": "打到", "is_correct": false, "explanation": "dǎ（第三声）与 dé（第二声）的韵母不同（a 与 e），打到的意思是击中。"}, {"text": "大刀", "is_correct": false, "explanation": "dà dāo 与 dé dào 的韵母和声调都不同，大刀的意思是大的刀。"}], "explanations": {"得到": "正确答案：得到，表示取得想要的结果。", "大盗": "dà（第四声）与 dé（第二声）的韵母不同（a 与 e），大盗的意思是大强盗。", "打到": "dǎ（第三声）与 dé（第二声）的韵母不同（a 与 e），打到的意思是击中。", "大刀": "dà dāo 与 dé dào 的韵母和声调都不同，大刀的意思是大的刀。"}, "sentence_index": null, "correct_answer": "得到"}, "level_3": {"options": [{"text": "得到", "is_correct": true, "explanation": "正确答案：“得到”表示取得，与“从没…过”和“这么好的礼物”搭配自然。"}, {"text": "说", "is_correct": false, "explanation": "搭配：“说”的对象是话语，不能说“说礼物”。"}, {"text": "修", "is_correct": false, "explanation": "语义：礼物不需要修理，句中没有“修”的语境。"}, {"text": "站", "is_correct": false, "explanation": "配价：“站”是不及物动词，后面不能带“礼物”作宾语。"}], "explanations": {"得到": "正确答案：“得到”表示取得，与“从没…过”和“这么好的礼物”搭配自然。", "说": "搭配：“说”的对象是话语，不能说“说礼物”。", "修": "语义：礼物不需要修理，句中没有“修”的语境。", "站": "配价：“站”是不及物动词，后面不能带“礼物”作宾语。"}, "sentence_index": 6, "correct_answer": "得到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他得到了那场比赛。", "explanation": "这里应该用〈赢得〉。比赛的胜负要说赢得，“得到”只用于拿到想要的东西。"}, {"text": "他得到了十八岁。", "explanation": "这里应该用〈满〉。年龄要说满，不能说得到。"}, {"text": "他得到了眼泪。", "explanation": "这里应该用〈流〉。眼泪是流的，不能说得到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20527, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我终于得到着一份工作。", "corrected_sentence": "我终于得到了一份工作。", "error_description": "“得到”表示一次完成的取得，后面要用“了”，不能用“着”。正确是“得到了一份工作”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
