INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20530, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "自己做不到，需要靠别人或别的事物的帮助才能维持或完成。", "primary_collocate": null, "pronunciation": "yī lài", "ipa": "i˥ laɪ˥˩", "syllable_count": 2, "sentences": [{"text": "孩子小的时候很依赖妈妈。", "target_word": "依赖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不能总是依赖别人。", "target_word": "依赖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很依赖哥哥的帮助。", "target_word": "依赖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人生病后，只能依赖家人。", "target_word": "依赖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想依赖父母过日子。", "target_word": "依赖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她太依赖朋友，什么事都要问。", "target_word": "依赖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学外语不能只依赖老师。", "target_word": "依赖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小店依赖老客人才能开下去。", "target_word": "依赖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刚到国外时，我依赖过同学的帮助。", "target_word": "依赖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他慢慢不再依赖家人了。", "target_word": "依赖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "依赖着", "label": "体标"}, {"form": "依赖过", "label": "体标"}, {"form": "依赖性", "label": "复合"}, {"form": "依賴", "label": "繁体"}], "register": "中性", "sense_fingerprint": "自己做不到，要靠别人或别的东西帮助", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e64b3b0f-81c3-4b52-bcde-e97b5fd7793c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20530, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "修理", "is_correct": false, "explanation": "语义：修理的对象是物品，孩子小时候不能“修理”妈妈，句意不通。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是房间、场所，不说打扫妈妈。"}, {"text": "指导", "is_correct": false, "explanation": "语义：小孩子不会去指导妈妈，与句中“小的时候”的语境矛盾。"}, {"text": "依赖", "is_correct": true, "explanation": "正确答案。“很依赖妈妈”指孩子小时候需要妈妈照顾，符合句意。"}], "explanations": {"修理": "语义：修理的对象是物品，孩子小时候不能“修理”妈妈，句意不通。", "打扫": "搭配：“打扫”的对象是房间、场所，不说打扫妈妈。", "指导": "语义：小孩子不会去指导妈妈，与句中“小的时候”的语境矛盾。", "依赖": "正确答案。“很依赖妈妈”指孩子小时候需要妈妈照顾，符合句意。"}, "sentence_index": 0, "correct_answer": "依赖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我出国前把小狗依赖给了邻居。", "explanation": "这里应该用〈托付〉。把事情或东西交给别人照顾要用“托付”，依赖指自己做不到而需要靠别人。"}, {"text": "他依赖着门框休息。", "explanation": "这里应该用〈倚靠〉。依赖指需要别人或事物帮助，身体靠着门框要用“倚靠”。"}, {"text": "父母把希望依赖在孩子身上。", "explanation": "这里应该用〈寄托〉。“希望”要用“寄托”，依赖不能与“希望”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20530, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "替换", "is_correct": false, "explanation": "语义：“替换”是换掉老师，与“学外语”的语境不符。"}, {"text": "复制", "is_correct": false, "explanation": "语义：不能复制老师，学外语要靠老师的指导，句意矛盾。"}, {"text": "批改", "is_correct": false, "explanation": "搭配：“批改”的对象是作业、作文，不说批改老师。"}, {"text": "依赖", "is_correct": true, "explanation": "正确答案。“不能只依赖老师”指学外语不能只靠老师，符合句意。"}], "explanations": {"替换": "语义：“替换”是换掉老师，与“学外语”的语境不符。", "复制": "语义：不能复制老师，学外语要靠老师的指导，句意矛盾。", "批改": "搭配：“批改”的对象是作业、作文，不说批改老师。", "依赖": "正确答案。“不能只依赖老师”指学外语不能只靠老师，符合句意。"}, "sentence_index": 6, "correct_answer": "依赖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子累了，就依赖在妈妈怀里。", "explanation": "这里应该用〈依偎〉。身体贴近、靠在一起要用“依偎”，“依赖”指需要别人帮助。"}, {"text": "藤蔓依赖在墙上生长。", "explanation": "这里应该用〈依附〉。植物攀附在别的物体上要用“依附”，依赖不用于植物附着。"}, {"text": "我向同学依赖了一本书。", "explanation": "这里应该用〈借〉。从别人那里拿来东西用要说“借”，依赖指自己做不到而需要靠别人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20530, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我小时候依赖的过奶奶。", "corrected_sentence": "我小时候依赖过奶奶。", "error_description": "结构错误：“依赖”后面直接接“过”，中间多了“的”，应说“依赖过奶奶”，不能加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20530, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人在医院里被依赖护工。", "corrected_sentence": "老人在医院里依赖护工。", "error_description": "被字句错误：“依赖”是及物动词，“老人”是施事，不能在前面加“被”，应删去“被”，说“老人在医院里依赖护工”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
