INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20532, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "做事情要用很多力气。", "primary_collocate": null, "pronunciation": "fèi lì", "ipa": "fei⁵¹ li⁵¹", "syllable_count": 2, "sentences": [{"text": "这个箱子太重，搬起来很费力。", "target_word": "费力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷爬楼梯有点费力。", "target_word": "费力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用小勺子挖土太费力了。", "target_word": "费力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事看起来简单，做起来却很费力。", "target_word": "费力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他年纪大了，走路很费力。", "target_word": "费力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这扇旧门很重，打开它很费力。", "target_word": "费力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "逆着风骑车非常费力。", "target_word": "费力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不费力就把桌子搬走了。", "target_word": "费力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手不方便的人写字很费力。", "target_word": "费力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山路又陡又滑，走得很费力。", "target_word": "费力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不费力", "label": "否定"}, {"form": "费力气", "label": "复合"}, {"form": "费力不讨好", "label": "固定搭配"}], "register": "中性", "sense_fingerprint": "做事需要花很大力气，不轻松", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f67254c-2b72-48f7-a62f-6cc95d11eae2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20532, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "费力", "is_correct": true, "explanation": "正确。“费力”指做事要用很大力气，与“太重，搬起来”的语境相符。"}, {"text": "轻松", "is_correct": false, "explanation": "语义：“轻松”与句中“箱子太重”的意思相反，搬起来不会轻松。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外貌好看，不能用来形容搬东西的情况。"}, {"text": "冷", "is_correct": false, "explanation": "语义：“冷”指温度低，不能用来形容搬东西的情况。"}], "explanations": {"费力": "正确。“费力”指做事要用很大力气，与“太重，搬起来”的语境相符。", "轻松": "语义：“轻松”与句中“箱子太重”的意思相反，搬起来不会轻松。", "漂亮": "体貌：“漂亮”形容外貌好看，不能用来形容搬东西的情况。", "冷": "语义：“冷”指温度低，不能用来形容搬东西的情况。"}, "sentence_index": 0, "correct_answer": "费力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这袋米很轻，扛起来很费力。", "explanation": "这里不能用“费力”。“费力”指做事需要很大力气，很轻的东西扛起来不费力，两者矛盾。"}, {"text": "他躺在沙发上看电视，觉得很费力。", "explanation": "“费力”只用于做事需要用力的情况，躺着看电视不需要用力，不能用“费力”。"}, {"text": "这张纸很轻，拿起来很费力。", "explanation": "“费力”指需要很大力气，一张很轻的纸拿起来不需要用力，两者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20532, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "费力", "is_correct": true, "explanation": "正确。“费力”指做事要用很大力气，与“逆着风骑车”的情况相符。"}, {"text": "清楚", "is_correct": false, "explanation": "搭配：“清楚”形容看得或说得明白，不能形容骑车的状态。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“安静”指没有声音，与逆风骑车是否费力无关。"}, {"text": "红", "is_correct": false, "explanation": "语义：“红”形容颜色，不能用来描述骑车的费力程度。"}], "explanations": {"费力": "正确。“费力”指做事要用很大力气，与“逆着风骑车”的情况相符。", "清楚": "搭配：“清楚”形容看得或说得明白，不能形容骑车的状态。", "安静": "语义：“安静”指没有声音，与逆风骑车是否费力无关。", "红": "语义：“红”形容颜色，不能用来描述骑车的费力程度。"}, "sentence_index": 6, "correct_answer": "费力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条大路很平，走起来非常费力。", "explanation": "“费力”指做事需要很大力气，平坦的大路走起来不需要用力，与“很平”矛盾。"}, {"text": "这台新电脑运行很费力，速度快得很。", "explanation": "“费力”只用于说人做事或动作需要很大力气，电脑运行快不能用“费力”。"}, {"text": "这块石头很轻，搬起来很费力。", "explanation": "“费力”指需要很大力气，“很轻”的石头搬起来不费力，两者矛盾，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20532, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他扛着箱子，走的很费力。", "corrected_sentence": "他扛着箱子，走得很费力。", "error_description": "补语标记误用：程度补语前应用“得”，此处误用“的”，应说“走得很费力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20532, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小孩搬椅子，觉很费力。", "corrected_sentence": "这个小孩搬椅子，觉得很费力。", "error_description": "漏字：“觉得”是一个动词，不能省去“得”，应说“觉得很费力”，不能说“觉很费力”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20534, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64ca69b-64e3-4334-9155-6b7ad34fc6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20534, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64ca69b-64e3-4334-9155-6b7ad34fc6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20534, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情从开始到结束的经过。", "primary_collocate": null, "pronunciation": "guò chéng", "ipa": "kwo˥˩ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "学习的过程很长。", "target_word": "过程", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "做饭的过程很有意思。", "target_word": "过程", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我喜欢旅行的过程,不只看结果。", "target_word": "过程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他给我讲了事情的整个过程。", "target_word": "过程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在学习过程中,我认识了很多朋友。", "target_word": "过程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛的结果不重要,过程更重要。", "target_word": "过程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个过程要花三个小时。", "target_word": "过程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师问我们实验的过程是怎么样的。", "target_word": "过程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把做蛋糕的过程拍成了视频。", "target_word": "过程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "成长的过程中,他吃过很多苦。", "target_word": "过程", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个过程", "label": "量词搭配"}, {"form": "过程中", "label": "方位搭配"}, {"form": "全过程", "label": "复合词"}], "register": "中性", "sense_fingerprint": "过程：事情从开始到结束的经过", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc7d612e-20ca-4dd1-8228-5889a24a7062') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20534, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不能用“长”来描述，“学习的颜色很长”说不通。"}, {"text": "过程", "is_correct": true, "explanation": "“过程”指事情从开始到结束的经过，“学习的过程很长”符合句意。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“很长”不用来形容“体重”，二者不搭配。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”不能说“很长”，与“学习”的时间经过无关，句子说不通。"}], "explanations": {"颜色": "语义：“颜色”不能用“长”来描述，“学习的颜色很长”说不通。", "过程": "“过程”指事情从开始到结束的经过，“学习的过程很长”符合句意。", "体重": "搭配：“很长”不用来形容“体重”，二者不搭配。", "脾气": "语义：“脾气”不能说“很长”，与“学习”的时间经过无关，句子说不通。"}, "sentence_index": 0, "correct_answer": "过程"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次选举的过程出来了。", "explanation": "这里应该用〈结果〉。“过程”指事情从开始到结束的经过，选举的最终结果出来要用“结果”，不能说“过程出来了”。"}, {"text": "这个药的过程很好，两天就好了。", "explanation": "这里应该用〈效果〉。“过程”指经过，不指药物作用的结果，应该用“效果”。"}, {"text": "这家公司的过程很大，有很多员工。", "explanation": "这里应该用〈规模〉。“过程”指经过，不指企业的大小，说企业的大小要用“规模”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64ca69b-64e3-4334-9155-6b7ad34fc6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20534, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "价格", "is_correct": false, "explanation": "搭配：“要花三个小时”说的是做事所需的时间，“价格”不能用来计算耗时。"}, {"text": "过程", "is_correct": true, "explanation": "“过程”指事情从开始到结束的经过，“这个过程要花三个小时”符合句意。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”不是可以持续耗时的事情，“这个声音要花三个小时”说不通。"}, {"text": "性别", "is_correct": false, "explanation": "语义：“性别”与“花三个小时”的时间概念无关，句子说不通。"}], "explanations": {"价格": "搭配：“要花三个小时”说的是做事所需的时间，“价格”不能用来计算耗时。", "过程": "“过程”指事情从开始到结束的经过，“这个过程要花三个小时”符合句意。", "声音": "语义：“声音”不是可以持续耗时的事情，“这个声音要花三个小时”说不通。", "性别": "语义：“性别”与“花三个小时”的时间概念无关，句子说不通。"}, "sentence_index": 6, "correct_answer": "过程"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张桌子的过程很结实。", "explanation": "这里应该用〈质地〉。“过程”指事情的经过，不用来形容物体的结实程度，说物体的质地要用“质地”。"}, {"text": "这顿饭的过程很贵。", "explanation": "这里应该用〈价钱〉。“过程”指事情的经过，不指金钱的多少，说饭菜的价钱要用“价钱”。"}, {"text": "我的过程比他高。", "explanation": "这里应该用〈身高〉。“过程”指事情的经过，不用来比较人的高矮，说人的高矮要用“身高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64ca69b-64e3-4334-9155-6b7ad34fc6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20534, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条过程很复杂，需要一周。", "corrected_sentence": "这个过程很复杂，需要一周。", "error_description": "错误：“过程”前的量词用了“条”。“条”多用于线状物、消息、规定等条目，不用于“过程”这类抽象的经过，应用“个”，说“这个过程”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64ca69b-64e3-4334-9155-6b7ad34fc6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20534, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在工作过程的，他学会了很多东西。", "corrected_sentence": "在工作过程中，他学会了很多东西。", "error_description": "“中”误写为“的”：“过程中”是固定的方位结构，“过程的”不成立，应说“在工作过程中”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64ca69b-64e3-4334-9155-6b7ad34fc6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
