INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20536, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "做事情需要很多时间。", "primary_collocate": null, "pronunciation": "hào shí", "ipa": "xaʊ˥˩ ʂɨ˧˥", "syllable_count": 2, "sentences": [{"text": "做这个菜很耗时。", "target_word": "耗时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "坐船去那里太耗时了。", "target_word": "耗时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手洗衣服很耗时，我用洗衣机。", "target_word": "耗时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个工作耗时又费力。", "target_word": "耗时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学画画很耗时，要慢慢来。", "target_word": "耗时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他觉得写信太耗时，就发短信了。", "target_word": "耗时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做蛋糕不难，但是很耗时。", "target_word": "耗时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车去比坐地铁更耗时。", "target_word": "耗时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏很耗时，我不玩了。", "target_word": "耗时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "整理房间很耗时，你要早点开始。", "target_word": "耗时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "耗时：做一件事需要花很多时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e424837-2e8c-4c86-b782-2097d65b46d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20536, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "耗时", "is_correct": true, "explanation": "正确：耗时指做事情需要很多时间。"}, {"text": "好事", "is_correct": false, "explanation": "好事（hǎoshì）指好的事情。hǎo 与 hào 声调不同，shì 与 shí 声调不同，容易听混。"}, {"text": "报时", "is_correct": false, "explanation": "报时（bàoshí）指报告时间。bào 与 hào 声母不同（b／h）。"}, {"text": "暴食", "is_correct": false, "explanation": "暴食（bàoshí）指过量地吃。bào 与 hào 只差声母（b／h）。"}], "explanations": {"耗时": "正确：耗时指做事情需要很多时间。", "好事": "好事（hǎoshì）指好的事情。hǎo 与 hào 声调不同，shì 与 shí 声调不同，容易听混。", "报时": "报时（bàoshí）指报告时间。bào 与 hào 声母不同（b／h）。", "暴食": "暴食（bàoshí）指过量地吃。bào 与 hào 只差声母（b／h）。"}, "sentence_index": null, "correct_answer": "耗时"}, "level_3": {"options": [{"text": "耗时", "is_correct": true, "explanation": "正确：“做这个菜很耗时”成立，指做菜花很多时间。"}, {"text": "结实", "is_correct": false, "explanation": "搭配：“结实”形容东西坚固，不能用来形容做菜花的时间。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的外形，不能用于做菜这件事。"}, {"text": "沉重", "is_correct": false, "explanation": "语义：“沉重”形容心情或负担，不能形容做菜。"}], "explanations": {"耗时": "正确：“做这个菜很耗时”成立，指做菜花很多时间。", "结实": "搭配：“结实”形容东西坚固，不能用来形容做菜花的时间。", "高大": "体貌：“高大”形容人或物的外形，不能用于做菜这件事。", "沉重": "语义：“沉重”形容心情或负担，不能形容做菜。"}, "sentence_index": 0, "correct_answer": "耗时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个工程耗时大量的钱。", "explanation": "这里应该用〈耗费〉。耗时只说花费的时间多，花钱、花人力要用耗费。"}, {"text": "这部手机的电池耗时很快。", "explanation": "这里应该用〈消耗〉。耗时只说时间花得多，电池的损耗要用消耗。"}, {"text": "他的耐心被耗时得一点不剩。", "explanation": "这里应该用〈消磨〉。耗时不表示耐心被磨光，这里要用消磨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b82f074-9073-48a1-a25a-cbb1a7b7ac41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20536, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "耗时", "is_correct": true, "explanation": "正确：“做蛋糕不难，但是很耗时”成立，指花的时间多。"}, {"text": "低矮", "is_correct": false, "explanation": "体貌：“低矮”形容外形的高度，不能形容做蛋糕的时间。"}, {"text": "委屈", "is_correct": false, "explanation": "语义：“委屈”形容心里不舒服，不能形容做蛋糕。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：“明亮”形容光线和颜色，不与“做蛋糕”搭配。"}], "explanations": {"耗时": "正确：“做蛋糕不难，但是很耗时”成立，指花的时间多。", "低矮": "体貌：“低矮”形容外形的高度，不能形容做蛋糕的时间。", "委屈": "语义：“委屈”形容心里不舒服，不能形容做蛋糕。", "明亮": "搭配：“明亮”形容光线和颜色，不与“做蛋糕”搭配。"}, "sentence_index": 6, "correct_answer": "耗时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台老冰箱很耗时，每个月电费都很高。", "explanation": "这里应该用〈耗电〉。耗时说的是花费的时间多，冰箱费电要说耗电。"}, {"text": "这台机器的零件耗时得很快。", "explanation": "这里应该用〈磨损〉。耗时只说花费的时间多，零件用久变坏要用磨损。"}, {"text": "旱季的水源很快耗时。", "explanation": "这里应该用〈耗尽〉。耗时只说时间长，水源用完要用耗尽。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b82f074-9073-48a1-a25a-cbb1a7b7ac41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20536, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学习一门新技能是一件很耗时事。", "corrected_sentence": "学习一门新技能是一件很耗时的事。", "error_description": "漏掉“的”：“耗时”作定语修饰名词时要加“的”，“很耗时事”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b82f074-9073-48a1-a25a-cbb1a7b7ac41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20536, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次手术前后的准备工作非常很耗时。", "corrected_sentence": "这次手术前后的准备工作非常耗时。", "error_description": "程度副词重复：“非常”与“很”都表示程度，不能叠用，应只用“非常”，说“非常耗时”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b82f074-9073-48a1-a25a-cbb1a7b7ac41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
