INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20538, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "身体或物体碰到人或物，表示物理上的接触。", "primary_collocate": null, "pronunciation": "jiē chù", "ipa": "tɕjɛ⁵⁵ ʈʂʰu⁵¹", "syllable_count": 2, "sentences": [{"text": "小孩的手接触到热水，马上缩回来了。", "target_word": "接触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皮肤接触到这种药水会很痒。", "target_word": "接触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要让食物接触到生肉。", "target_word": "接触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手一接触到冰块，就觉得很冷。", "target_word": "接触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种植物的汁液接触到皮肤会过敏。", "target_word": "接触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的脚刚接触到水，就叫了起来。", "target_word": "接触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，病人的血不要接触到别人的伤口。", "target_word": "接触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电线接触到水很危险。", "target_word": "接触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫的鼻子接触到我的手，凉凉的。", "target_word": "接触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗手以前，不要用手接触眼睛。", "target_word": "接触", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "接触了", "label": "体标（了）"}, {"form": "接触过", "label": "体标（过）"}, {"form": "接触着", "label": "体标（着）"}, {"form": "接觸", "label": "繁体"}], "register": "中性", "sense_fingerprint": "身体或手碰到人或物，物理上的接触", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fde7ad18-0ff2-44e3-844c-df7b9ce4ca9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20538, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "接触", "is_correct": true, "explanation": "正确答案：接触，表示手或身体碰到人或物。"}, {"text": "解除", "is_correct": false, "explanation": "jiě（第三声）与 jiē（第一声）、chú（第二声）与 chù（第四声）声调都不同，意思是消除、取消。"}, {"text": "结束", "is_correct": false, "explanation": "jié 与 jiē 声调不同，shù 与 chù 的声母不同（sh 与 ch），意思是结束。"}, {"text": "接住", "is_correct": false, "explanation": "zhù 与 chù 的声母不同（zh 与 ch），接住的意思是接稳。"}], "explanations": {"接触": "正确答案：接触，表示手或身体碰到人或物。", "解除": "jiě（第三声）与 jiē（第一声）、chú（第二声）与 chù（第四声）声调都不同，意思是消除、取消。", "结束": "jié 与 jiē 声调不同，shù 与 chù 的声母不同（sh 与 ch），意思是结束。", "接住": "zhù 与 chù 的声母不同（zh 与 ch），接住的意思是接稳。"}, "sentence_index": null, "correct_answer": "接触"}, "level_3": {"options": [{"text": "接触", "is_correct": true, "explanation": "正确答案：“接触到”表示碰到，与“手”和“热水”搭配自然。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：“讨论”的对象是问题，不能用于手和热水。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能说手唱到热水。"}, {"text": "站", "is_correct": false, "explanation": "配价：“站”是不及物动词，不能说站到热水。"}], "explanations": {"接触": "正确答案：“接触到”表示碰到，与“手”和“热水”搭配自然。", "讨论": "搭配：“讨论”的对象是问题，不能用于手和热水。", "唱": "搭配：“唱”的对象是歌曲，不能说手唱到热水。", "站": "配价：“站”是不及物动词，不能说站到热水。"}, "sentence_index": 0, "correct_answer": "接触"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他接触了我的一个邀请。", "explanation": "这里应该用〈接受〉。邀请要说接受，“接触”只表示用手碰到别人或东西。"}, {"text": "他接触了比赛的冠军。", "explanation": "这里应该用〈获得〉。冠军要说获得或拿到，“接触”不表示取得名次。"}, {"text": "他的成绩接触了我。", "explanation": "这里应该用〈超过〉。成绩比较是超过，不能用“接触”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20538, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "接触", "is_correct": true, "explanation": "正确答案：接触，表示手或身体碰到人或物。"}, {"text": "戒除", "is_correct": false, "explanation": "jiè（第四声）与 jiē（第一声）、chú（第二声）与 chù（第四声）声调都不同，意思是戒掉。"}, {"text": "借出", "is_correct": false, "explanation": "jiè chū 与 jiē chù 的声调都不同，意思是借给别人。"}, {"text": "结出", "is_correct": false, "explanation": "jié（第二声）与 jiē 声调不同，chū 与 chù 声调也不同，意思是长出果实。"}], "explanations": {"接触": "正确答案：接触，表示手或身体碰到人或物。", "戒除": "jiè（第四声）与 jiē（第一声）、chú（第二声）与 chù（第四声）声调都不同，意思是戒掉。", "借出": "jiè chū 与 jiē chù 的声调都不同，意思是借给别人。", "结出": "jié（第二声）与 jiē 声调不同，chū 与 chù 声调也不同，意思是长出果实。"}, "sentence_index": null, "correct_answer": "接触"}, "level_3": {"options": [{"text": "接触", "is_correct": true, "explanation": "正确答案：“接触到”表示碰到，与“血”和“伤口”搭配自然。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说血吃到伤口。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是饮品，不能说血喝到伤口。"}, {"text": "修", "is_correct": false, "explanation": "语义：血和伤口都不能修理，句中没有“修”的语境。"}], "explanations": {"接触": "正确答案：“接触到”表示碰到，与“血”和“伤口”搭配自然。", "吃": "搭配：“吃”的对象是食物，不能说血吃到伤口。", "喝": "搭配：“喝”的对象是饮品，不能说血喝到伤口。", "修": "语义：血和伤口都不能修理，句中没有“修”的语境。"}, "sentence_index": 6, "correct_answer": "接触"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他接触了考试。", "explanation": "这里应该用〈通过〉。考试要说通过，不能说接触。"}, {"text": "事故接触在下午。", "explanation": "这里应该用〈发生〉。事故是发生的，不能用“接触”。"}, {"text": "会议接触了。", "explanation": "这里应该用〈结束〉。会议是结束的，不能说接触。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20538, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的脚刚接触到着冷水。", "corrected_sentence": "他的脚刚接触到了冷水。", "error_description": "“接触到”表示动作已经完成，后面要用“了”，不能用“着”。正确是“接触到了冷水”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20538, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子的手不小心接触了到插座。", "corrected_sentence": "孩子的手不小心接触到了插座。", "error_description": "“到”是结果补语，应紧跟“接触”，“了”放在“到”后面，说“接触到了插座”；不能说“接触了到插座”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1facf474-2d73-4b49-8631-5ec35907cffa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
