INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20540, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人们分成不同的组，有的高有的低。", "primary_collocate": null, "pronunciation": "jiē céng", "ipa": "tɕjɛ˥ tsʰəŋ˧˥", "syllable_count": 2, "sentences": [{"text": "社会上有不同的阶层。", "target_word": "阶层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家属于哪个阶层？", "target_word": "阶层", "complexity_tier": "T3", "furigana": "jiēcéng", "sentence_source": "generated"}, {"text": "不同阶层的人，生活很不一样。", "target_word": "阶层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市里，不同阶层的人住在一起。", "target_word": "阶层", "complexity_tier": "T3", "furigana": "jiēcéng", "sentence_source": "generated"}, {"text": "这本书写的是古代社会的阶层。", "target_word": "阶层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个阶层的人都有自己的想法。", "target_word": "阶层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他努力工作，想进入更高的阶层。", "target_word": "阶层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，过去的社会分成很多阶层。", "target_word": "阶层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同阶层的孩子在同一所学校读书。", "target_word": "阶层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人觉得，阶层之间的路很难走。", "target_word": "阶层", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "中产阶层", "label": "复合"}, {"form": "社会阶层", "label": "复合"}], "register": "中性", "sense_fingerprint": "社会中按地位高低分成的群体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd55c2c29-17cd-4734-b3f1-6a6d294a15a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20540, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "阶层", "is_correct": true, "explanation": "正确。阶层指社会中按地位高低分成的群体，这里说社会上有不同的群体。"}, {"text": "天气", "is_correct": false, "explanation": "语义：「天气」指大气状况，不能用来指社会中的群体。"}, {"text": "树木", "is_correct": false, "explanation": "语义：「树木」指植物，与社会分层无关。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：「体重」一般用于人或动物的重量，不能用来说社会的分类。"}], "explanations": {"阶层": "正确。阶层指社会中按地位高低分成的群体，这里说社会上有不同的群体。", "天气": "语义：「天气」指大气状况，不能用来指社会中的群体。", "树木": "语义：「树木」指植物，与社会分层无关。", "体重": "搭配：「体重」一般用于人或动物的重量，不能用来说社会的分类。"}, "sentence_index": 0, "correct_answer": "阶层"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司按阶层给员工发工资。", "explanation": "这里应该用〈等级〉。阶层指社会中的群体，按职位或能力高低定工资要用等级。"}, {"text": "人生的每个阶层都有不同的挑战。", "explanation": "这里应该用〈阶段〉。阶层指社会中的群体，人生的不同时期要说阶段。"}, {"text": "这栋楼一共有二十个阶层。", "explanation": "这里应该用〈楼层〉。阶层指社会中按地位分成的群体，楼房的层数要说楼层。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2512b206-61b6-47f3-a7d1-2353d2b9f1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20540, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "阶层", "is_correct": true, "explanation": "正确。阶层指社会中的群体，想进入更高的阶层就是想提升社会地位。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：「颜色」指色彩，不能说进入更高的颜色。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：「年龄」一般说人或动物的岁数，不能说进入更高的年龄。"}, {"text": "声音", "is_correct": false, "explanation": "语义：「声音」指发出的音响，不能说进入更高的声音。"}], "explanations": {"阶层": "正确。阶层指社会中的群体，想进入更高的阶层就是想提升社会地位。", "颜色": "语义：「颜色」指色彩，不能说进入更高的颜色。", "年龄": "搭配：「年龄」一般说人或动物的岁数，不能说进入更高的年龄。", "声音": "语义：「声音」指发出的音响，不能说进入更高的声音。"}, "sentence_index": 6, "correct_answer": "阶层"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "中国有五十六个阶层。", "explanation": "这里应该用〈民族〉。阶层指社会地位高低分成的群体，中国的五十六个并不是按这种方式划分的。"}, {"text": "我们班有四十个阶层。", "explanation": "这里应该用〈学生〉。阶层指社会中的群体，班里的人数不能用阶层来说。"}, {"text": "学校有六个阶层，每个年级一个。", "explanation": "这里应该用〈年级〉。学校的年级是学制的划分，不是社会中的阶层。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2512b206-61b6-47f3-a7d1-2353d2b9f1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20540, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这篇报道分析了城市里一位阶层的收入。", "corrected_sentence": "这篇报道分析了城市里一个阶层的收入。", "error_description": "错误在量词：「阶层」不能用「位」，「位」用于人。正确说法是「一个阶层」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2512b206-61b6-47f3-a7d1-2353d2b9f1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20540, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小镇的居民分属不同的阶层们。", "corrected_sentence": "这个小镇的居民分属不同的阶层。", "error_description": "错误在词尾：「阶层」是抽象名词，不能加「们」表示复数。正确说法是「不同的阶层」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2512b206-61b6-47f3-a7d1-2353d2b9f1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
