INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20542, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "讹误是文字、数字等在抄写或流传中出现的错误。", "primary_collocate": null, "pronunciation": "é wù", "ipa": "ɤ˧˥ u˥˩", "syllable_count": 2, "sentences": [{"text": "这本旧书里有不少讹误。", "target_word": "讹误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师帮我们改正了古书里的讹误。", "target_word": "讹误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古书抄来抄去，难免会有讹误。", "target_word": "讹误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "后人抄写时，这个字出现了讹误。", "target_word": "讹误", "complexity_tier": "T3", "furigana": "hòu rén chāo xiě shí zhè gè zì chū xiàn le é wù", "sentence_source": "generated"}, {"text": "他看出了报告中的几处讹误。", "target_word": "讹误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你检查一下，看看有没有讹误。", "target_word": "讹误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这句话流传很久，已经出现了讹误。", "target_word": "讹误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书中的讹误太多，读起来很难受。", "target_word": "讹误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学者们花了很多年才改正这些讹误。", "target_word": "讹误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的数字有讹误，应该是五十。", "target_word": "讹误", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "处", "label": "量词"}], "register": "书面", "sense_fingerprint": "文字、数字等在抄写或流传中出现的错误", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c13fba2-698e-4727-b25b-42f4c360e701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20542, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "讹误", "is_correct": true, "explanation": "正确：讹误指文字或数字在抄写、流传中出现的错误，旧书里可以有。"}, {"text": "石头", "is_correct": false, "explanation": "语义：书里不会有石头，“有不少石头”与旧书的语境不合。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包不会出现在旧书里，与“有不少”的语境不合。"}, {"text": "海水", "is_correct": false, "explanation": "语义：旧书里不会有海水，“有不少海水”与旧书的语境不合。"}], "explanations": {"讹误": "正确：讹误指文字或数字在抄写、流传中出现的错误，旧书里可以有。", "石头": "语义：书里不会有石头，“有不少石头”与旧书的语境不合。", "面包": "语义：面包不会出现在旧书里，与“有不少”的语境不合。", "海水": "语义：旧书里不会有海水，“有不少海水”与旧书的语境不合。"}, "sentence_index": 0, "correct_answer": "讹误"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试我犯了很多讹误。", "explanation": "这里应该用〈错误〉。讹误多指文字、数字在抄写或流传中的错误，做题的错误要用〈错误〉。"}, {"text": "这里有一颗讹误。", "explanation": "这里应该用〈处〉。〈颗〉用于粒状的东西，讹误应用〈处〉。"}, {"text": "这场比赛他有一次讹误。", "explanation": "这里应该用〈失误〉。讹误指文字或数字的错误，比赛中的差错要用〈失误〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb992c-4cb3-4d2d-b363-c122f580b353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20542, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "讹误", "is_correct": true, "explanation": "正确：讹误指流传中出现的错误，“已经出现了讹误”成立。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：雨水与句子在流传中出现的错误无关，句子里不会出现雨水。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“出现”指事情或问题在流传中显露，冰箱是具体物件，不能这样出现。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：“出现了”后接的是问题或情况，“面积”是度量，不能说“出现了面积”。"}], "explanations": {"讹误": "正确：讹误指流传中出现的错误，“已经出现了讹误”成立。", "雨水": "语义：雨水与句子在流传中出现的错误无关，句子里不会出现雨水。", "冰箱": "语义：“出现”指事情或问题在流传中显露，冰箱是具体物件，不能这样出现。", "面积": "搭配：“出现了”后接的是问题或情况，“面积”是度量，不能说“出现了面积”。"}, "sentence_index": 6, "correct_answer": "讹误"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份合同里有一座讹误。", "explanation": "这里应该用〈处〉。〈座〉用于山、楼等大型固定物，讹误应用〈处〉。"}, {"text": "我和朋友之间有一个讹误。", "explanation": "这里应该用〈误会〉。两人之间的误解要用〈误会〉，讹误指文字或数字的错误。"}, {"text": "他在书里发现了一把讹误。", "explanation": "这里应该用〈处〉。〈把〉用于有柄的器具，讹误不能用“一把”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb992c-4cb3-4d2d-b363-c122f580b353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20542, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "书里有三只讹误。", "corrected_sentence": "书里有三处讹误。", "error_description": "量词错误：讹误应用〈处〉，〈只〉用于动物，不能用于讹误。错误形式“三只讹误”，正确形式“三处讹误”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb992c-4cb3-4d2d-b363-c122f580b353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20542, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这篇文章里有两讹误。", "corrected_sentence": "这篇文章里有两处讹误。", "error_description": "量词缺失：讹误前的数量词“两”后必须有量词〈处〉，应说“两处讹误”，不能省略为“两讹误”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0fb992c-4cb3-4d2d-b363-c122f580b353') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20544, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20544, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20544, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "让一件事情发生。", "primary_collocate": null, "pronunciation": "zhì shǐ", "ipa": "tʂɻ̩˥˩ ʂɻ̩˨˩˦", "syllable_count": 2, "sentences": [{"text": "大雨致使火车晚点了两个小时。", "target_word": "致使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的粗心致使实验失败了。", "target_word": "致使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨晚的大风致使许多树倒了。", "target_word": "致使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机太累，致使车撞到了路边。", "target_word": "致使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器出了问题，致使工厂停工一天。", "target_word": "致使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一场大雾致使飞机不能起飞。", "target_word": "致使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李睡过了头，致使他错过了考试。", "target_word": "致使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天太冷，致使很多花都死了。", "target_word": "致使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水管坏了，致使家里到处是水。", "target_word": "致使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "管理不好，致使公司损失了不少钱。", "target_word": "致使", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "正式", "sense_fingerprint": "某个原因使后面的事情发生，多带不好的结果，如致使失败、致使停工", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f562dea-1484-4d6c-8f48-09986f773a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20544, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "致使", "is_correct": true, "explanation": "正确。“致使”读 zhì shǐ，意思是使某件事情发生。"}, {"text": "致死", "is_correct": false, "explanation": "sǐ 与 shǐ 声母不同（s 与 sh），意思是导致死亡。"}, {"text": "志士", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，意思是有抱负的人。"}, {"text": "指使", "is_correct": false, "explanation": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是支使、差遣。"}], "explanations": {"致使": "正确。“致使”读 zhì shǐ，意思是使某件事情发生。", "致死": "sǐ 与 shǐ 声母不同（s 与 sh），意思是导致死亡。", "志士": "shì（第四声）与 shǐ（第三声）声调不同，意思是有抱负的人。", "指使": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是支使、差遣。"}, "sentence_index": null, "correct_answer": "致使"}, "level_3": {"options": [{"text": "防止", "is_correct": false, "explanation": "语义：“防止”指避免尚未发生的事，句中的晚点已经发生。"}, {"text": "配合", "is_correct": false, "explanation": "搭配：“配合”需要有能参与合作的主体，“大雨”不能与“火车”配合。"}, {"text": "保证", "is_correct": false, "explanation": "语义：“保证”表示担保某事一定会发生，与句中“晚点”这一负面结果不符。"}, {"text": "致使", "is_correct": true, "explanation": "正确。“致使”表示由某个原因引起后面的结果，与“大雨”一句相合。"}], "explanations": {"防止": "语义：“防止”指避免尚未发生的事，句中的晚点已经发生。", "配合": "搭配：“配合”需要有能参与合作的主体，“大雨”不能与“火车”配合。", "保证": "语义：“保证”表示担保某事一定会发生，与句中“晚点”这一负面结果不符。", "致使": "正确。“致使”表示由某个原因引起后面的结果，与“大雨”一句相合。"}, "sentence_index": 0, "correct_answer": "致使"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈的鼓励致使我考上了大学。", "explanation": "这里应该用〈使得〉。“致使”多用于不好的结果，考上大学这类好结果要用“使得”。"}, {"text": "老师致使我们全班去参观博物馆。", "explanation": "这里应该用〈安排〉。“致使”表示无意间造成的结果，老师有计划地组织活动时不能用“致使”。"}, {"text": "我故意致使自己迟到。", "explanation": "这里不能用〈致使〉。“致使”表示无意造成的结果，与“故意”矛盾，应说“我故意迟到”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20544, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "致使", "is_correct": true, "explanation": "正确。“致使”读 zhì shǐ，意思是使某件事情发生。"}, {"text": "支使", "is_correct": false, "explanation": "zhī（第一声）与 zhì（第四声）声调不同，意思是差遣、指使别人做事。"}, {"text": "至死", "is_correct": false, "explanation": "sǐ 与 shǐ 声母不同（s 与 sh），意思是直到死亡。"}, {"text": "制式", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，意思是式样、规格。"}], "explanations": {"致使": "正确。“致使”读 zhì shǐ，意思是使某件事情发生。", "支使": "zhī（第一声）与 zhì（第四声）声调不同，意思是差遣、指使别人做事。", "至死": "sǐ 与 shǐ 声母不同（s 与 sh），意思是直到死亡。", "制式": "shì（第四声）与 shǐ（第三声）声调不同，意思是式样、规格。"}, "sentence_index": null, "correct_answer": "致使"}, "level_3": {"options": [{"text": "避免", "is_correct": false, "explanation": "语义：“避免”指防止尚未发生的事，句中的错过已经发生。"}, {"text": "合作", "is_correct": false, "explanation": "搭配：“合作”需要双方共同行动，“小李”不能与“错过考试”合作。"}, {"text": "阻止", "is_correct": false, "explanation": "语义：“阻止”指制止尚未发生的事，句中的结果已经出现。"}, {"text": "致使", "is_correct": true, "explanation": "正确。“致使”引出由“睡过了头”造成的结果“错过了考试”。"}], "explanations": {"避免": "语义：“避免”指防止尚未发生的事，句中的错过已经发生。", "合作": "搭配：“合作”需要双方共同行动，“小李”不能与“错过考试”合作。", "阻止": "语义：“阻止”指制止尚未发生的事，句中的结果已经出现。", "致使": "正确。“致使”引出由“睡过了头”造成的结果“错过了考试”。"}, "sentence_index": 6, "correct_answer": "致使"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次培训致使大家都学会了新技术。", "explanation": "这里应该用〈让〉。“致使”多用于不好的结果，学会新技术是好的结果，应改用“让”。"}, {"text": "为了省钱，他致使自己每天少吃一顿饭。", "explanation": "这里应该用〈决定〉。“致使”引出的是某事造成的结果，不能用于主语自己有意做出的选择。"}, {"text": "他的好成绩致使父母很高兴。", "explanation": "这里应该用〈使〉。“致使”多用于不好的结果，父母高兴是好的结果，应改用“使”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20544, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天气太热，致使了很多人生病。", "corrected_sentence": "天气太热，致使很多人生病。", "error_description": "错误：“致使了很多人”，正确：“致使很多人”。“致使”后面不能直接加“了”，“致使”后直接接结果即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20544, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他经常熬夜，被致使身体越来越差。", "corrected_sentence": "他经常熬夜，致使身体越来越差。", "error_description": "错误：“被致使身体”，正确：“致使身体”。“致使”是主动动词，前面不能直接加“被”，应去掉“被”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
