INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20548, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "很多地方都在用这个东西。", "primary_collocate": null, "pronunciation": "guǎng fàn yìng yòng", "ipa": "kwɑŋ˨˩ fan˥˩ iŋ˥˩ yʊŋ˥˩", "syllable_count": 4, "sentences": [{"text": "这种技术在工厂里广泛应用。", "target_word": "广泛应用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "二维码在商店和车站广泛应用。", "target_word": "广泛应用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电在我们的生活中广泛应用。", "target_word": "广泛应用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种材料在建筑上广泛应用。", "target_word": "广泛应用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汉语拼音在学校里广泛应用。", "target_word": "广泛应用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "塑料袋曾经在超市广泛应用。", "target_word": "广泛应用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种软件在公司里广泛应用。", "target_word": "广泛应用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机支付在年轻人中广泛应用。", "target_word": "广泛应用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种机器在农村也得到了广泛应用。", "target_word": "广泛应用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空调在南方的家庭中广泛应用。", "target_word": "广泛应用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "某物在许多场合和地方都在使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65ed119e-0d7b-4fd6-9dc2-f9c5d6a85cda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20548, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "广泛应用", "is_correct": true, "explanation": "正确。广泛应用指某种技术在许多场合被普遍使用，与“这种技术在工厂里”相符。"}, {"text": "辩论", "is_correct": false, "explanation": "语义：“辩论”的施事须是人，技术不能辩论。"}, {"text": "恋爱", "is_correct": false, "explanation": "语义：“恋爱”的施事须是人，技术不能恋爱。"}, {"text": "道歉", "is_correct": false, "explanation": "语义：“道歉”的施事须是有意识的人，技术不能道歉。"}], "explanations": {"广泛应用": "正确。广泛应用指某种技术在许多场合被普遍使用，与“这种技术在工厂里”相符。", "辩论": "语义：“辩论”的施事须是人，技术不能辩论。", "恋爱": "语义：“恋爱”的施事须是人，技术不能恋爱。", "道歉": "语义：“道歉”的施事须是有意识的人，技术不能道歉。"}, "sentence_index": 0, "correct_answer": "广泛应用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他广泛应用这次机会学习英语。", "explanation": "这里应该用〈利用〉。广泛应用指某种方法或技术在很多场合普遍使用，只针对一次机会时要说利用。"}, {"text": "我每天广泛应用这把剪刀剪纸。", "explanation": "这里应该用〈使用〉。广泛应用强调在许多场合普遍推广，只用一把剪刀时应说使用。"}, {"text": "他广泛应用了一个拥抱来安慰朋友。", "explanation": "这里应该用〈给〉。广泛应用指方法、技术在许多场合普遍推广，安慰朋友的一个拥抱不是可推广的方法，应说给。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d18738-51dc-4bdc-98ce-94563e09fdad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20548, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "广泛应用", "is_correct": true, "explanation": "正确。广泛应用指软件在很多地方被普遍使用，与“这种软件在公司里”相符。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”是人或动物的活动，软件不能散步。"}, {"text": "出差", "is_correct": false, "explanation": "搭配：“出差”的主语是人，不能说软件出差。"}, {"text": "挑食", "is_correct": false, "explanation": "语义：“挑食”是人吃东西时的习惯，与软件无关。"}], "explanations": {"广泛应用": "正确。广泛应用指软件在很多地方被普遍使用，与“这种软件在公司里”相符。", "散步": "语义：“散步”是人或动物的活动，软件不能散步。", "出差": "搭配：“出差”的主语是人，不能说软件出差。", "挑食": "语义：“挑食”是人吃东西时的习惯，与软件无关。"}, "sentence_index": 6, "correct_answer": "广泛应用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他广泛应用朋友的力量完成了作业。", "explanation": "这里应该用〈借助〉。广泛应用的对象是方法、技术等，“朋友的力量”不能作为它的对象，应说借助。"}, {"text": "我们广泛应用行动解决了问题。", "explanation": "这里应该用〈采取〉。广泛应用的对象是方法、技术，“行动”不是可以普遍推广的对象，应说采取。"}, {"text": "我广泛应用了同学的一本字典。", "explanation": "这里应该用〈借用〉。广泛应用指在许多场合普遍推广，只借一本字典的情况要说借用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d18738-51dc-4bdc-98ce-94563e09fdad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20548, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种方法到医院里广泛应用。", "corrected_sentence": "这种方法在医院里广泛应用。", "error_description": "“到”引出的是动作的终点，不能用来引出“广泛应用”的地点；此处应用“在”，写作“在医院里广泛应用”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d18738-51dc-4bdc-98ce-94563e09fdad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20548, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种技术在农村已经了广泛应用。", "corrected_sentence": "这种技术在农村已经广泛应用。", "error_description": "“了”不能紧接副词“已经”，多出的“了”应删去，正确说法是“这种技术在农村已经广泛应用”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d18738-51dc-4bdc-98ce-94563e09fdad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
