INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20554, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指一群人中特别优秀、出色的人。", "primary_collocate": null, "pronunciation": "jīng yīng", "ipa": "tɕiŋ˥ iŋ˥", "syllable_count": 2, "sentences": [{"text": "这所大学培养了很多社会精英。", "target_word": "精英", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是公司里的精英，大家都很佩服他。", "target_word": "精英", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支球队里都是各国的精英。", "target_word": "精英", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司只招收行业里的精英。", "target_word": "精英", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些精英每天工作十几个小时。", "target_word": "精英", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就想成为社会的精英。", "target_word": "精英", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大会请来了科学界的精英。", "target_word": "精英", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几位精英坐在会议室里讨论新计划。", "target_word": "精英", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是班里的精英，每次考试都是第一。", "target_word": "精英", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个团队集合了各行业的精英。", "target_word": "精英", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "群", "label": "量词"}, {"form": "批", "label": "量词"}], "register": "中性", "sense_fingerprint": "人群中特别优秀出色的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '083b86a6-9f7b-4d1f-ab6f-174ff48943e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20554, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "精英", "is_correct": true, "explanation": "正确。“社会精英”指社会中特别优秀的人，正是“培养”的对象。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果是植物的果实，不能与“社会”组合，也不是可以培养的人。"}, {"text": "工具", "is_correct": false, "explanation": "搭配：“培养”的对象是人，不能说培养工具。"}, {"text": "植物", "is_correct": false, "explanation": "语义：植物不是“社会”的成员，与“培养了很多社会……”的人群语境不符。"}], "explanations": {"精英": "正确。“社会精英”指社会中特别优秀的人，正是“培养”的对象。", "水果": "语义：水果是植物的果实，不能与“社会”组合，也不是可以培养的人。", "工具": "搭配：“培养”的对象是人，不能说培养工具。", "植物": "语义：植物不是“社会”的成员，与“培养了很多社会……”的人群语境不符。"}, "sentence_index": 0, "correct_answer": "精英"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班来了一台精英，他的成绩在年级排前三。", "explanation": "这里应该用〈位〉。台是机器等物品的量词，精英指人，不能用“台”来数。"}, {"text": "这家店卖的都是高档精英，价格很贵。", "explanation": "这里应该用〈精品〉。精英指人，不能用来指商品，商品要说精品。"}, {"text": "这道数学题是今天考试的精英。", "explanation": "这里应该用〈难题〉。精英指一群人中特别优秀的人，不能用来形容题目。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20554, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "精英", "is_correct": true, "explanation": "正确。“科学界的精英”指科学界中特别优秀的人，正是大会请来的对象。"}, {"text": "水稻", "is_correct": false, "explanation": "语义：水稻是作物，不是科学界的人，与“科学界的”不符。"}, {"text": "盘子", "is_correct": false, "explanation": "搭配：“请来”的对象是人，不能请来盘子。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不是人群，不能说“科学界的天气”。"}], "explanations": {"精英": "正确。“科学界的精英”指科学界中特别优秀的人，正是大会请来的对象。", "水稻": "语义：水稻是作物，不是科学界的人，与“科学界的”不符。", "盘子": "搭配：“请来”的对象是人，不能请来盘子。", "天气": "语义：天气是自然现象，不是人群，不能说“科学界的天气”。"}, "sentence_index": 6, "correct_answer": "精英"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子是今年设计的精英，价格却很低。", "explanation": "这里应该用〈代表〉。精英指人，不能用来指家具，说椅子是某类设计的代表。"}, {"text": "这杯茶的精英全在第一泡里。", "explanation": "这里应该用〈精华〉。精英指人，不能指事物的精髓，那要说精华。"}, {"text": "这个团队来了一只精英，他的工作效率很高。", "explanation": "这里应该用〈位〉。“只”多用于动物或个别物品，指人应用“位”或“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20554, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工作室里有一只精英，他的设计很受欢迎。", "corrected_sentence": "工作室里有一位精英，他的设计很受欢迎。", "error_description": "错误在量词“只”。精英指人，应用量词“位”；“只”多用于动物或个别物品，用于人不合适。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20554, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她是我们学校的精英们，老师都很喜欢她。", "corrected_sentence": "她是我们学校的精英，老师都很喜欢她。", "error_description": "错误在“们”与“她”不一致：“她”只指一个人，不能与表示复数的“们”搭配，应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
