INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20558, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "第一次做出新东西。", "primary_collocate": null, "pronunciation": "shǒu chuàng", "ipa": "ʂou˨˩ ʈʂʰuaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这个小城市首创了无人商店。", "target_word": "首创", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁首创了这种新玩具？", "target_word": "首创", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们班首创了一种新的游戏。", "target_word": "首创", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是我们村首创的种树办法。", "target_word": "首创", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂首创了用纸做的杯子。", "target_word": "首创", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他首创过一种很好吃的面包。", "target_word": "首创", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种菜是奶奶首创的，别的地方没有。", "target_word": "首创", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所学校首创了周末音乐课。", "target_word": "首创", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王首创了一种新的画画方法。", "target_word": "首创", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市首创的公交卡，现在全国都在用。", "target_word": "首创", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "首创了", "label": "体标"}, {"form": "首创过", "label": "体标"}, {"form": "首创者", "label": "复合"}], "register": "书面", "sense_fingerprint": "第一次做出新东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ab2749-257c-4c70-be8d-c6367b76fc36') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20558, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "背诵", "is_correct": false, "explanation": "搭配：「背诵」的对象是课文或诗词，不能说背诵无人商店。"}, {"text": "翻译", "is_correct": false, "explanation": "搭配：「翻译」的对象是语言文字，不能说翻译商店。"}, {"text": "逃离", "is_correct": false, "explanation": "语义：「逃离」指离开令人难受的地方，城市不会逃离自己建的商店。"}, {"text": "首创", "is_correct": true, "explanation": "正确：「首创」指第一次做出，与「无人商店」的新事物相合。"}], "explanations": {"背诵": "搭配：「背诵」的对象是课文或诗词，不能说背诵无人商店。", "翻译": "搭配：「翻译」的对象是语言文字，不能说翻译商店。", "逃离": "语义：「逃离」指离开令人难受的地方，城市不会逃离自己建的商店。", "首创": "正确：「首创」指第一次做出，与「无人商店」的新事物相合。"}, "sentence_index": 0, "correct_answer": "首创"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们首创了别村的种树办法。", "explanation": "这里应该用〈学习〉。首创指第一次做出，别村已有的办法只能说学习。"}, {"text": "他首创了别人已经用过的修路方法。", "explanation": "这里应该用〈模仿〉。别人已经用过的修路方法，照着做要说模仿，首创指第一次做出。"}, {"text": "这家店首创了别人的招牌。", "explanation": "这里应该用〈抄袭〉。首创指原创的第一次，不能用于把别人的招牌据为己有。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a14e0eff-779a-45b1-b97c-f8696dcfa583') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20558, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "游泳", "is_correct": false, "explanation": "配价：「游泳」是不及物动词，不能说「奶奶游泳的菜」。"}, {"text": "发愁", "is_correct": false, "explanation": "配价：「发愁」是不及物动词，不能带「菜」作受事。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：「唱」的对象是歌曲，不能说唱菜。"}, {"text": "首创", "is_correct": true, "explanation": "正确：「首创」指第一次做出，与「别的地方没有」相合。"}], "explanations": {"游泳": "配价：「游泳」是不及物动词，不能说「奶奶游泳的菜」。", "发愁": "配价：「发愁」是不及物动词，不能带「菜」作受事。", "唱": "搭配：「唱」的对象是歌曲，不能说唱菜。", "首创": "正确：「首创」指第一次做出，与「别的地方没有」相合。"}, "sentence_index": 6, "correct_answer": "首创"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们首创了国外的经验。", "explanation": "这里应该用〈借鉴〉。国外已有的经验只能说借鉴，首创指第一次做出。"}, {"text": "他首创了祖传的手艺。", "explanation": "这里应该用〈继承〉。祖传的手艺是前人传下来的，只能说继承。"}, {"text": "他首创了三千年前就有的节日。", "explanation": "这里应该用〈沿袭〉。三千年前就有的节日是前人留下的，只能说沿袭，首创指第一次做出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a14e0eff-779a-45b1-b97c-f8696dcfa583') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20558, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司首创的了一种新型电池。", "corrected_sentence": "这家公司首创了一种新型电池。", "error_description": "助词错误：“首创”表示完成后应接“了”，“的”与“了”不能同时用，应说“这家公司首创了一种新型电池”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a14e0eff-779a-45b1-b97c-f8696dcfa583') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20558, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种玩具是小王首创了的。", "corrected_sentence": "这种玩具是小王首创的。", "error_description": "「是……的」句中，「首创」后面直接接「的」，不能再加「了」，应说「是小王首创的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a14e0eff-779a-45b1-b97c-f8696dcfa583') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
