INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20570, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "写和读的时候用的符号。", "primary_collocate": null, "pronunciation": "hàn zì", "ipa": "xan˥˩ tsɨ˥˩", "syllable_count": 2, "sentences": [{"text": "我今天在本子上写了二十个汉字。", "target_word": "汉字", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个汉字我不会读，你能教我吗？", "target_word": "汉字", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师在黑板上写了一个大大的汉字。", "target_word": "汉字", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明已经认识三百多个汉字了。", "target_word": "汉字", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张海报上的汉字太小，我看不清。", "target_word": "汉字", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的汉字写得又快又漂亮。", "target_word": "汉字", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我妈妈的名字里有一个很难写的汉字。", "target_word": "汉字", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把这几个汉字抄三遍。", "target_word": "汉字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菜单上的汉字我都认识，可是意思不懂。", "target_word": "汉字", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们每天读汉字、写汉字，进步很快。", "target_word": "汉字", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "漢字", "label": "繁体"}, {"form": "常用汉字", "label": "复合"}], "register": "中性", "sense_fingerprint": "日常书写和阅读时具体使用的一个个汉语文字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '859509cb-ef91-48f7-818c-847e5d1c3de5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20570, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "汉字", "is_correct": true, "explanation": "正确。「写」的对象是文字，「二十个」指写下的文字符号。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：「桌子」不是能写在本子上的东西，句子不通。"}, {"text": "花朵", "is_correct": false, "explanation": "搭配：「写」用于文字、符号，不能与「花朵」搭配。"}, {"text": "脚印", "is_correct": false, "explanation": "语义：「脚印」是脚踩出的痕迹，不能写在本子上。"}], "explanations": {"汉字": "正确。「写」的对象是文字，「二十个」指写下的文字符号。", "桌子": "语义：「桌子」不是能写在本子上的东西，句子不通。", "花朵": "搭配：「写」用于文字、符号，不能与「花朵」搭配。", "脚印": "语义：「脚印」是脚踩出的痕迹，不能写在本子上。"}, "sentence_index": 0, "correct_answer": "汉字"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个汉字由三个字母组成。", "explanation": "这里应该用〈拼音〉。拼音由字母拼成，汉字由笔画和部件组成，不是由字母拼成的。"}, {"text": "这个汉字有三个音节。", "explanation": "这里应该用〈词〉。一个汉字一般只是一个音节，有三个音节要说〈词〉。"}, {"text": "英语一共有二十六个汉字。", "explanation": "这里应该用〈字母〉。英语是用字母书写的，汉字是汉语的书写符号，英语里没有汉字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aa7f61f-2729-4d5d-99e7-c6c8d654eeee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20570, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "汉字", "is_correct": true, "explanation": "正确。名字里的组成部分是文字，「很难写的汉字」指书写难的字。"}, {"text": "音符", "is_correct": false, "explanation": "语义：「音符」只出现在乐谱里，不能是名字的组成部分。"}, {"text": "汗水", "is_correct": false, "explanation": "搭配：「难写」只用于文字，不能说汗水难写。"}, {"text": "云朵", "is_correct": false, "explanation": "语义：「云朵」不能写在名字里，与「名字里」「很难写」矛盾。"}], "explanations": {"汉字": "正确。名字里的组成部分是文字，「很难写的汉字」指书写难的字。", "音符": "语义：「音符」只出现在乐谱里，不能是名字的组成部分。", "汗水": "搭配：「难写」只用于文字，不能说汗水难写。", "云朵": "语义：「云朵」不能写在名字里，与「名字里」「很难写」矛盾。"}, "sentence_index": 6, "correct_answer": "汉字"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是外国人，汉字说得很流利。", "explanation": "这里应该用〈汉语〉。说的是口头语言，汉字是写和读的符号，说得流利要用〈汉语〉。"}, {"text": "这道题有一个汉字算错了。", "explanation": "这里应该用〈数字〉。算错要用于数字，汉字是写出来的，不能说算错。"}, {"text": "孩子们用汉字搭房子。", "explanation": "这里应该用〈积木〉。搭房子要用积木，汉字是书写符号，不能用来搭建东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aa7f61f-2729-4d5d-99e7-c6c8d654eeee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20570, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹在纸上认真地写了一条汉字。", "corrected_sentence": "妹妹在纸上认真地写了一个汉字。", "error_description": "错误形式：「一条汉字」；正确形式：「一个汉字」。「条」用于细长的东西，如裤子、河流，汉字应该用量词「个」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aa7f61f-2729-4d5d-99e7-c6c8d654eeee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20570, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们把这条汉字写得很整齐。", "corrected_sentence": "孩子们把这个汉字写得很整齐。", "error_description": "错误形式：「这条汉字」；正确形式：「这个汉字」。「条」用于细长的东西，如裤子、河流，汉字应该用量词「个」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aa7f61f-2729-4d5d-99e7-c6c8d654eeee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
