INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20572, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把字、图片等放在合适的位置。", "primary_collocate": null, "pronunciation": "pái bǎn", "ipa": "pʰai˧˥ pan˨˩", "syllable_count": 2, "sentences": [{"text": "小王正在给新书排版。", "target_word": "排版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "排版时，要把图片放在合适的位置。", "target_word": "排版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份作业我已经排版好了。", "target_word": "排版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用电脑给照片和文字排版。", "target_word": "排版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "排版以前，先想好哪里放字，哪里放图。", "target_word": "排版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张海报我排版了两个小时。", "target_word": "排版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈不会排版，所以请朋友帮忙。", "target_word": "排版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的小报每个月都由同学们自己排版。", "target_word": "排版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他排版很慢，一页要用半个小时。", "target_word": "排版", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎样给班报排版。", "target_word": "排版", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "排版了", "label": "体标"}, {"form": "排版过", "label": "体标"}, {"form": "排版师", "label": "复合"}], "register": "中性", "sense_fingerprint": "把字和图片放在合适的位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ab2749-257c-4c70-be8d-c6367b76fc36') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20572, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "排版", "is_correct": true, "explanation": "正确：排版（pái bǎn）指把字、图片放在合适的位置。"}, {"text": "拍板", "is_correct": false, "explanation": "拍板（pāi bǎn）第一音节 pāi 为第一声，与 pái（第二声）声调不同，意思是拍板（做决定）。"}, {"text": "白板", "is_correct": false, "explanation": "白板（bái bǎn）第一音节声母为 b，与 p 不同，意思是白色的板子。"}, {"text": "排班", "is_correct": false, "explanation": "排班（pái bān）第二音节 bān 为第一声，与 bǎn（第三声）声调不同，意思是安排轮班。"}, {"text": "排满", "is_correct": false, "explanation": "排满（pái mǎn）第二音节声母为 m，与 b 不同，意思是排列到满。"}], "explanations": {"排版": "正确：排版（pái bǎn）指把字、图片放在合适的位置。", "拍板": "拍板（pāi bǎn）第一音节 pāi 为第一声，与 pái（第二声）声调不同，意思是拍板（做决定）。", "白板": "白板（bái bǎn）第一音节声母为 b，与 p 不同，意思是白色的板子。", "排班": "排班（pái bān）第二音节 bān 为第一声，与 bǎn（第三声）声调不同，意思是安排轮班。", "排满": "排满（pái mǎn）第二音节声母为 m，与 b 不同，意思是排列到满。"}, "sentence_index": null, "correct_answer": "排版"}, "level_3": {"options": [{"text": "排版", "is_correct": true, "explanation": "正确：排版指把字、图片放在合适的位置，此处是给新书做版面。"}, {"text": "切割", "is_correct": false, "explanation": "语义：切割指把物体切开，与“给新书”编排字和图的版面无关。"}, {"text": "喂养", "is_correct": false, "explanation": "搭配：喂养用于动物或婴儿，不能用于书籍。"}, {"text": "冲洗", "is_correct": false, "explanation": "搭配：冲洗用于照片、胶卷，不能用于新书。"}], "explanations": {"排版": "正确：排版指把字、图片放在合适的位置，此处是给新书做版面。", "切割": "语义：切割指把物体切开，与“给新书”编排字和图的版面无关。", "喂养": "搭配：喂养用于动物或婴儿，不能用于书籍。", "冲洗": "搭配：冲洗用于照片、胶卷，不能用于新书。"}, "sentence_index": 0, "correct_answer": "排版"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她把桌子排版在教室中间。", "explanation": "这里应该用〈摆放〉。排版指排列文字、图片的版面，桌子在教室里的位置要用〈摆放〉。"}, {"text": "这位画家排版了一幅风景画。", "explanation": "这里应该用〈绘制〉。排版指排列文字、图片的版面，画风景画要用〈绘制〉。"}, {"text": "妈妈排版了周末的聚会。", "explanation": "这里应该用〈策划〉。排版只用于文字、图片的版面，聚会的安排要用〈策划〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a14e0eff-779a-45b1-b97c-f8696dcfa583') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20572, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "排版", "is_correct": true, "explanation": "正确：排版指把字、图片放在合适的位置，此处是妈妈不会做的版面工作。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：下雨是天气现象，不是人会不会做的事，不能说“妈妈不会下雨”。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉是本能，不是需要学会的技能，说“不会睡觉”与语境不符。"}, {"text": "发烧", "is_correct": false, "explanation": "搭配：发烧是身体状况，不能用“不会发烧”来表示需要别人帮忙。"}], "explanations": {"排版": "正确：排版指把字、图片放在合适的位置，此处是妈妈不会做的版面工作。", "下雨": "语义：下雨是天气现象，不是人会不会做的事，不能说“妈妈不会下雨”。", "睡觉": "语义：睡觉是本能，不是需要学会的技能，说“不会睡觉”与语境不符。", "发烧": "搭配：发烧是身体状况，不能用“不会发烧”来表示需要别人帮忙。"}, "sentence_index": 6, "correct_answer": "排版"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "姐姐每天排版她的指甲，很好看。", "explanation": "这里应该用〈修剪〉。排版指排列文字、图片的版面，修整指甲要用〈修剪〉，不能用排版。"}, {"text": "他排版了那只小鸟。", "explanation": "这里应该用〈喂养〉。排版指排列文字、图片的版面，照料小鸟要用〈喂养〉，不能用排版。"}, {"text": "工人排版了那座桥。", "explanation": "这里应该用〈修建〉。排版指排列文字、图片的版面，桥梁的建造要用〈修建〉，不能用排版。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a14e0eff-779a-45b1-b97c-f8696dcfa583') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20572, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她帮我把这篇作文排版了好。", "corrected_sentence": "她帮我把这篇作文排版好了。", "error_description": "结果补语错误：“排版”的结果补语“好”应紧跟动词，再接“了”，应说“排版好了”，“排版了好”不通顺。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a14e0eff-779a-45b1-b97c-f8696dcfa583') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20572, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师这张海报排版。", "corrected_sentence": "老师给这张海报排版。", "error_description": "漏用介词：引出动作对象“这张海报”的“给”不能省略，应说“老师给这张海报排版”；去掉“给”后，“这张海报”直接放在动词前，句子不通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a14e0eff-779a-45b1-b97c-f8696dcfa583') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
