INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20574, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "东西有多少。", "primary_collocate": null, "pronunciation": "shù liàng", "ipa": "ʂu˥˩ ljɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这家店的苹果数量很多。", "target_word": "数量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今年我们学校的学生数量比去年多。", "target_word": "数量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上的杯子数量不对，少了一个。", "target_word": "数量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水果的质量好，数量也够。", "target_word": "数量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂每天做的鞋，数量很大。", "target_word": "数量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先检查一下货物的数量。", "target_word": "数量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的汽车数量越来越多。", "target_word": "数量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种鱼的数量很少，所以很贵。", "target_word": "数量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买东西不问价钱，只问数量。", "target_word": "数量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河里的鱼数量变少了。", "target_word": "数量", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "數量", "label": "繁体"}, {"form": "数量词", "label": "复合"}], "register": "中性", "sense_fingerprint": "数量：东西的多少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f562dea-1484-4d6c-8f48-09986f773a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20574, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "数量", "is_correct": true, "explanation": "“数量”指东西有多少，与“很多”搭配，填入后语义通顺。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”说贵贱、高低，不说“很多”。"}, {"text": "地址", "is_correct": false, "explanation": "语义：“地址”指位置，不是可以计数的东西，与“苹果”不搭。"}, {"text": "距离", "is_correct": false, "explanation": "搭配：“距离”说远近，不能说“苹果距离很多”。"}], "explanations": {"数量": "“数量”指东西有多少，与“很多”搭配，填入后语义通顺。", "价格": "搭配：“价格”说贵贱、高低，不说“很多”。", "地址": "语义：“地址”指位置，不是可以计数的东西，与“苹果”不搭。", "距离": "搭配：“距离”说远近，不能说“苹果距离很多”。"}, "sentence_index": 0, "correct_answer": "数量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店的苹果数量很香。", "explanation": "这里应该用〈味道〉。香形容气味或味道，数量只说多少，不能这样形容。"}, {"text": "这家店的苹果数量很便宜。", "explanation": "这里应该用〈价格〉。便宜、贵说价格，数量不能这样形容。"}, {"text": "这种电池的数量很长。", "explanation": "这里应该用〈寿命〉。长短说寿命，数量只说多少。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20574, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "数量", "is_correct": true, "explanation": "“数量”指多少，与“越来越多”搭配，语义通顺。"}, {"text": "速度", "is_correct": false, "explanation": "搭配：“速度”说快慢，不说“越来越多”。"}, {"text": "人口", "is_correct": false, "explanation": "语义：“人口”指人的数量，不能用来说汽车。"}, {"text": "亮度", "is_correct": false, "explanation": "语义：“亮度”指明暗程度，与“汽车”和“越来越多”都不搭。"}], "explanations": {"数量": "“数量”指多少，与“越来越多”搭配，语义通顺。", "速度": "搭配：“速度”说快慢，不说“越来越多”。", "人口": "语义：“人口”指人的数量，不能用来说汽车。", "亮度": "语义：“亮度”指明暗程度，与“汽车”和“越来越多”都不搭。"}, "sentence_index": 6, "correct_answer": "数量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这朵花的数量很鲜艳。", "explanation": "这里应该用〈颜色〉。鲜艳形容颜色，数量不能这样形容。"}, {"text": "这个班的数量很有礼貌。", "explanation": "这里应该用〈同学〉。有礼貌形容人的行为，数量只说多少，不能这样形容。"}, {"text": "他的数量很重。", "explanation": "这里应该用〈体重〉。轻重说体重，数量不能这样形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20574, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "仓库里有一个数量的苹果。", "corrected_sentence": "仓库里有一定数量的苹果。", "error_description": "“数量”前不能用量词“个”修饰，应说“一定数量”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20574, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这片湖的鱼数量明显变少着。", "corrected_sentence": "这片湖的鱼数量明显变少了。", "error_description": "“变少”作结果补语，表示变化已完成，要用“了”，不能用“着”，应说“变少了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
