INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20576, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "手抄本是一个人用手写的书。", "primary_collocate": null, "pronunciation": "shǒu chāo běn", "ipa": "ʂoʊ̯˨˩˦ ʈʂʰɑʊ̯˥ pən˨˩˦", "syllable_count": 3, "sentences": [{"text": "这本手抄本有三百年的历史了。", "target_word": "手抄本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "印刷术出现以前，书大多是手抄本。", "target_word": "手抄本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有一本很旧的手抄本。", "target_word": "手抄本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有一本爷爷留下的手抄本，里面是古诗。", "target_word": "手抄本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本手抄本的字迹保存得很好。", "target_word": "手抄本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们看了一本唐代的手抄本。", "target_word": "手抄本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手抄本是人一个字一个字写出来的。", "target_word": "手抄本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为是手抄本，所以每一本都不一样。", "target_word": "手抄本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆很小心地保存着这些手抄本。", "target_word": "手抄本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本手抄本不是印的，是用笔写的。", "target_word": "手抄本", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "本", "label": "量词"}, {"form": "古代手抄本", "label": "复合"}], "register": "中性", "sense_fingerprint": "用手抄写而成的书，不是印刷的书", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '245410d8-ef7c-4e0b-b864-35d4e472cd06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20576, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "手抄本", "is_correct": true, "explanation": "“手抄本”是手写的书，可以有三百年的历史。"}, {"text": "报纸", "is_correct": false, "explanation": "搭配：报纸不用量词“本”，而且报纸是印刷品，不说“这本报纸”。"}, {"text": "电子书", "is_correct": false, "explanation": "语义：“电子书”是电子设备上的书，不可能有三百年的历史。"}, {"text": "练习本", "is_correct": false, "explanation": "搭配：“有……历史”多用于古旧或有来历的物品，“练习本”不与之搭配。"}], "explanations": {"手抄本": "“手抄本”是手写的书，可以有三百年的历史。", "报纸": "搭配：报纸不用量词“本”，而且报纸是印刷品，不说“这本报纸”。", "电子书": "语义：“电子书”是电子设备上的书，不可能有三百年的历史。", "练习本": "搭配：“有……历史”多用于古旧或有来历的物品，“练习本”不与之搭配。"}, "sentence_index": 0, "correct_answer": "手抄本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "图书馆里有一张很旧的手抄本。", "explanation": "这里应该用〈本〉。手抄本是书，量词用“本”，不用“张”。"}, {"text": "这本手抄本是今年刚出版的新书。", "explanation": "“手抄本”是手写的书，不是出版社出版的，与“刚出版”矛盾。"}, {"text": "这本手抄本是机器一分钟印出来的，很快就做好了。", "explanation": "“手抄本”是手写的书，不是机器印刷的，与“机器印出来”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340804dc-70db-472b-8fc9-1556bee5f82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20576, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手抄本", "is_correct": true, "explanation": "“手抄本”是一个字一个字手写出来的，符合句意。"}, {"text": "印刷品", "is_correct": false, "explanation": "语义：“印刷品”是机器印出来的，不是人手写的。"}, {"text": "复印件", "is_correct": false, "explanation": "语义：“复印件”是复印机做的，不是人手写的。"}, {"text": "打印稿", "is_correct": false, "explanation": "搭配：“一个字一个字写”指手写，与“打印”不搭配。"}], "explanations": {"手抄本": "“手抄本”是一个字一个字手写出来的，符合句意。", "印刷品": "语义：“印刷品”是机器印出来的，不是人手写的。", "复印件": "语义：“复印件”是复印机做的，不是人手写的。", "打印稿": "搭配：“一个字一个字写”指手写，与“打印”不搭配。"}, "sentence_index": 6, "correct_answer": "手抄本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本手抄本是我用键盘一个字一个字打出来的。", "explanation": "“手抄本”指用手写的书，用键盘打出来的不能叫手抄本。"}, {"text": "这本手抄本上的字都是用印章盖上去的。", "explanation": "“手抄”指用手写，用印章盖上的字不算手抄。"}, {"text": "这本手抄本一共印了一万本，全部送给了学生。", "explanation": "“手抄本”每一本都是手写的，不能大量印刷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340804dc-70db-472b-8fc9-1556bee5f82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20576, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把爷爷的一张手抄本借给了朋友。", "corrected_sentence": "他把爷爷的一本手抄本借给了朋友。", "error_description": "“手抄本”是书，量词应用“本”，不能用“张”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340804dc-70db-472b-8fc9-1556bee5f82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20576, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他有一只手抄本，是爷爷留下的。", "corrected_sentence": "他有一本手抄本，是爷爷留下的。", "error_description": "“手抄本”是书，量词应该用“本”，不能用“只”。应说“一本手抄本”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '340804dc-70db-472b-8fc9-1556bee5f82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20580, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放宽", "is_correct": true, "explanation": "放宽：让范围变大，与“限制”相反。"}, {"text": "赞美", "is_correct": false, "explanation": "赞美指表扬，与“限制”没有反义关系。"}, {"text": "思考", "is_correct": false, "explanation": "思考指动脑想问题，与“限制”没有反义关系。"}, {"text": "观察", "is_correct": false, "explanation": "观察指仔细看，与“限制”没有反义关系。"}], "correct_answer": "放宽", "explanations": {"放宽": "放宽：让范围变大，与“限制”相反。", "赞美": "赞美指表扬，与“限制”没有反义关系。", "思考": "思考指动脑想问题，与“限制”没有反义关系。", "观察": "观察指仔细看，与“限制”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20580, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放宽", "is_correct": true, "explanation": "放宽：让限制变松，与“限制”相反。"}, {"text": "尊重", "is_correct": false, "explanation": "尊重指重视他人，与“限制”没有反义关系。"}, {"text": "参观", "is_correct": false, "explanation": "参观指去看场所或展览，与“限制”没有反义关系。"}, {"text": "修建", "is_correct": false, "explanation": "修建指建造，与“限制”没有反义关系。"}], "correct_answer": "放宽", "explanations": {"放宽": "放宽：让限制变松，与“限制”相反。", "尊重": "尊重指重视他人，与“限制”没有反义关系。", "参观": "参观指去看场所或展览，与“限制”没有反义关系。", "修建": "修建指建造，与“限制”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20580, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不让超过某个范围。", "primary_collocate": null, "pronunciation": "xiàn zhì", "ipa": "ɕjɛn⁵¹ ʈʂɻ̩⁵¹", "syllable_count": 2, "sentences": [{"text": "学校限制学生带手机进教室。", "target_word": "限制", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路限制大车通过。", "target_word": "限制", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生限制爸爸每天喝酒。", "target_word": "限制", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公园限制进去的人数。", "target_word": "限制", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈限制我每天玩游戏的时间。", "target_word": "限制", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店限制每人只能买两个。", "target_word": "限制", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大雨限制了我们的活动。", "target_word": "限制", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师没有限制我们用什么方法。", "target_word": "限制", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个地方限制停车。", "target_word": "限制", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "父母不应该限制孩子的想法。", "target_word": "限制", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "限制了", "label": "体标"}, {"form": "限制着", "label": "体标"}, {"form": "限制过", "label": "体标"}], "register": "中性", "sense_fingerprint": "动词：规定范围，不让超出（人数、时间、行为等）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '083b86a6-9f7b-4d1f-ab6f-174ff48943e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20580, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "限制", "is_correct": true, "explanation": "限制：不让超过某个范围，符合“学校不让学生带手机”的意思。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃的对象是食物，不能是学生。"}, {"text": "修理", "is_correct": false, "explanation": "语义：修理的对象是物品，不能用于学生。"}, {"text": "生产", "is_correct": false, "explanation": "搭配：“生产”的对象是产品，不能说“生产学生”。"}], "explanations": {"限制": "限制：不让超过某个范围，符合“学校不让学生带手机”的意思。", "吃": "语义：吃的对象是食物，不能是学生。", "修理": "语义：修理的对象是物品，不能用于学生。", "生产": "搭配：“生产”的对象是产品，不能说“生产学生”。"}, "sentence_index": 0, "correct_answer": "限制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子限制了三岁。", "explanation": "这里应该用〈才〉。“限制”表示不让超过界限，不能用来说年龄小，应说“才三岁”。"}, {"text": "他把手机限制在桌子上就出去了。", "explanation": "这里应该用〈放〉。“限制”表示不让超过范围，不能表示把东西摆在某处，应说“放在桌子上”。"}, {"text": "这座城市限制了三十年的历史。", "explanation": "限制不能用于说明历史的长度。这里应该用〈经历〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20580, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "限制", "is_correct": true, "explanation": "限制：不让超出范围，符合“大雨影响活动”的意思。"}, {"text": "赞叹", "is_correct": false, "explanation": "语义：赞叹需要人的感情，大雨不能赞叹活动。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：翻译是把语言换成另一种语言，不能用于大雨。"}, {"text": "播放", "is_correct": false, "explanation": "搭配：播放多用于影像或声音，不用于大雨和活动。"}], "explanations": {"限制": "限制：不让超出范围，符合“大雨影响活动”的意思。", "赞叹": "语义：赞叹需要人的感情，大雨不能赞叹活动。", "翻译": "语义：翻译是把语言换成另一种语言，不能用于大雨。", "播放": "搭配：播放多用于影像或声音，不用于大雨和活动。"}, "sentence_index": 6, "correct_answer": "限制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台显微镜把细胞限制了一百倍。", "explanation": "这里应该用〈放大〉。“限制”指不让超过界限，不能用来表示细胞被放大的倍数。"}, {"text": "这次考试限制了我的心情。", "explanation": "这里应该用〈影响〉。“限制”是对行动或范围加以约束，不能用来说“限制心情”。"}, {"text": "这家店限制了苹果的甜味。", "explanation": "这里应该用〈减少〉。“限制”是不让超过界限，不能用来说苹果甜味的变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20580, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个活动限制三十人以内。", "corrected_sentence": "这个活动限制在三十人以内。", "error_description": "错误：“限制三十人以内”；正确：“限制在三十人以内”。表示范围的结构要用“在”引出，缺少“在”，句子不完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20580, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈没有限制了我看电视的时间。", "corrected_sentence": "妈妈没有限制我看电视的时间。", "error_description": "错误：“没有限制了”；正确：“没有限制”。用“没有”否定的动作后面不能再加“了”，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
