INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20586, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "像大海里一个接一个的大水波。", "primary_collocate": null, "pronunciation": "làng cháo", "ipa": "lɑŋ˥˩ tʂʰɑʊ˧˥", "syllable_count": 2, "sentences": [{"text": "海上的浪潮一阵接一阵。", "target_word": "浪潮", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "浪潮拍打着海边的石头。", "target_word": "浪潮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里我听见远处浪潮的声音。", "target_word": "浪潮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "浪潮退去后，沙滩上有很多小贝壳。", "target_word": "浪潮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大船在浪潮里慢慢向前走。", "target_word": "浪潮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风很大，海上的浪潮越来越高。", "target_word": "浪潮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们站在海边，看浪潮一次次涌来。", "target_word": "浪潮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "渔船在浪潮中晃来晃去。", "target_word": "浪潮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的浪潮冲走了沙子上的字。", "target_word": "浪潮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "浪潮把小船推到了岸边。", "target_word": "浪潮", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一波浪潮", "label": "量词"}, {"form": "一阵浪潮", "label": "量词"}], "register": "书面", "sense_fingerprint": "浪潮：海里一个接一个涌来的大水波", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ff47f7-e50e-4937-9c6f-4d98586d83d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20586, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "浪潮", "is_correct": true, "explanation": "正确答案。“海上的浪潮一阵接一阵”描述海浪一波接一波地涌来。"}, {"text": "岩石", "is_correct": false, "explanation": "语义：岩石不会一阵接一阵地出现在海上，与海面的动态不符。"}, {"text": "脚印", "is_correct": false, "explanation": "搭配：“一阵接一阵”多用于声音、风雨、海浪等，不用于脚印。"}, {"text": "灯塔", "is_correct": false, "explanation": "语义：灯塔是固定的建筑，不会一阵接一阵地出现。"}], "explanations": {"浪潮": "正确答案。“海上的浪潮一阵接一阵”描述海浪一波接一波地涌来。", "岩石": "语义：岩石不会一阵接一阵地出现在海上，与海面的动态不符。", "脚印": "搭配：“一阵接一阵”多用于声音、风雨、海浪等，不用于脚印。", "灯塔": "语义：灯塔是固定的建筑，不会一阵接一阵地出现。"}, "sentence_index": 0, "correct_answer": "浪潮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的学习成绩达到了浪潮。", "explanation": "这里应该用〈高峰〉。“浪潮”指海里一个接一个的大水波，成绩达到顶点要用高峰。"}, {"text": "这部电影的浪潮是最后十分钟。", "explanation": "这里应该用〈高潮〉。“浪潮”指海里的大水波，不指电影最精彩的部分。"}, {"text": "他把浪潮放进了冰箱。", "explanation": "这里应该用〈牛奶〉。“放进冰箱”的对象是食物或饮品，“浪潮”不能冷藏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52471281-3756-4e87-a66a-c94079c46cb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20586, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "浪潮", "is_correct": true, "explanation": "正确答案。“看浪潮一次次涌来”描述孩子们看着海浪一次次扑上来。"}, {"text": "钟声", "is_correct": false, "explanation": "语义：钟声是听到的，不能用“看”来形容它一次次涌来。"}, {"text": "树木", "is_correct": false, "explanation": "语义：树木不会一次次涌来，与“看……涌来”的情境不符。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“涌来”多用于水流、人群，不用于石头。"}], "explanations": {"浪潮": "正确答案。“看浪潮一次次涌来”描述孩子们看着海浪一次次扑上来。", "钟声": "语义：钟声是听到的，不能用“看”来形容它一次次涌来。", "树木": "语义：树木不会一次次涌来，与“看……涌来”的情境不符。", "石头": "搭配：“涌来”多用于水流、人群，不用于石头。"}, "sentence_index": 6, "correct_answer": "浪潮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把浪潮装进了书包。", "explanation": "这里应该用〈课本〉。“装进书包”的对象是可以装的物品，“浪潮”不能装。"}, {"text": "他的身高达到了浪潮。", "explanation": "这里应该用〈顶峰〉。“浪潮”指海里一个接一个的大水波，不能用来形容身高。"}, {"text": "我的浪潮饿了，想吃一碗面。", "explanation": "这里应该用〈肚子〉。“饿”的主语须是人或身体部位，“浪潮”不能感到饿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52471281-3756-4e87-a66a-c94079c46cb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20586, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "海边的一只浪潮涌来，很有气势。", "corrected_sentence": "海边的一阵浪潮涌来，很有气势。", "error_description": "量词错误：“浪潮”不能用“只”，“只”多用于动物或成对物件中的一个。这里应改为“阵”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52471281-3756-4e87-a66a-c94079c46cb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20586, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一只浪潮打来，小船晃了一下。", "corrected_sentence": "一阵浪潮打来，小船晃了一下。", "error_description": "量词错误：“浪潮”不能用“只”，“只”多用于动物或成对物件中的一个。应用“阵”或“波”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52471281-3756-4e87-a66a-c94079c46cb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
