INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20588, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让一件事开始发生。", "primary_collocate": null, "pronunciation": "yǐn fā", "ipa": "in˨˩˦ fa˥", "syllable_count": 2, "sentences": [{"text": "这个消息引发了大家的讨论。", "target_word": "引发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一根烟头引发了一场大火。", "target_word": "引发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话引发了很多人的不满。", "target_word": "引发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影引发了社会的关注。", "target_word": "引发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小小的误会引发了他们的矛盾。", "target_word": "引发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨太大，引发了山洪。", "target_word": "引发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机太累，引发了这次事故。", "target_word": "引发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃太多冰激凌可能引发胃病。", "target_word": "引发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的笑话引发了全班的笑声。", "target_word": "引发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事引发过很多争论。", "target_word": "引发", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "引发了", "label": "体标"}, {"form": "引发过", "label": "体标"}], "register": "中性", "sense_fingerprint": "使某件事开始发生，多指讨论、事故、矛盾等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '245aa18a-045a-46cc-b4fa-b7de9581fe19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20588, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "引发", "is_correct": true, "explanation": "正确：引发表示使某件事开始发生。"}, {"text": "银发", "is_correct": false, "explanation": "yínfà（第二、四声）与 yǐnfā（第三、一声）声调不同，意思是白色的头发。"}, {"text": "印发", "is_correct": false, "explanation": "yìnfā（第四声）与 yǐnfā（第三声）第一音节声调不同，意思是印刷后发出。"}, {"text": "应发", "is_correct": false, "explanation": "yīngfā（第一、一声）与 yǐnfā 第一音节声调不同，韵母相近，意思是应当发放。"}], "explanations": {"引发": "正确：引发表示使某件事开始发生。", "银发": "yínfà（第二、四声）与 yǐnfā（第三、一声）声调不同，意思是白色的头发。", "印发": "yìnfā（第四声）与 yǐnfā（第三声）第一音节声调不同，意思是印刷后发出。", "应发": "yīngfā（第一、一声）与 yǐnfā 第一音节声调不同，韵母相近，意思是应当发放。"}, "sentence_index": null, "correct_answer": "引发"}, "level_3": {"options": [{"text": "引发", "is_correct": true, "explanation": "正确：「引发」表示使某件事开始发生，「这个消息引发了大家的讨论」符合句意。"}, {"text": "抹杀", "is_correct": false, "explanation": "语义：「抹杀」表示把事物否定掉，与「引起讨论」的意思相反。"}, {"text": "放松", "is_correct": false, "explanation": "搭配：「放松」不能与「讨论」搭配，讨论不能被放松。"}, {"text": "生育", "is_correct": false, "explanation": "语义：「生育」指生孩子，与消息引起讨论无关。"}], "explanations": {"引发": "正确：「引发」表示使某件事开始发生，「这个消息引发了大家的讨论」符合句意。", "抹杀": "语义：「抹杀」表示把事物否定掉，与「引起讨论」的意思相反。", "放松": "搭配：「放松」不能与「讨论」搭配，讨论不能被放松。", "生育": "语义：「生育」指生孩子，与消息引起讨论无关。"}, "sentence_index": 0, "correct_answer": "引发"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师引发学生去参观博物馆。", "explanation": "这里应该用〈带领〉。引发表示引起某件事或矛盾，不能用来带领人去做事。"}, {"text": "他用手轻轻引发了门，走了进去。", "explanation": "这里应该用〈推开〉或〈打开〉。〈引发〉表示引起某件事或矛盾，不能用于开门这样的具体动作。"}, {"text": "她引发了一块蛋糕，大家都吃了。", "explanation": "这里应该用〈切〉。〈引发〉只用于引起事件或矛盾，不能用于「一块蛋糕」这样的具体物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e68fea7-3f48-4414-8e82-b156083ca382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20588, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "引发", "is_correct": true, "explanation": "正确：「司机太累，引发了这次事故」表示司机太累导致了事故，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：「吃」不能表示引起事故，句子不成立。"}, {"text": "庆祝", "is_correct": false, "explanation": "语义：「庆祝」是为喜事举行活动，不能用于事故。"}, {"text": "抄袭", "is_correct": false, "explanation": "搭配：「抄袭」指照搬别人的作品，不能与「事故」搭配。"}], "explanations": {"引发": "正确：「司机太累，引发了这次事故」表示司机太累导致了事故，符合句意。", "吃": "语义：「吃」不能表示引起事故，句子不成立。", "庆祝": "语义：「庆祝」是为喜事举行活动，不能用于事故。", "抄袭": "搭配：「抄袭」指照搬别人的作品，不能与「事故」搭配。"}, "sentence_index": 6, "correct_answer": "引发"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师引发学生读书，很有效。", "explanation": "这里应该用〈引导〉。引发表示引起某件事或矛盾，不能用来表示老师带领学生读书。"}, {"text": "我引发了一杯水。", "explanation": "这里应该用〈倒〉。〈引发〉只用于引起事件或矛盾，不能用于「一杯水」这样的具体物品。"}, {"text": "他引发了一棵树。", "explanation": "这里应该用〈种〉。〈引发〉只用于引起事件或矛盾，树是具体物体，不能说被引发。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e68fea7-3f48-4414-8e82-b156083ca382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20588, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次暴雨引发得了一场山体滑坡。", "corrected_sentence": "这次暴雨引发了一场山体滑坡。", "error_description": "补语错误：「引发」后面不能加可能补语「得」，应写作「引发了」。「……得了」表示能否应付或承受，这里说的是引起事件，不能用「得」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e68fea7-3f48-4414-8e82-b156083ca382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20588, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这场大雨被引发了洪水。", "corrected_sentence": "这场大雨引发了洪水。", "error_description": "被字句错误：「引发」的主语「大雨」是引起事情的一方，不能用「被」。应去掉「被」，写作「这场大雨引发了洪水」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e68fea7-3f48-4414-8e82-b156083ca382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20590, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20590, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20590, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示事情是真的，不是假的。", "primary_collocate": null, "pronunciation": "zhēn zhèng", "ipa": "ʈʂən⁵⁵ ʈʂəŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "你真正了解他吗？", "target_word": "真正", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我到中国以后，才真正开始学汉语。", "target_word": "真正", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他真正喜欢的是画画。", "target_word": "真正", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这件事真正做起来很难。", "target_word": "真正", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "只有朋友才会真正帮你。", "target_word": "真正", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她第一次真正感到快乐。", "target_word": "真正", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子长大了，真正懂事了。", "target_word": "真正", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你真正需要的是休息。", "target_word": "真正", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们要真正解决这个问题。", "target_word": "真正", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "见到他以后，我才真正放心。", "target_word": "真正", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词：确实、名副其实地（做某事或处于某种状态）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '083b86a6-9f7b-4d1f-ab6f-174ff48943e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20590, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "真正", "is_correct": true, "explanation": "真正：表示确实如此，符合“你确实了解他吗”的意思。"}, {"text": "故意", "is_correct": false, "explanation": "语义：故意表示有意去做，不能表示了解的程度。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：偶尔指次数少，与“深入了解他”的含义不符。"}, {"text": "赶紧", "is_correct": false, "explanation": "语义：赶紧表示急忙，不能修饰“了解”。"}], "explanations": {"真正": "真正：表示确实如此，符合“你确实了解他吗”的意思。", "故意": "语义：故意表示有意去做，不能表示了解的程度。", "偶尔": "语义：偶尔指次数少，与“深入了解他”的含义不符。", "赶紧": "语义：赶紧表示急忙，不能修饰“了解”。"}, "sentence_index": 0, "correct_answer": "真正"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他真正的很高兴，我们都替他开心。", "explanation": "这里应该用〈很〉。“真正的”是修饰名词的结构，不能直接修饰形容词“高兴”，应说“很高兴”。"}, {"text": "他真正的一个人走了。", "explanation": "这里应该用〈独自〉。“真正”强调事情是真的，不能修饰“一个人走了”这样的动作方式。"}, {"text": "我们真正的回家吧。", "explanation": "这里应该用〈快点〉。“真正”表示事情是真的，不能加“的”修饰动词“回家”，这里应该说“快点回家吧”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20590, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "真正", "is_correct": true, "explanation": "真正：表示确实懂事，符合“长大了”的变化。"}, {"text": "恰好", "is_correct": false, "explanation": "语义：恰好表示正好碰上，与“懂事”的变化不搭。"}, {"text": "匆忙", "is_correct": false, "explanation": "搭配：匆忙形容动作急，不能修饰“懂事”。"}, {"text": "白白", "is_correct": false, "explanation": "语义：白白表示没有收获，与“懂事”的正面意思矛盾。"}], "explanations": {"真正": "真正：表示确实懂事，符合“长大了”的变化。", "恰好": "语义：恰好表示正好碰上，与“懂事”的变化不搭。", "匆忙": "搭配：匆忙形容动作急，不能修饰“懂事”。", "白白": "语义：白白表示没有收获，与“懂事”的正面意思矛盾。"}, "sentence_index": 6, "correct_answer": "真正"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈真正的在做饭，别打扰她。", "explanation": "这里应该用〈正在〉。“真正的”后面不能直接接“在”，应说“正在做饭”。"}, {"text": "这个问题真正的难，我们明天再讨论。", "explanation": "这里应该用〈很〉。“真正”强调事情是真的，不能用“真正的”修饰“难”，这里应该说“很难”。"}, {"text": "这个菜真正的辣，我们吃不了。", "explanation": "这里应该用〈太〉。“真正的”修饰名词，不能直接修饰形容词“辣”，应说“太辣”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20590, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们没有真正解决了这个问题。", "corrected_sentence": "我们没有真正解决这个问题。", "error_description": "错误：“没有真正解决了”；正确：“没有真正解决”。用“没有”否定的动作后面不能再加“了”，应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20590, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我真正喜欢这个真正城市。", "corrected_sentence": "我真正喜欢这个城市。", "error_description": "错误：“真正”多出一处。“真正”是副词，不能直接修饰名词“城市”，此处应删去。正确：“我真正喜欢这个城市。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20592, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a5472ea-8c64-46cc-bd4c-f3abe5b7c9f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
