INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20592, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "被别人管着，不能自己做主。", "primary_collocate": null, "pronunciation": "shòu zhì yú", "ipa": "ʂoʊ̯˥˩ ʈʂɻ̩˥˩ y˧˥", "syllable_count": 3, "sentences": [{"text": "他从小受制于父母，什么都不能自己选。", "target_word": "受制于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她刚结婚时，处处受制于婆婆。", "target_word": "受制于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个孩子受制于哥哥，不敢说话。", "target_word": "受制于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司受制于老板一个人，没人敢提意见。", "target_word": "受制于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不想一辈子受制于别人。", "target_word": "受制于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小国常常受制于大国。", "target_word": "受制于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他欠了很多钱，只好受制于债主。", "target_word": "受制于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "员工受制于经理，不能自己决定。", "target_word": "受制于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在家里，他总是受制于妻子。", "target_word": "受制于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她不愿受制于人，所以自己开了店。", "target_word": "受制于", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "受制于", "label": "基本形式"}, {"form": "受制於", "label": "繁体"}], "register": "书面", "sense_fingerprint": "人被另一个人或势力管着，失去自主权", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b7ca80-ae1c-4e7c-a5ec-daf599d2e99f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20592, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "独立于", "is_correct": false, "explanation": "语义：“独立于”表示不受约束、自己做主，与“什么都不能自己选”矛盾。"}, {"text": "受制于", "is_correct": true, "explanation": "正确：“他从小受制于父母，什么都不能自己选”表示被父母管着，不能自主，与语境一致。"}, {"text": "自立于", "is_correct": false, "explanation": "语义：“自立于”指能够自己站立、自主做事，与“不能自己选”的语境相反。"}, {"text": "有别于", "is_correct": false, "explanation": "语义：“有别于”表示与……不同，不表示被管着，与“什么都不能自己选”联系不上。"}], "explanations": {"独立于": "语义：“独立于”表示不受约束、自己做主，与“什么都不能自己选”矛盾。", "受制于": "正确：“他从小受制于父母，什么都不能自己选”表示被父母管着，不能自主，与语境一致。", "自立于": "语义：“自立于”指能够自己站立、自主做事，与“不能自己选”的语境相反。", "有别于": "语义：“有别于”表示与……不同，不表示被管着，与“什么都不能自己选”联系不上。"}, "sentence_index": 0, "correct_answer": "受制于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他受制于老师的一句话，决定改行。", "explanation": "这里应该用〈受启发〉。受制于表示被约束，含消极意思；老师的一句话带来的是启发，应说〈受启发〉。"}, {"text": "这家公司受制于老板的帮助，业绩越来越好。", "explanation": "〈受制于〉含被管束、不能自主的消极意思，不能用于“帮助”这类正面关系。"}, {"text": "这孩子受制于一只小猫，每天都在院子里玩耍。", "explanation": "这里应该用〈陪伴〉。受制于要求控制者能管束人，小猫不能管束孩子；这里描述的是陪伴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a5472ea-8c64-46cc-bd4c-f3abe5b7c9f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20592, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "受宠于", "is_correct": false, "explanation": "语义：“受宠”指得到宠爱，与“欠了很多钱，只好……”的窘迫语境不符。"}, {"text": "受制于", "is_correct": true, "explanation": "正确：“欠了很多钱，只好受制于债主”表示被债主管着、无法自主，与语境一致。"}, {"text": "受邀于", "is_correct": false, "explanation": "搭配：“受邀”指接受邀请，不能用于欠债者与债主之间的关系。"}, {"text": "受赏于", "is_correct": false, "explanation": "语义：“受赏”指得到奖赏，与“欠钱”的语境相反。"}], "explanations": {"受宠于": "语义：“受宠”指得到宠爱，与“欠了很多钱，只好……”的窘迫语境不符。", "受制于": "正确：“欠了很多钱，只好受制于债主”表示被债主管着、无法自主，与语境一致。", "受邀于": "搭配：“受邀”指接受邀请，不能用于欠债者与债主之间的关系。", "受赏于": "语义：“受赏”指得到奖赏，与“欠钱”的语境相反。"}, "sentence_index": 6, "correct_answer": "受制于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她受制于朋友的祝福，很激动地哭了起来。", "explanation": "这里应该用〈得到〉。受制于表示被约束，含消极意思；朋友的祝福带来的是支持，应说〈得到〉。"}, {"text": "她受制于朋友的赞美，所以更加努力。", "explanation": "这里应该用〈受鼓舞〉。受制于表示被约束，含消极意思；朋友的赞美带来的是激励，应说〈受鼓舞〉。"}, {"text": "她受制于一份录取通知，立刻去了学校。", "explanation": "这里应该用〈接到〉。受制于表示被约束，含消极意思；录取通知是喜讯，应说〈接到〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a5472ea-8c64-46cc-bd4c-f3abe5b7c9f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20592, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她从小受制于了家里的安排，很少有自己的时间。", "corrected_sentence": "她从小受制于家里的安排，很少有自己的时间。", "error_description": "错误在于在“于”后面多加了“了”。“受制于”是一个固定结构，“于”后面直接接宾语，不能插入“了”；正确说法是“受制于家里的安排”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a5472ea-8c64-46cc-bd4c-f3abe5b7c9f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20592, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她从来不愿被受制于人，独自创业。", "corrected_sentence": "她从来不愿受制于人，独自创业。", "error_description": "错误在于在“受制于”前面多加了“被”。“受制于”本身已表示被动，前面不能再加“被”；正确说法是“不愿受制于人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a5472ea-8c64-46cc-bd4c-f3abe5b7c9f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
