INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20596, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "有一定范围的一片地方，比如北方、南方或者你住的那一带。", "primary_collocate": null, "pronunciation": "dì qū", "ipa": "ti˥˩ tɕʰy˥", "syllable_count": 2, "sentences": [{"text": "北方地区冬天很冷，常常下雪。", "target_word": "地区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地区的夏天又热又长。", "target_word": "地区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们地区最近下了很大的雨。", "target_word": "地区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "南方地区的人喜欢吃米饭。", "target_word": "地区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地区有很多漂亮的公园。", "target_word": "地区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同地区的人说话不太一样。", "target_word": "地区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去过很多地区，见了不同的人。", "target_word": "地区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地区的交通很方便，坐地铁就到。", "target_word": "地区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠地区很少下雨，水也很少。", "target_word": "地区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你住在哪个地区？", "target_word": "地区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "地區", "label": "繁体"}], "register": "中性", "sense_fingerprint": "有一定范围的地方、区域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '083b86a6-9f7b-4d1f-ab6f-174ff48943e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20596, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地区", "is_correct": true, "explanation": "正确。“北方地区”指一定范围的地域，可以作为“冬天很冷”的主语。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果是食物，不是地域，“北方水果”不成立。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：“北方”修饰地域，“眼睛”不能与之搭配。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是书籍，不是地域，无法“冬天很冷，常常下雪”。"}], "explanations": {"地区": "正确。“北方地区”指一定范围的地域，可以作为“冬天很冷”的主语。", "水果": "语义：水果是食物，不是地域，“北方水果”不成立。", "眼睛": "搭配：“北方”修饰地域，“眼睛”不能与之搭配。", "课本": "语义：课本是书籍，不是地域，无法“冬天很冷，常常下雪”。"}, "sentence_index": 0, "correct_answer": "地区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我住在一根地区，附近的邻居都很友好。", "explanation": "这里应该用〈个〉。根是细长物的量词，地区指一定范围的地方，不能用“根”来数。"}, {"text": "我们约好在一个地区见面，就在车站门口。", "explanation": "这里应该用〈地点〉。地区范围很大，不能用来指车站门口这样的具体位置。"}, {"text": "他是一个很有名的地区，大家都认识他。", "explanation": "这里应该用〈名人〉。地区指地方范围，不能用来指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20596, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地区", "is_correct": true, "explanation": "正确。“去过很多地区”指去过很多一定范围的地域，与“见了不同的人”相符。"}, {"text": "歌曲", "is_correct": false, "explanation": "配价：“去过”要求处所作宾语，“歌曲”不能充当。"}, {"text": "书本", "is_correct": false, "explanation": "语义：书本是纸质读物，不是可以去过的地方。"}, {"text": "电话", "is_correct": false, "explanation": "搭配：“去过”的对象是地方，不与“电话”搭配。"}], "explanations": {"地区": "正确。“去过很多地区”指去过很多一定范围的地域，与“见了不同的人”相符。", "歌曲": "配价：“去过”要求处所作宾语，“歌曲”不能充当。", "书本": "语义：书本是纸质读物，不是可以去过的地方。", "电话": "搭配：“去过”的对象是地方，不与“电话”搭配。"}, "sentence_index": 6, "correct_answer": "地区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个问题的地区很广，涉及很多学科。", "explanation": "这里应该用〈范围〉。地区指地理上的一片区域，抽象问题的涉及面要说范围，不能用“地区”。"}, {"text": "书架的地区里放着一本旧书。", "explanation": "这里应该用〈角落〉。地区指较大的范围，不能用来指书架内部的具体位置。"}, {"text": "这家店的地区很大，客人很多。", "explanation": "这里应该用〈面积〉。地区指地理范围，描述店铺大小应说面积或场地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20596, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我去过三地区，都很有意思。", "corrected_sentence": "我去过三个地区，都很有意思。", "error_description": "错误在量词。数词与“地区”之间应有量词“个”，应为“三个地区”，不能省略。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20596, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几个地区们的气候差别很大。", "corrected_sentence": "这几个地区的气候差别很大。", "error_description": "错误在“们”。“地区”不能加“们”表示复数，且“这几个”已表示数量，应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20598, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拉向", "is_correct": true, "explanation": "反义：“推”与“拉”方向相反，“拉向”表示朝相反方向拉动物体，与“推向”互为反义。"}, {"text": "收藏", "is_correct": false, "explanation": "无反义关系：“收藏”指妥善保存物品，与物体的移动方向无关。"}, {"text": "朗读", "is_correct": false, "explanation": "无反义关系：“朗读”指大声读出文字，与推动物体无关。"}, {"text": "编写", "is_correct": false, "explanation": "无反义关系：“编写”指编辑、撰写，与物理移动无关。"}], "correct_answer": "拉向", "explanations": {"拉向": "反义：“推”与“拉”方向相反，“拉向”表示朝相反方向拉动物体，与“推向”互为反义。", "收藏": "无反义关系：“收藏”指妥善保存物品，与物体的移动方向无关。", "朗读": "无反义关系：“朗读”指大声读出文字，与推动物体无关。", "编写": "无反义关系：“编写”指编辑、撰写，与物理移动无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ef2fe60-f98c-491f-8c0c-773036b68860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20598, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拉向", "is_correct": true, "explanation": "反义：“推”与“拉”方向相反，“拉向”表示朝相反方向拉动物体，与“推向”互为反义。"}, {"text": "保持", "is_correct": false, "explanation": "无反义关系：“保持”指维持原样，与物体的移动方向无关。"}, {"text": "留下", "is_correct": false, "explanation": "无反义关系：“留下”指不离开某处，与“推向”表示的推动义无关。"}, {"text": "挑选", "is_correct": false, "explanation": "无反义关系：“挑选”指选择，与推动物体无关。"}], "correct_answer": "拉向", "explanations": {"拉向": "反义：“推”与“拉”方向相反，“拉向”表示朝相反方向拉动物体，与“推向”互为反义。", "保持": "无反义关系：“保持”指维持原样，与物体的移动方向无关。", "留下": "无反义关系：“留下”指不离开某处，与“推向”表示的推动义无关。", "挑选": "无反义关系：“挑选”指选择，与推动物体无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ef2fe60-f98c-491f-8c0c-773036b68860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20598, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手或工具让东西朝一个方向移动。", "primary_collocate": null, "pronunciation": "tuī xiàng", "ipa": "tʰweɪ˥ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他用力把箱子推向墙边。", "target_word": "推向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子把球推向了门口。", "target_word": "推向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把小车推向超市的出口。", "target_word": "推向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用棍子把石头推向河边。", "target_word": "推向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸把椅子推向桌子。", "target_word": "推向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把盘子推向我，说你先吃。", "target_word": "推向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人慢慢把轮椅推向公园。", "target_word": "推向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把桌子推向窗边，坐下看书。", "target_word": "推向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把杯子推向桌子中间。", "target_word": "推向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟把玩具车推向沙发下面。", "target_word": "推向", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "推向了", "label": "体标"}], "register": "中性", "sense_fingerprint": "用手或工具把具体物体推到某个方向或地点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e884783-3d98-4d71-90bb-6a5b56992bcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20598, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "推向", "is_correct": true, "explanation": "正确：推向，用手或工具让东西朝一个方向移动。"}, {"text": "推想", "is_correct": false, "explanation": "推想与推向只有第二个音节声调不同（xiǎng 与 xiàng），意思是推测、推断，不指移动具体物体。"}, {"text": "推销", "is_correct": false, "explanation": "推销（tuī xiāo）与推向（tuī xiàng）读音相近，第二个音节韵母和声调不同，意思是卖东西，与推动物体无关。"}, {"text": "吹向", "is_correct": false, "explanation": "吹向与推向只有声母不同（ch 与 t），意思是吹动，动作不同。"}], "explanations": {"推向": "正确：推向，用手或工具让东西朝一个方向移动。", "推想": "推想与推向只有第二个音节声调不同（xiǎng 与 xiàng），意思是推测、推断，不指移动具体物体。", "推销": "推销（tuī xiāo）与推向（tuī xiàng）读音相近，第二个音节韵母和声调不同，意思是卖东西，与推动物体无关。", "吹向": "吹向与推向只有声母不同（ch 与 t），意思是吹动，动作不同。"}, "sentence_index": null, "correct_answer": "推向"}, "level_3": {"options": [{"text": "推向", "is_correct": true, "explanation": "正确：“他用力把箱子推向墙边”表示用力使箱子朝墙边移动。"}, {"text": "缩短", "is_correct": false, "explanation": "搭配：“缩短”针对距离或时间，不能与“墙边”这样的处所搭配。"}, {"text": "吞下", "is_correct": false, "explanation": "语义：“吞下”只用于可以吞咽的东西，箱子不能被吞下。"}, {"text": "吐出", "is_correct": false, "explanation": "语义：“吐出”指从口中排出，与用力推箱子的动作不符。"}], "explanations": {"推向": "正确：“他用力把箱子推向墙边”表示用力使箱子朝墙边移动。", "缩短": "搭配：“缩短”针对距离或时间，不能与“墙边”这样的处所搭配。", "吞下": "语义：“吞下”只用于可以吞咽的东西，箱子不能被吞下。", "吐出": "语义：“吐出”指从口中排出，与用力推箱子的动作不符。"}, "sentence_index": 0, "correct_answer": "推向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这阵笑声推向了屋外。", "explanation": "这里应该用〈传向〉。推向需要外力施加在具体物体上，笑声是声音，不能被推动，应说传向。"}, {"text": "小猫慢慢推向了碗。", "explanation": "这里应该用〈靠近〉。推向需要带一个被推的物体，小猫自己走近碗要用靠近。"}, {"text": "气球推向了天空。", "explanation": "这里应该用〈飘向〉。推向需要外力施加在物体上，气球自己飘动要用飘向。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ef2fe60-f98c-491f-8c0c-773036b68860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20598, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "推向", "is_correct": true, "explanation": "正确：“老人慢慢把轮椅推向公园”表示老人用手推着轮椅朝公园的方向移动。"}, {"text": "打碎", "is_correct": false, "explanation": "语义：“打碎”指用力使物体破裂，与“慢慢”和正常推动的动作相矛盾。"}, {"text": "举起", "is_correct": false, "explanation": "配价：“举起”要求直接的受事，不能带“公园”这样的处所作宾语。"}, {"text": "折叠", "is_correct": false, "explanation": "配价：“折叠”针对可以折起的物品，不能表示朝处所的移动。"}], "explanations": {"推向": "正确：“老人慢慢把轮椅推向公园”表示老人用手推着轮椅朝公园的方向移动。", "打碎": "语义：“打碎”指用力使物体破裂，与“慢慢”和正常推动的动作相矛盾。", "举起": "配价：“举起”要求直接的受事，不能带“公园”这样的处所作宾语。", "折叠": "配价：“折叠”针对可以折起的物品，不能表示朝处所的移动。"}, "sentence_index": 6, "correct_answer": "推向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他推向了一阵花香。", "explanation": "这里应该用〈闻到〉。推向的宾语必须是具体物体，花香是气味，不能被推动，只能说闻到。"}, {"text": "鱼儿推向了深水。", "explanation": "这里应该用〈游向〉。推向需要施力的主体，鱼自己游动要用游向。"}, {"text": "他的脚步推向了门口。", "explanation": "这里应该用〈走向〉。推向需要施力的物体，脚步是人行走的动作，不能被推动，应说走向。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ef2fe60-f98c-491f-8c0c-773036b68860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20598, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爷爷用手把椅子推向了了门边。", "corrected_sentence": "爷爷用手把椅子推向了门边。", "error_description": "错误：“推向”后的“了”重复出现。应只保留一个“了”，写作“推向了门边”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ef2fe60-f98c-491f-8c0c-773036b68860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20598, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小华把一只小车推向了车库。", "corrected_sentence": "小华把一辆小车推向了车库。", "error_description": "错误形式是“一只小车”，正确形式是“一辆小车”。小车是有轮的交通工具，量词应用“辆”，“只”不能用于小车。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ef2fe60-f98c-491f-8c0c-773036b68860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
