INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20600, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "变革就是社会、制度或事物发生了根本性的重大改变。", "primary_collocate": null, "pronunciation": "biàn gé", "ipa": "pjɛn˥˩ kɤ˧˥", "syllable_count": 2, "sentences": [{"text": "这个国家正在经历一场大变革。", "target_word": "变革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "技术变革改变了人们的生活。", "target_word": "变革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社会变革需要很长的时间。", "target_word": "变革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们支持教育变革。", "target_word": "变革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次变革让公司有了新的方向。", "target_word": "变革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农村的变革让人们过上了好日子。", "target_word": "变革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每一次变革都会带来新的问题。", "target_word": "变革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司需要一次大的变革。", "target_word": "变革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "变革给这座城市带来了新的机会。", "target_word": "变革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对变革，我们不要害怕。", "target_word": "变革", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "次", "label": "量词"}, {"form": "社会变革", "label": "复合"}], "register": "书面", "sense_fingerprint": "社会、制度或事物发生的重大改变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd392b4f9-49cb-42d5-83fd-145c61c00b83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20600, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "变革", "is_correct": true, "explanation": "正确：「一场大变革」指社会或制度的重大改变，可以说「经历」它。"}, {"text": "游戏", "is_correct": false, "explanation": "语义：「游戏」指娱乐活动，不能用来说国家正在经历一场根本的转折。"}, {"text": "早饭", "is_correct": false, "explanation": "搭配：「一场大」不修饰「早饭」，不能说「经历一场大早饭」。"}, {"text": "演出", "is_correct": false, "explanation": "语义：「演出」指表演给人看，不是制度或社会层面的重大改变。"}], "explanations": {"变革": "正确：「一场大变革」指社会或制度的重大改变，可以说「经历」它。", "游戏": "语义：「游戏」指娱乐活动，不能用来说国家正在经历一场根本的转折。", "早饭": "搭配：「一场大」不修饰「早饭」，不能说「经历一场大早饭」。", "演出": "语义：「演出」指表演给人看，不是制度或社会层面的重大改变。"}, "sentence_index": 0, "correct_answer": "变革"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天气发生了很大的变革。", "explanation": "这里应该用〈变化〉。变革指制度、社会的根本改变，天气的起伏用〈变化〉。"}, {"text": "他的房间发生了很大的变革。", "explanation": "这里应该用〈变化〉。变革指制度、社会的根本改变，房间的摆设变动用〈变化〉。"}, {"text": "物价出现了一点变革。", "explanation": "这里应该用〈变动〉。变革指根本性的重大改变，物价的小幅起伏要用〈变动〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbd57905-2a75-4732-b296-47278eecfe97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20600, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "变革", "is_correct": true, "explanation": "正确：「每一次变革」指每次制度或社会的重大改变，「带来新的问题」合理。"}, {"text": "天气", "is_correct": false, "explanation": "语义：「天气」不是能带来制度性影响的改变，「每一次天气」说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：「每一次」不修饰「颜色」，「颜色带来新的问题」也不通。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：「每一次」多修饰可以计数的事件，「每一次空气」说不通。"}], "explanations": {"变革": "正确：「每一次变革」指每次制度或社会的重大改变，「带来新的问题」合理。", "天气": "语义：「天气」不是能带来制度性影响的改变，「每一次天气」说不通。", "颜色": "搭配：「每一次」不修饰「颜色」，「颜色带来新的问题」也不通。", "空气": "搭配：「每一次」多修饰可以计数的事件，「每一次空气」说不通。"}, "sentence_index": 6, "correct_answer": "变革"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "舞台上的灯光在不断变革。", "explanation": "这里应该用〈变换〉。变革指根本性的重大改变，灯光的不断切换要用〈变换〉。"}, {"text": "股票价格出现了很大的变革。", "explanation": "这里应该用〈波动〉。变革是制度层面的根本改变，股价的起伏用〈波动〉。"}, {"text": "设计图纸做了一些变革。", "explanation": "这里应该用〈改动〉。变革指根本性的重大改变，图纸上的小范围修改要用〈改动〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbd57905-2a75-4732-b296-47278eecfe97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20600, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校正在推进一把深刻的变革。", "corrected_sentence": "学校正在推进一场深刻的变革。", "error_description": "量词错误：「把」用于有柄的器具，「变革」是重大事件，应用「场」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbd57905-2a75-4732-b296-47278eecfe97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20600, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这场的变革影响了整个行业。", "corrected_sentence": "这场变革影响了整个行业。", "error_description": "“的”错误：指示词加量词修饰名词时不加“的”，“这场变革”应直接说，“这场的变革”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbd57905-2a75-4732-b296-47278eecfe97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
