INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20602, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "意思是这件事很重要，会改变以后的事情。", "primary_collocate": null, "pronunciation": "lì shǐ xìng", "ipa": "li˥˩ ʂɻ̩˨˩˦ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这是历史性的一天，大家都记得。", "target_word": "历史性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那次历史性的会议改变了很多事。", "target_word": "历史性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们赢了，这是历史性的胜利。", "target_word": "历史性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "登月是历史性的时刻。", "target_word": "历史性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次发现具有历史性意义，课本里也写了。", "target_word": "历史性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场签字仪式是一件历史性的大事。", "target_word": "历史性", "complexity_tier": "T3", "furigana": "lì shǐ xìng", "sentence_source": "generated"}, {"text": "这历史性的一步，让世界变得不一样。", "target_word": "历史性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们见证了这个历史性的瞬间。", "target_word": "历史性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥通车，是城市历史性的大事。", "target_word": "历史性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个历史性的决定，让很多人生活变好了。", "target_word": "历史性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "歷史性", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "事情很重要，会改变以后", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e884783-3d98-4d71-90bb-6a5b56992bcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20602, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "历史性", "is_correct": true, "explanation": "正确：“这是历史性的一天，大家都记得”表示这一天具有重大意义，值得记住。"}, {"text": "日常性", "is_correct": false, "explanation": "语义：“日常性”指平常、每天都有，与“大家都记得”相矛盾。"}, {"text": "老式", "is_correct": false, "explanation": "搭配：“老式”说事物的样式，不修饰“一天”。"}, {"text": "临时性", "is_correct": false, "explanation": "语义：“临时性”指暂时的，与值得记住的一天不符。"}], "explanations": {"历史性": "正确：“这是历史性的一天，大家都记得”表示这一天具有重大意义，值得记住。", "日常性": "语义：“日常性”指平常、每天都有，与“大家都记得”相矛盾。", "老式": "搭配：“老式”说事物的样式，不修饰“一天”。", "临时性": "语义：“临时性”指暂时的，与值得记住的一天不符。"}, "sentence_index": 0, "correct_answer": "历史性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的午饭很历史性。", "explanation": "这里应该用〈平常〉。历史性指会改变以后事情的重大意义，形容普通的一餐应说平常。"}, {"text": "这张桌子很历史性，买来才两天。", "explanation": "这里应该用〈崭新〉。历史性指会改变以后事情的重要性，买来两天的桌子只是崭新，应说崭新。"}, {"text": "我的铅笔是历史性的，用了一周。", "explanation": "这里应该用〈寻常〉。历史性指重要、影响深远的事，铅笔是寻常的文具，应说寻常。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ef2fe60-f98c-491f-8c0c-773036b68860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20602, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "历史性", "is_correct": true, "explanation": "正确：“这历史性的一步，让世界变得不一样”表示这一步具有重大意义，改变了世界。"}, {"text": "季节性", "is_correct": false, "explanation": "语义：“季节性”指按季节周期出现，与改变世界的一步不符。"}, {"text": "短暂性", "is_correct": false, "explanation": "语义：“短暂性”指持续时间很短，与“让世界变得不一样”的长远影响相矛盾。"}, {"text": "手工性", "is_correct": false, "explanation": "搭配：“手工性”描述制作方式，不能修饰“一步”这样的行动。"}], "explanations": {"历史性": "正确：“这历史性的一步，让世界变得不一样”表示这一步具有重大意义，改变了世界。", "季节性": "语义：“季节性”指按季节周期出现，与改变世界的一步不符。", "短暂性": "语义：“短暂性”指持续时间很短，与“让世界变得不一样”的长远影响相矛盾。", "手工性": "搭配：“手工性”描述制作方式，不能修饰“一步”这样的行动。"}, "sentence_index": 6, "correct_answer": "历史性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次聚会很历史性，大家都吃饱了。", "explanation": "这里应该用〈热闹〉。历史性指会改变以后事情的重大意义，形容聚会的场面应说热闹。"}, {"text": "他的生日蛋糕很历史性。", "explanation": "这里应该用〈精致〉。历史性指重大意义，形容蛋糕应说精致。"}, {"text": "那只小猫在历史性地睡觉。", "explanation": "这里应该用〈安稳〉。历史性修饰行为时表示产生重大影响，形容小猫睡觉应说安稳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ef2fe60-f98c-491f-8c0c-773036b68860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20602, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这一刻是历史性地时刻。", "corrected_sentence": "这一刻是历史性的时刻。", "error_description": "错误：“地”放在了名词“时刻”前。“地”用来修饰动词或形容词，形成状语；修饰名词应用“的”。正确形式是“历史性的时刻”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ef2fe60-f98c-491f-8c0c-773036b68860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20602, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次会议很历史性的。", "corrected_sentence": "这次会议是历史性的。", "error_description": "错误形式是“很历史性的”。“历史性”是只能修饰名词的属性词，不能受程度副词“很”修饰。正确形式是用“是……的”：“这次会议是历史性的。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ef2fe60-f98c-491f-8c0c-773036b68860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
