INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20604, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "没能做到。", "primary_collocate": null, "pronunciation": "wèi néng", "ipa": "wei˥˩ nəŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他因为堵车，未能按时到公司。", "target_word": "未能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛我们未能进入决赛。", "target_word": "未能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她未能说服父母，只好放弃了。", "target_word": "未能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "由于下雨，运动会未能举行。", "target_word": "未能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王未能参加昨天的会议。", "target_word": "未能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我未能找到那本书，真可惜。", "target_word": "未能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他努力了很久，还是未能成功。", "target_word": "未能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为太忙，我未能回家看妈妈。", "target_word": "未能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机晚点，客人未能见到经理。", "target_word": "未能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小张未能通过考试，心情不好。", "target_word": "未能", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "正式", "sense_fingerprint": "放在动词前，表示想做的事没有做到，如未能参加、未能成功", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f562dea-1484-4d6c-8f48-09986f773a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20604, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "未能", "is_correct": true, "explanation": "正确。“未能”表示想做的事没有做到，与“因为堵车”的语境相合。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示事情已完成，与“因为堵车”所说的阻碍相矛盾。"}, {"text": "总是", "is_correct": false, "explanation": "语义：“总是”表示经常，与句中这一次具体的情况不符。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”指一贯如此，与“因为堵车”这一具体情况相矛盾。"}], "explanations": {"未能": "正确。“未能”表示想做的事没有做到，与“因为堵车”的语境相合。", "已经": "语义：“已经”表示事情已完成，与“因为堵车”所说的阻碍相矛盾。", "总是": "语义：“总是”表示经常，与句中这一次具体的情况不符。", "从来": "语义：“从来”指一贯如此，与“因为堵车”这一具体情况相矛盾。"}, "sentence_index": 0, "correct_answer": "未能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天未能吃早饭。", "explanation": "这里应该用〈不〉。“未能”表示想做却没做成，习惯性的事要用“不”。"}, {"text": "他未能很聪明。", "explanation": "这里应该用〈不〉。“未能”表示想做的事没有做成，只能用于动作，不能用来描述人的性格或状态。"}, {"text": "这个问题未能很简单。", "explanation": "这里应该用〈不〉。“未能”表示做某事没有做成，不能用于描述事物的性质。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20604, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "未能", "is_correct": true, "explanation": "正确。“未能”表示努力后没有做成，与“努力了很久”相合。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”指过去有过的经历，而“努力了很久，还是……”后面要说努力的结果，用“曾经”不合。"}, {"text": "太", "is_correct": false, "explanation": "语义：“太”表示程度过分，与“努力了很久，还是……”所表达的没有成功不合。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上，与“努力了很久”的时间过程相矛盾。"}], "explanations": {"未能": "正确。“未能”表示努力后没有做成，与“努力了很久”相合。", "曾经": "语义：“曾经”指过去有过的经历，而“努力了很久，还是……”后面要说努力的结果，用“曾经”不合。", "太": "语义：“太”表示程度过分，与“努力了很久，还是……”所表达的没有成功不合。", "立刻": "语义：“立刻”表示马上，与“努力了很久”的时间过程相矛盾。"}, "sentence_index": 6, "correct_answer": "未能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子未能很舒服。", "explanation": "这里应该用〈不太〉。“未能”表示做某事没能做成，不能用来描述椅子等物品的舒适度。"}, {"text": "今天的天气未能很好。", "explanation": "这里应该用〈不太〉。“未能”后面接的是动作，不能直接修饰“很好”这类形容词。"}, {"text": "小张未能很开心。", "explanation": "这里应该用〈不太〉。“未能”表示努力做某事没做成，不能直接修饰表示心情的形容词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20604, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他因为病了，未能了参加比赛。", "corrected_sentence": "他因为病了，未能参加比赛。", "error_description": "错误：“未能了参加比赛”，正确：“未能参加比赛”。“未能”是副词，后面直接接动词，不能在“未能”和动词中间加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20604, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我试了很多次，仍然不未能打开这扇门。", "corrected_sentence": "我试了很多次，仍然未能打开这扇门。", "error_description": "双重否定错误：“未能”本身已含否定，前面不能再加“不”。正确：“仍然未能打开”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
