INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20614, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把不好的地方改好。", "primary_collocate": null, "pronunciation": "gǎi liáng", "ipa": "kai̯˨˩˦ liɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他想改良这个旧办法。", "target_word": "改良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民改良了田里的土。", "target_word": "改良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师改良了学习的方法。", "target_word": "改良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店改良了面包的做法。", "target_word": "改良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把这台旧机器改良了。", "target_word": "改良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸一直在改良花园里的土。", "target_word": "改良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人改良过这种工具。", "target_word": "改良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种大米是专家改良出来的。", "target_word": "改良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店主打算改良菜单上的菜。", "target_word": "改良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂改良了这种玩具的设计。", "target_word": "改良", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "改良了", "label": "体标（了）"}, {"form": "改良过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "把不好的地方改好（办法、土、做法、设计）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a854fec-be2f-4f93-bb5b-d6f5ac612a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20614, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "改良", "is_correct": true, "explanation": "“改良”指把旧办法改好，与“旧办法”的语境相符。"}, {"text": "创造", "is_correct": false, "explanation": "语义：“创造”指从无到有，而“旧办法”已经存在。"}, {"text": "发明", "is_correct": false, "explanation": "语义：“发明”指首次造出新事物，与“旧”的所指矛盾。"}, {"text": "参观", "is_correct": false, "explanation": "配价：“参观”的宾语是场所或展览，不能支配“办法”作宾语。"}], "explanations": {"改良": "“改良”指把旧办法改好，与“旧办法”的语境相符。", "创造": "语义：“创造”指从无到有，而“旧办法”已经存在。", "发明": "语义：“发明”指首次造出新事物，与“旧”的所指矛盾。", "参观": "配价：“参观”的宾语是场所或展览，不能支配“办法”作宾语。"}, "sentence_index": 0, "correct_answer": "改良"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他改良了作业里的错别字。", "explanation": "这里应该用〈改正〉。“改良”指把事物变得更完善，错别字要用“改正”。"}, {"text": "我的收入改良了不少。", "explanation": "这里应该用〈提高〉。“改良”指改进事物的质量，收入这类数量要用“提高”。"}, {"text": "他的病情改良了很多。", "explanation": "这里应该用〈改善〉。“改良”多用于土壤、工具、做法等事物，病情要用“改善”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9df87813-b294-4532-89f8-b277418e5a0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20614, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "改良", "is_correct": true, "explanation": "“改良过”指曾经改进过这种工具，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指吞咽食物，不能用于“工具”。"}, {"text": "培养", "is_correct": false, "explanation": "搭配：“培养”用于人、植物或能力，不能用于“工具”。"}, {"text": "驯化", "is_correct": false, "explanation": "搭配：“驯化”用于动植物，不能用于“工具”。"}], "explanations": {"改良": "“改良过”指曾经改进过这种工具，符合句意。", "吃": "语义：“吃”指吞咽食物，不能用于“工具”。", "培养": "搭配：“培养”用于人、植物或能力，不能用于“工具”。", "驯化": "搭配：“驯化”用于动植物，不能用于“工具”。"}, "sentence_index": 6, "correct_answer": "改良"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校改良了老师的人数。", "explanation": "这里应该用〈增加〉。“改良”指改进事物的质量，人数这类数量要用“增加”。"}, {"text": "双方终于改良了矛盾。", "explanation": "这里应该用〈消除〉。“改良”是使事物更完善，矛盾要用“消除”。"}, {"text": "医生改良了病人的病。", "explanation": "这里应该用〈治疗〉。“改良”用于事物的缺点，人的病要用“治疗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9df87813-b294-4532-89f8-b277418e5a0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20614, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台旧收音机已经改良了过。", "corrected_sentence": "这台旧收音机已经改良过了。", "error_description": "错误：体标“过”与“了”的顺序颠倒（改良了过）。正确：“改良过了”，“过”紧跟动词表示经历，“了”置于其后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9df87813-b294-4532-89f8-b277418e5a0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20614, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家工厂把设计改良很实用。", "corrected_sentence": "这家工厂把设计改良得很实用。", "error_description": "错误：补语前缺少“得”（改良很实用）。正确：“改良得很实用”，“得”引出补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9df87813-b294-4532-89f8-b277418e5a0d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
