INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20618, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "指含有油的性质，比如油性皮肤容易出油。", "primary_collocate": null, "pronunciation": "yóu xìng", "ipa": "iou˧˥ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "她是油性皮肤，脸上一到中午就出油。", "target_word": "油性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "油性的皮肤容易长痘痘。", "target_word": "油性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买洗发水以前，先看看你的头发是不是油性。", "target_word": "油性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天天气热，油性皮肤的人要多洗脸。", "target_word": "油性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我弟弟的头发是油性的，每天都要洗。", "target_word": "油性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是油性笔，写在塑料上不容易擦掉。", "target_word": "油性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "油性皮肤适合用不含油的护肤品。", "target_word": "油性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的皮肤油性大，所以不用厚厚的面霜。", "target_word": "油性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这瓶油性漆有点臭，要开窗用。", "target_word": "油性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说油性和水性的墨水不能混在一起。", "target_word": "油性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "油性笔", "label": "复合词"}, {"form": "油性漆", "label": "复合词"}], "register": "中性", "sense_fingerprint": "油性|名词|含有油的性质，如油性皮肤容易出油", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba171e17-0e71-47fc-bc45-dc66a5f33e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20618, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "油性", "is_correct": true, "explanation": "油性 yóu xìng，指含有油的性质，如油性皮肤容易出油。"}, {"text": "有幸", "is_correct": false, "explanation": "yǒu（第三声）与 yóu（第二声）声调不同，有幸意思是幸运。"}, {"text": "游行", "is_correct": false, "explanation": "xíng（第二声）与 xìng（第四声）声调不同，游行意思是结队行进。"}, {"text": "油星", "is_correct": false, "explanation": "xīng（第一声）与 xìng（第四声）声调不同，油星意思是一点一点的油滴。"}], "explanations": {"油性": "油性 yóu xìng，指含有油的性质，如油性皮肤容易出油。", "有幸": "yǒu（第三声）与 yóu（第二声）声调不同，有幸意思是幸运。", "游行": "xíng（第二声）与 xìng（第四声）声调不同，游行意思是结队行进。", "油星": "xīng（第一声）与 xìng（第四声）声调不同，油星意思是一点一点的油滴。"}, "sentence_index": null, "correct_answer": "油性"}, "level_3": {"options": [{"text": "油性", "is_correct": true, "explanation": "油性：描述皮肤的含油性质，与“脸上一到中午就出油”相符。"}, {"text": "干性", "is_correct": false, "explanation": "语义：干性皮肤不容易出油，与“出油”矛盾。"}, {"text": "干燥", "is_correct": false, "explanation": "语义：干燥的皮肤缺少油分，与“出油”矛盾。"}, {"text": "冷冻", "is_correct": false, "explanation": "搭配：冷冻是低温处理，不能用来形容皮肤。"}], "explanations": {"油性": "油性：描述皮肤的含油性质，与“脸上一到中午就出油”相符。", "干性": "语义：干性皮肤不容易出油，与“出油”矛盾。", "干燥": "语义：干燥的皮肤缺少油分，与“出油”矛盾。", "冷冻": "搭配：冷冻是低温处理，不能用来形容皮肤。"}, "sentence_index": 0, "correct_answer": "油性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他说话很油性，大家都不太喜欢。", "explanation": "这里应该用〈圆滑〉。油性只描述物质或皮肤、头发等含油的性质，不形容人的说话和性格。"}, {"text": "这里的空气很油性，早上散步很舒服。", "explanation": "这里应该用〈清新〉。油性指含油的性质，空气不含油，不能这样形容。"}, {"text": "鸟叫声很油性，听起来很清脆。", "explanation": "这里应该用〈悦耳〉。油性不形容声音，好听的鸟鸣要说悦耳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c8f0eb-19a2-4e09-a76b-b723b0105203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20618, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "油性", "is_correct": true, "explanation": "油性：指皮肤含油多，正适合用不含油的护肤品，与句意相符。"}, {"text": "干裂", "is_correct": false, "explanation": "语义：干裂皮肤缺油，需要含油的滋润护肤品，与“不含油”矛盾。"}, {"text": "紧绷", "is_correct": false, "explanation": "语义：紧绷感多来自缺油，应选含油的滋润品，与“不含油”矛盾。"}, {"text": "发酵", "is_correct": false, "explanation": "搭配：发酵是微生物作用的过程，不能用来形容皮肤。"}], "explanations": {"油性": "油性：指皮肤含油多，正适合用不含油的护肤品，与句意相符。", "干裂": "语义：干裂皮肤缺油，需要含油的滋润护肤品，与“不含油”矛盾。", "紧绷": "语义：紧绷感多来自缺油，应选含油的滋润品，与“不含油”矛盾。", "发酵": "搭配：发酵是微生物作用的过程，不能用来形容皮肤。"}, "sentence_index": 6, "correct_answer": "油性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗汤很油性，我喝不下去。", "explanation": "这里应该用〈油腻〉。油性说的是皮肤、头发或物品含油的性质，形容食物油多要用油腻。"}, {"text": "他的嗓子很油性，说话很费力。", "explanation": "这里应该用〈沙哑〉。油性不形容嗓音，嗓子发不出清亮的声音时要说沙哑。"}, {"text": "这条路很油性，下雨时很危险。", "explanation": "这里应该用〈滑〉。油性说的是含油的性质，路面容易让人摔倒要说滑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c8f0eb-19a2-4e09-a76b-b723b0105203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20618, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "油性地皮肤在夏天最容易出油。", "corrected_sentence": "油性的皮肤在夏天最容易出油。", "error_description": "助词错误：修饰名词“皮肤”应用“的”，“地”用于修饰动词，不能用于名词前。应为“油性的皮肤”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c8f0eb-19a2-4e09-a76b-b723b0105203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20618, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种皮肤是油性得，要常常洗脸。", "corrected_sentence": "这种皮肤是油性的，要常常洗脸。", "error_description": "助词错误：“是……的”句中应用“的”，“得”用于动词后引出补语，应为“是油性的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c8f0eb-19a2-4e09-a76b-b723b0105203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20620, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分离", "is_correct": true, "explanation": "正确。“分离”与“结合”意思相反，指把合在一起的事物分开。"}, {"text": "跑步", "is_correct": false, "explanation": "与“结合”没有反义关系，只是一种运动。"}, {"text": "唱歌", "is_correct": false, "explanation": "与“结合”没有反义关系，只是一种活动。"}, {"text": "睡觉", "is_correct": false, "explanation": "与“结合”没有反义关系，只是一种活动。"}], "correct_answer": "分离", "explanations": {"分离": "正确。“分离”与“结合”意思相反，指把合在一起的事物分开。", "跑步": "与“结合”没有反义关系，只是一种运动。", "唱歌": "与“结合”没有反义关系，只是一种活动。", "睡觉": "与“结合”没有反义关系，只是一种活动。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20620, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分离", "is_correct": true, "explanation": "正确。“分离”与“结合”意思相反，指把合在一起的事物分开。"}, {"text": "吃饭", "is_correct": false, "explanation": "与“结合”没有反义关系，只是一种日常活动。"}, {"text": "游泳", "is_correct": false, "explanation": "与“结合”没有反义关系，只是一种运动。"}, {"text": "读书", "is_correct": false, "explanation": "与“结合”没有反义关系，只是一种活动。"}], "correct_answer": "分离", "explanations": {"分离": "正确。“分离”与“结合”意思相反，指把合在一起的事物分开。", "吃饭": "与“结合”没有反义关系，只是一种日常活动。", "游泳": "与“结合”没有反义关系，只是一种运动。", "读书": "与“结合”没有反义关系，只是一种活动。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20620, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把不同的东西放在一起。", "primary_collocate": null, "pronunciation": "jié hé", "ipa": "tɕjɛ˧˥ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "这道菜把中国和日本的做法结合在一起。", "target_word": "结合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习语言要把听和说结合起来。", "target_word": "结合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的画结合了传统和现代的特点。", "target_word": "结合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师常把课文和生活结合起来讲。", "target_word": "结合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店把咖啡和书店结合在一起。", "target_word": "结合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "理论要和练习结合，才能学得好。", "target_word": "结合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座房子结合了中西两种风格。", "target_word": "结合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏把音乐和运动结合得很好。", "target_word": "结合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生建议把吃药和休息结合起来。", "target_word": "结合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的广告常常结合故事来介绍产品。", "target_word": "结合", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "结合了", "label": "完成体"}, {"form": "结合着", "label": "持续体"}, {"form": "结合过", "label": "经历体"}, {"form": "结合体", "label": "复合"}, {"form": "結合", "label": "繁体"}], "register": "正式", "sense_fingerprint": "把不同的事物或方面合在一起，如理论与实践结合、传统与现代结合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f562dea-1484-4d6c-8f48-09986f773a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20620, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "结合", "is_correct": true, "explanation": "正确。“结合”表示把不同的事物合在一起，与“在一起”相合。"}, {"text": "分开", "is_correct": false, "explanation": "语义：“分开”与句中“在一起”的意思相反。"}, {"text": "隔离", "is_correct": false, "explanation": "语义：“隔离”表示使分开，与“在一起”相矛盾。"}, {"text": "烧", "is_correct": false, "explanation": "搭配：“烧”不能与“做法”搭配，不能说“把做法烧在一起”。"}], "explanations": {"结合": "正确。“结合”表示把不同的事物合在一起，与“在一起”相合。", "分开": "语义：“分开”与句中“在一起”的意思相反。", "隔离": "语义：“隔离”表示使分开，与“在一起”相矛盾。", "烧": "搭配：“烧”不能与“做法”搭配，不能说“把做法烧在一起”。"}, "sentence_index": 0, "correct_answer": "结合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班结合了老师，一起完成了作业。", "explanation": "这里应该用〈配合〉。“结合”用于把不同事物合在一起，与人一起合作要用“配合”。"}, {"text": "我把钥匙结合在口袋里。", "explanation": "这里应该用〈放〉。“结合”指把不同的东西组合在一起，不是放置物品。"}, {"text": "他结合了一下午的时间，才把作业写完。", "explanation": "这里应该用〈花〉。“结合”要求事物之间的组合，不能用于时间的消耗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20620, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "结合", "is_correct": true, "explanation": "正确。“结合了”表示把中西两种风格合在一起，与句意相合。"}, {"text": "反对", "is_correct": false, "explanation": "语义：“反对”表示不赞成，与“房子”的主语和“风格”的语境不符。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：房子不会拒绝风格，这一搭配与句意不符。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：“讨论”需要人作主语，“房子”不能讨论风格。"}], "explanations": {"结合": "正确。“结合了”表示把中西两种风格合在一起，与句意相合。", "反对": "语义：“反对”表示不赞成，与“房子”的主语和“风格”的语境不符。", "拒绝": "语义：房子不会拒绝风格，这一搭配与句意不符。", "讨论": "搭配：“讨论”需要人作主语，“房子”不能讨论风格。"}, "sentence_index": 6, "correct_answer": "结合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他结合了一只猫去公园。", "explanation": "这里应该用〈带〉。“结合”指把不同事物组合在一起，带一只动物出门要用“带”。"}, {"text": "妈妈结合了一个故事。", "explanation": "这里应该用〈讲〉。“结合”指组合事物，讲故事要用“讲”。"}, {"text": "他结合一个人在家。", "explanation": "这里应该用〈独自〉。“结合”要求有两个以上的事物相合，表示单独一个人时要用“独自”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20620, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座公园把自然和城市结合了在一起。", "corrected_sentence": "这座公园把自然和城市结合在一起。", "error_description": "错误：“结合了在一起”中“了”插在“结合”和“在一起”之间，不能这样插入。正确：去掉“了”，说“结合在一起”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20620, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新的计划把学习和休息结合下来。", "corrected_sentence": "新的计划把学习和休息结合起来。", "error_description": "补语错误：“结合”表示把不同事物合在一起，后面应接“起来”，不能用“下来”。正确：“结合起来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20622, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "模糊", "is_correct": true, "explanation": "正确答案。“模糊”指不清楚、不准确，与“精确”意思相反。"}, {"text": "漂亮", "is_correct": false, "explanation": "“漂亮”形容外表好看，与“精确”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”与“吵闹”相对，与“精确”没有反义关系。"}, {"text": "快乐", "is_correct": false, "explanation": "“快乐”与“悲伤”相对，与“精确”没有反义关系。"}], "correct_answer": "模糊", "explanations": {"模糊": "正确答案。“模糊”指不清楚、不准确，与“精确”意思相反。", "漂亮": "“漂亮”形容外表好看，与“精确”没有反义关系。", "安静": "“安静”与“吵闹”相对，与“精确”没有反义关系。", "快乐": "“快乐”与“悲伤”相对，与“精确”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20622, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "模糊", "is_correct": true, "explanation": "正确答案。“模糊”指不清楚、不准确，与“精确”意思相反。"}, {"text": "热情", "is_correct": false, "explanation": "“热情”形容待人的态度，与“精确”没有反义关系。"}, {"text": "甜蜜", "is_correct": false, "explanation": "“甜蜜”形容感情或味道，与“精确”没有反义关系。"}, {"text": "勇敢", "is_correct": false, "explanation": "“勇敢”形容人的胆量，与“精确”没有反义关系。"}], "correct_answer": "模糊", "explanations": {"模糊": "正确答案。“模糊”指不清楚、不准确，与“精确”意思相反。", "热情": "“热情”形容待人的态度，与“精确”没有反义关系。", "甜蜜": "“甜蜜”形容感情或味道，与“精确”没有反义关系。", "勇敢": "“勇敢”形容人的胆量，与“精确”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20622, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "准确，没有差错。", "primary_collocate": null, "pronunciation": "jīng què", "ipa": "tɕiŋ˥ tɕʰɥɛ˥˩", "syllable_count": 2, "sentences": [{"text": "这个表很精确，一秒都不差。", "target_word": "精确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器能精确地显示时间。", "target_word": "精确", "complexity_tier": "T3", "furigana": "zhè tái jī qì néng jīng què de xiǎn shì shí jiān", "sentence_source": "generated"}, {"text": "他算的数字非常精确。", "target_word": "精确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张地图画得不够精确，我们走错了路。", "target_word": "精确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生要精确地知道药的重量。", "target_word": "精确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她记录的数据很精确，老师很满意。", "target_word": "精确", "complexity_tier": "T3", "furigana": "tā jì lù de shù jù hěn jīng què, lǎo shī hěn mǎn yì", "sentence_source": "generated"}, {"text": "机器可以把长度量得很精确。", "target_word": "精确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个数字不精确，请再算一次。", "target_word": "精确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用尺子精确地量了桌子的长度。", "target_word": "精确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气预报不一定每次都精确。", "target_word": "精确", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "精确度", "label": "复合"}, {"form": "精确地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "数据、时间、测量等非常准确，没有差错", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4208b8-fa3e-439a-94ca-4737d9934ac5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20622, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "精确", "is_correct": true, "explanation": "正确答案。“精确”指准确、没有差错，与“一秒都不差”相符。"}, {"text": "粗略", "is_correct": false, "explanation": "语义：“一秒都不差”说的是准确，“粗略”与这个线索矛盾。"}, {"text": "马虎", "is_correct": false, "explanation": "搭配：“马虎”多用来形容人做事不认真，不说手表“很马虎”。"}, {"text": "含糊", "is_correct": false, "explanation": "搭配：“含糊”多用于说话、说法不清楚，不说手表“很含糊”。"}], "explanations": {"精确": "正确答案。“精确”指准确、没有差错，与“一秒都不差”相符。", "粗略": "语义：“一秒都不差”说的是准确，“粗略”与这个线索矛盾。", "马虎": "搭配：“马虎”多用来形容人做事不认真，不说手表“很马虎”。", "含糊": "搭配：“含糊”多用于说话、说法不清楚，不说手表“很含糊”。"}, "sentence_index": 0, "correct_answer": "精确"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道菜很精确，我吃了两碗饭。", "explanation": "这里应该用〈好吃〉。精确用于数据和测量，说菜的味道好要用“好吃”。"}, {"text": "今天的天空很精确，一朵云也没有。", "explanation": "这里应该用〈晴朗〉。精确用于数据和测量，天空没有云要用“晴朗”。"}, {"text": "他的笑容很精确。", "explanation": "这里应该用〈灿烂〉。精确用于数据和测量，形容笑容要用“灿烂”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20622, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "精确", "is_correct": true, "explanation": "正确答案。“精确”指准确，可以修饰“量得”的结果。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”说味道，不能用来形容测量的结果。"}, {"text": "懒惰", "is_correct": false, "explanation": "搭配：“懒惰”形容人的习惯，机器不能“量得很懒惰”。"}, {"text": "粗暴", "is_correct": false, "explanation": "搭配：“粗暴”说对待人或事物的态度，不说测量长度“很粗暴”。"}], "explanations": {"精确": "正确答案。“精确”指准确，可以修饰“量得”的结果。", "甜": "语义：“甜”说味道，不能用来形容测量的结果。", "懒惰": "搭配：“懒惰”形容人的习惯，机器不能“量得很懒惰”。", "粗暴": "搭配：“粗暴”说对待人或事物的态度，不说测量长度“很粗暴”。"}, "sentence_index": 6, "correct_answer": "精确"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这班公交车很精确。", "explanation": "这里应该用〈准时〉。精确用于数据和测量，车辆到站的时间要用“准时”。"}, {"text": "这场比赛很精确，观众看得很过瘾。", "explanation": "这里应该用〈精彩〉。精确指准确无误，说比赛好看、让人激动要用“精彩”。"}, {"text": "他的字写得很精确。", "explanation": "这里应该用〈工整〉。精确用于数据和测量，描述字写得整齐要用“工整”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20622, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他精确的测了这个房间的长度。", "corrected_sentence": "他精确地测了这个房间的长度。", "error_description": "词尾错误：“精确”修饰动词“测”时要用“地”，这里写成“的”不对。正确形式是“精确地测”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20622, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个仪器的精确很高。", "corrected_sentence": "这个仪器的精确度很高。", "error_description": "形式错误：“精确”是形容词，不能直接作“很高”的主语。这里应该用名词“精确度”，说“精确度很高”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
