INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20628, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西都变得一样，好比较。", "primary_collocate": null, "pronunciation": "biāo zhǔn huà", "ipa": "pjɑʊ˥ ʈʂun˨˩˦ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "工厂想把产品尺寸标准化。", "target_word": "标准化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的服务需要标准化。", "target_word": "标准化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校把考试标准化了。", "target_word": "标准化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "零件标准化以后，修理更方便。", "target_word": "标准化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们正在把工作流程标准化。", "target_word": "标准化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "标准化生产能让成本变低。", "target_word": "标准化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "课本内容没有标准化，很难比较成绩。", "target_word": "标准化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院想把检查方法标准化。", "target_word": "标准化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快递包装已经标准化了。", "target_word": "标准化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要把饭店的菜单标准化。", "target_word": "标准化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "标准化了", "label": "体标"}, {"form": "标准化过", "label": "体标"}], "register": "书面", "sense_fingerprint": "使事物符合统一的标准", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d78632b-8856-4b08-affc-b5331421b71a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20628, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "标准化", "is_correct": true, "explanation": "正确：“标准化”表示使尺寸符合统一标准，与“产品尺寸”搭配。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」不能带「尺寸」作宾语，不能说“把尺寸吃”。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：「唱」不能用于「尺寸」，不能说“把尺寸唱”。"}, {"text": "睡", "is_correct": false, "explanation": "配价：「睡」是不及物动词，不能用在“把”字句中带宾语。"}], "explanations": {"标准化": "正确：“标准化”表示使尺寸符合统一标准，与“产品尺寸”搭配。", "吃": "搭配：「吃」不能带「尺寸」作宾语，不能说“把尺寸吃”。", "唱": "搭配：「唱」不能用于「尺寸」，不能说“把尺寸唱”。", "睡": "配价：「睡」是不及物动词，不能用在“把”字句中带宾语。"}, "sentence_index": 0, "correct_answer": "标准化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服很脏，要标准化。", "explanation": "这里应该用〈清洗〉。标准化指统一规格，把衣服弄干净要说清洗。"}, {"text": "这本书已经标准化成英文了。", "explanation": "这里应该用〈翻译〉。标准化指统一规格，把外文转成另一种语言要说翻译。"}, {"text": "我的房间很乱，要标准化一下。", "explanation": "这里应该用〈整理〉。标准化指统一规格，收拾房间要说整理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8cc7a2f-ad07-4e4c-87d1-1568aba3801c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20628, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "标准化", "is_correct": true, "explanation": "正确：“没有标准化”指内容没有统一规格，与“课本内容”搭配。"}, {"text": "游泳", "is_correct": false, "explanation": "搭配：「游泳」与「课本内容」不搭，不能说“内容没有游泳”。"}, {"text": "哭", "is_correct": false, "explanation": "语义：「哭」指流泪，与课本内容无关。"}, {"text": "跑", "is_correct": false, "explanation": "语义：「跑」指快速移动，与课本内容无关，不能说“内容没有跑”。"}], "explanations": {"标准化": "正确：“没有标准化”指内容没有统一规格，与“课本内容”搭配。", "游泳": "搭配：「游泳」与「课本内容」不搭，不能说“内容没有游泳”。", "哭": "语义：「哭」指流泪，与课本内容无关。", "跑": "语义：「跑」指快速移动，与课本内容无关，不能说“内容没有跑”。"}, "sentence_index": 6, "correct_answer": "标准化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座桥需要标准化。", "explanation": "这里应该用〈修复〉。标准化指使产品、流程符合统一规格，受损的桥梁要说修复。"}, {"text": "这台电脑出了问题，需要标准化。", "explanation": "这里应该用〈维修〉。标准化指统一规格，出了故障的机器要说维修。"}, {"text": "这件衣服破了，需要标准化。", "explanation": "这里应该用〈缝补〉。标准化指使事物符合统一规格，衣服破了要说缝补。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8cc7a2f-ad07-4e4c-87d1-1568aba3801c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20628, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店的菜单已经标准化了过。", "corrected_sentence": "这家店的菜单已经标准化了。", "error_description": "错误在“标准化”后多加了“过”。“标准化了”表示已经完成，“了”和“过”不能同时用在同一个动词后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8cc7a2f-ad07-4e4c-87d1-1568aba3801c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20628, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些零件都是标准化。", "corrected_sentence": "这些零件都是标准化的。", "error_description": "错误在“是……的”结构漏了结尾的“的”。“是标准化的”用来说明零件的性质，只说“是标准化”句子不完整。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8cc7a2f-ad07-4e4c-87d1-1568aba3801c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
