INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20630, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "冲过原来挡在前面的东西。", "primary_collocate": null, "pronunciation": "tū pò", "ipa": "tʰu˥˥ pʰwo˥˩", "syllable_count": 2, "sentences": [{"text": "他一下子突破了对手的防线。", "target_word": "突破", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他带着球突破了对方的防守。", "target_word": "突破", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵们突破了敌人的包围。", "target_word": "突破", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪水突破了河边的堤坝。", "target_word": "突破", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他带球突破了两名后卫。", "target_word": "突破", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坦克突破了敌人的阵地。", "target_word": "突破", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们突破了封锁，把药送进了山村。", "target_word": "突破", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支队伍突破了第一道防线。", "target_word": "突破", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们突破了包围，回到了营地。", "target_word": "突破", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他突破了人群的阻拦，跑上了台。", "target_word": "突破", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "突破了", "label": "体标"}, {"form": "突破过", "label": "体标"}, {"form": "突破口", "label": "复合"}], "register": "中性", "sense_fingerprint": "冲过挡在前面的防线、封锁或限制", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d56d81d-7b32-4ed2-b81f-faaa77360a2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20630, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "突破", "is_correct": true, "explanation": "「突破」指冲过防线，与「一下子」搭配，符合句意。"}, {"text": "保卫", "is_correct": false, "explanation": "语义：「保卫」是守护自己一方，与「对手的防线」矛盾。"}, {"text": "巩固", "is_correct": false, "explanation": "语义：「巩固」指加强，与「对手的防线」被一下子攻破的意思相反。"}, {"text": "修补", "is_correct": false, "explanation": "搭配：「修补」多用于墙壁、衣物等破损的东西，不用来说防线被一下子修补。"}], "explanations": {"突破": "「突破」指冲过防线，与「一下子」搭配，符合句意。", "保卫": "语义：「保卫」是守护自己一方，与「对手的防线」矛盾。", "巩固": "语义：「巩固」指加强，与「对手的防线」被一下子攻破的意思相反。", "修补": "搭配：「修补」多用于墙壁、衣物等破损的东西，不用来说防线被一下子修补。"}, "sentence_index": 0, "correct_answer": "突破"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场台风突破了沿海的房屋。", "explanation": "这里应该用〈破坏〉。突破指冲过挡在前面的东西，台风毁坏房屋要说破坏。"}, {"text": "这道墙突破了洪水，没让它进城。", "explanation": "这里应该用〈挡住〉。突破是冲过障碍，墙阻挡洪水要说挡住。"}, {"text": "卫兵突破了国王，没有离开一步。", "explanation": "这里应该用〈保护〉。突破用于障碍和防线，守护人要说保护。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b664e9ad-97d3-45f2-b78a-e8211ea03883') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20630, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "突破", "is_correct": true, "explanation": "「突破」指冲过封锁，与后半句把药送进山村的行动相符。"}, {"text": "维持", "is_correct": false, "explanation": "语义：「维持」是保持封锁的存在，与送药进山村的行动相反。"}, {"text": "遵守", "is_correct": false, "explanation": "语义：「遵守」指服从规定，与把药送进山村的行动矛盾。"}, {"text": "加强", "is_correct": false, "explanation": "搭配：「加强」多接力量、措施，与「封锁」连用时，后半句送药的行动无法接续。"}], "explanations": {"突破": "「突破」指冲过封锁，与后半句把药送进山村的行动相符。", "维持": "语义：「维持」是保持封锁的存在，与送药进山村的行动相反。", "遵守": "语义：「遵守」指服从规定，与把药送进山村的行动矛盾。", "加强": "搭配：「加强」多接力量、措施，与「封锁」连用时，后半句送药的行动无法接续。"}, "sentence_index": 6, "correct_answer": "突破"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈突破了哭泣的孩子。", "explanation": "这里应该用〈安慰〉。突破用于障碍，不用于人，安慰哭泣的孩子要说安慰。"}, {"text": "工人突破了断裂的桥面。", "explanation": "这里应该用〈修复〉。突破指冲过挡住的东西，修好断裂的桥面要说修复。"}, {"text": "医生突破了生病的病人。", "explanation": "这里应该用〈治疗〉。突破用于障碍，不用于人，治病要说治疗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b664e9ad-97d3-45f2-b78a-e8211ea03883') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20630, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次他们终于突破那道防线。", "corrected_sentence": "这次他们终于突破了那道防线。", "error_description": "错误：「突破那道防线」漏了「了」；正确：「突破了那道防线」。表示已经完成的动作，「突破」后要加「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b664e9ad-97d3-45f2-b78a-e8211ea03883') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20630, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那道防线，他们突破很快，不到一个小时就到了山顶。", "corrected_sentence": "那道防线，他们突破得很快，不到一个小时就到了山顶。", "error_description": "错误：「突破很快」漏了「得」；正确：「突破得很快」。说明突破的快慢时要用「得」引出补语，宾语前置时也一样。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b664e9ad-97d3-45f2-b78a-e8211ea03883') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
