INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20632, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "照着原来的样子再做一份。", "primary_collocate": null, "pronunciation": "fù zhì", "ipa": "fu˥˩ ʈʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "我想复制这张照片，给妈妈一份。", "target_word": "复制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把这段文字复制下来。", "target_word": "复制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他复制了朋友的音乐，放进手机里。", "target_word": "复制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打印店可以复制各种文件。", "target_word": "复制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她照着原画复制了一幅。", "target_word": "复制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把钥匙丢了，得再复制一把。", "target_word": "复制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手机复制了网页上的地址。", "target_word": "复制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "复制前，先看清楚原件。", "target_word": "复制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机器能复制一模一样的杯子。", "target_word": "复制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他复制过好几份旧文件。", "target_word": "复制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "复制了", "label": "体标"}, {"form": "复制过", "label": "体标"}, {"form": "复制品", "label": "复合"}], "register": "中性", "sense_fingerprint": "复制：照着原样再做一份", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba171e17-0e71-47fc-bc45-dc66a5f33e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20632, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "复制", "is_correct": true, "explanation": "复制（fù zhì）：照着原来的样子再做一份，是本词的读音与意思。"}, {"text": "副职", "is_correct": false, "explanation": "副职（fù zhí）与复制 fù zhì 声调不同（zhí 为第二声，zhì 为第四声），意思是副手的职位。"}, {"text": "扶植", "is_correct": false, "explanation": "扶植（fú zhí）两个音节的声调都与复制不同，意思是扶助培植。"}, {"text": "复试", "is_correct": false, "explanation": "复试（fù shì）与复制 fù zhì 声母不同（sh 与 zh），意思是再次考试或第二轮面试。"}], "explanations": {"复制": "复制（fù zhì）：照着原来的样子再做一份，是本词的读音与意思。", "副职": "副职（fù zhí）与复制 fù zhì 声调不同（zhí 为第二声，zhì 为第四声），意思是副手的职位。", "扶植": "扶植（fú zhí）两个音节的声调都与复制不同，意思是扶助培植。", "复试": "复试（fù shì）与复制 fù zhì 声母不同（sh 与 zh），意思是再次考试或第二轮面试。"}, "sentence_index": null, "correct_answer": "复制"}, "level_3": {"options": [{"text": "复制", "is_correct": true, "explanation": "复制：依原样再做一份，句中是再做一张照片给妈妈。"}, {"text": "删除", "is_correct": false, "explanation": "语义：删除后照片就没有了，无法再给妈妈一份。"}, {"text": "撕毁", "is_correct": false, "explanation": "语义：撕毁的照片不能再给妈妈，与“给妈妈一份”矛盾。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：“咬”不能与“照片”搭配，照片不能咬。"}], "explanations": {"复制": "复制：依原样再做一份，句中是再做一张照片给妈妈。", "删除": "语义：删除后照片就没有了，无法再给妈妈一份。", "撕毁": "语义：撕毁的照片不能再给妈妈，与“给妈妈一份”矛盾。", "咬": "搭配：“咬”不能与“照片”搭配，照片不能咬。"}, "sentence_index": 0, "correct_answer": "复制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子总喜欢复制大人的心情。", "explanation": "这里应该用〈体会〉。心情不是可以依原样仿制的物件或资料，复制不能用于感受。"}, {"text": "他复制了父亲留下的家业。", "explanation": "这里应该用〈继承〉。家业是人的财产，要用“继承”，不能说“复制”。"}, {"text": "他复制了这段路的长度。", "explanation": "这里应该用〈测量〉。复制指照着原样再做一份，路的长度是要量出来的数量，要用“测量”，不能说“复制”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c8f0eb-19a2-4e09-a76b-b723b0105203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20632, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "复制", "is_correct": true, "explanation": "复制（fù zhì）：照着原来的样子再做一份，是本词的读音与意思。"}, {"text": "福祉", "is_correct": false, "explanation": "福祉（fú zhǐ）两个音节的声调都与复制不同，意思是幸福和福利。"}, {"text": "父子", "is_correct": false, "explanation": "父子（fù zǐ）与复制 fù zhì 声母不同（z 与 zh），声调也不同，意思是父亲与儿子。"}, {"text": "副食", "is_correct": false, "explanation": "副食（fù shí）与复制 fù zhì 声母不同（sh 与 zh），第二音节声调也不同，意思是副食品。"}], "explanations": {"复制": "复制（fù zhì）：照着原来的样子再做一份，是本词的读音与意思。", "福祉": "福祉（fú zhǐ）两个音节的声调都与复制不同，意思是幸福和福利。", "父子": "父子（fù zǐ）与复制 fù zhì 声母不同（z 与 zh），声调也不同，意思是父亲与儿子。", "副食": "副食（fù shí）与复制 fù zhì 声母不同（sh 与 zh），第二音节声调也不同，意思是副食品。"}, "sentence_index": null, "correct_answer": "复制"}, "level_3": {"options": [{"text": "复制", "is_correct": true, "explanation": "复制：照着原样再做一份，句中是把网页上的地址再抄下一份。"}, {"text": "播放", "is_correct": false, "explanation": "搭配：“播放”只用于音视频，不能与“地址”搭配。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”只用于歌曲等，不能与“地址”搭配。"}, {"text": "吞", "is_correct": false, "explanation": "语义：吞下去的地址就不在网页上了，与句意矛盾。"}], "explanations": {"复制": "复制：照着原样再做一份，句中是把网页上的地址再抄下一份。", "播放": "搭配：“播放”只用于音视频，不能与“地址”搭配。", "唱": "搭配：“唱”只用于歌曲等，不能与“地址”搭配。", "吞": "语义：吞下去的地址就不在网页上了，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "复制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生复制了病人的体温。", "explanation": "这里应该用〈测量〉。体温是要量出来的数值，不是可以照原样再做一份的东西，不能说“复制”。"}, {"text": "她复制了刚才那份喜悦。", "explanation": "这里应该用〈回味〉。复制指照着原来的样子再做一份，喜悦这类感受只能回味，不能复制。"}, {"text": "演员复制了那位英雄的一生。", "explanation": "这里应该用〈再现〉。一生的经历不是可以仿制的原件，要用“再现”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c8f0eb-19a2-4e09-a76b-b723b0105203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20632, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把这首歌复制在了移动硬盘里。", "corrected_sentence": "我把这首歌复制到了移动硬盘里。", "error_description": "补语错误：复制的去向要用介词“到”，应说“复制到移动硬盘里”，不说“复制在移动硬盘里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c8f0eb-19a2-4e09-a76b-b723b0105203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20632, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把合同复制了到电脑里。", "corrected_sentence": "我把合同复制到了电脑里。", "error_description": "体标位置错误：“了”应放在补语“到”之后，说“复制到了电脑里”，不说“复制了到电脑里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c8f0eb-19a2-4e09-a76b-b723b0105203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20634, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "提高", "is_correct": true, "explanation": "正确：「提高」与「降低」意思相反，指使水平、数量等变高。"}, {"text": "游泳", "is_correct": false, "explanation": "与「降低」没有反义关系，「游泳」指在水里活动。"}, {"text": "观察", "is_correct": false, "explanation": "与「降低」没有反义关系，「观察」指仔细地看。"}, {"text": "制造", "is_correct": false, "explanation": "与「降低」没有反义关系，「制造」指做出东西。"}], "correct_answer": "提高", "explanations": {"提高": "正确：「提高」与「降低」意思相反，指使水平、数量等变高。", "游泳": "与「降低」没有反义关系，「游泳」指在水里活动。", "观察": "与「降低」没有反义关系，「观察」指仔细地看。", "制造": "与「降低」没有反义关系，「制造」指做出东西。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d7bb3b7-e085-46e5-b1a5-a7408cc8f010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20634, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "升高", "is_correct": true, "explanation": "正确：「升高」与「降低」意思相反，指数值、温度等变高。"}, {"text": "写作", "is_correct": false, "explanation": "与「降低」没有反义关系，「写作」指写文章。"}, {"text": "修理", "is_correct": false, "explanation": "与「降低」没有反义关系，「修理」指把坏了的东西弄好。"}, {"text": "旅行", "is_correct": false, "explanation": "与「降低」没有反义关系，「旅行」指到外地去游览。"}], "correct_answer": "升高", "explanations": {"升高": "正确：「升高」与「降低」意思相反，指数值、温度等变高。", "写作": "与「降低」没有反义关系，「写作」指写文章。", "修理": "与「降低」没有反义关系，「修理」指把坏了的东西弄好。", "旅行": "与「降低」没有反义关系，「旅行」指到外地去游览。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d7bb3b7-e085-46e5-b1a5-a7408cc8f010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20634, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西落下去或变得少一些。", "primary_collocate": null, "pronunciation": "jiàng dī", "ipa": "tɕiaŋ˥˩ ti˥", "syllable_count": 2, "sentences": [{"text": "这家店东西太贵，他想降低价格。", "target_word": "降低", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把音乐的声音降低一点。", "target_word": "降低", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上气温会降低到十度。", "target_word": "降低", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店降低了价格，所以买的人多了。", "target_word": "降低", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多运动可以降低生病的风险。", "target_word": "降低", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂想办法降低成本，让产品更便宜。", "target_word": "降低", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开车时要降低速度，不能太快。", "target_word": "降低", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了降低噪音，学校在路边种了很多树。", "target_word": "降低", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师没有降低要求，大家要继续努力。", "target_word": "降低", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说吃药可以降低血压。", "target_word": "降低", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "降低了", "label": "体标"}, {"form": "降低过", "label": "体标"}], "register": "中性", "sense_fingerprint": "使价格、温度、速度、水平等变低或变少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6062633-d150-4b42-8c9e-91408b62d40d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20634, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "提高", "is_correct": false, "explanation": "语义：「提高」指往上升，与「东西太贵」的意思矛盾。"}, {"text": "降低", "is_correct": true, "explanation": "正确：「降低」表示变低，与「东西太贵，他想……价格」呼应。"}, {"text": "增加", "is_correct": false, "explanation": "语义：「增加」指数量变多，与「东西太贵」的意思矛盾。"}, {"text": "印刷", "is_correct": false, "explanation": "搭配：「印刷」不能直接和「价格」搭配，说不通。"}], "explanations": {"提高": "语义：「提高」指往上升，与「东西太贵」的意思矛盾。", "降低": "正确：「降低」表示变低，与「东西太贵，他想……价格」呼应。", "增加": "语义：「增加」指数量变多，与「东西太贵」的意思矛盾。", "印刷": "搭配：「印刷」不能直接和「价格」搭配，说不通。"}, "sentence_index": 0, "correct_answer": "降低"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他降低了运动，身体变好了。", "explanation": "这里应该用〈增加〉。「降低」是变少，与「身体变好了」矛盾；多运动要说〈增加〉。"}, {"text": "这家店降低了顾客。", "explanation": "这里应该用〈减少〉。「降低」用于价格、温度、水平等量，说顾客变少要用〈减少〉。"}, {"text": "冬天到了，树上的叶子都降低了。", "explanation": "这里应该用〈落〉。叶子从树上掉下来要说“落”，“降低”用于价格、温度、速度等变低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d7bb3b7-e085-46e5-b1a5-a7408cc8f010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20634, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "欣赏", "is_correct": false, "explanation": "搭配：「欣赏」一般用于风景、艺术，不能和「速度」搭配。"}, {"text": "加快", "is_correct": false, "explanation": "语义：「加快」是变快，与后面的「不能太快」矛盾。"}, {"text": "降低", "is_correct": true, "explanation": "正确：「降低」表示变慢，与「不能太快」一致。"}, {"text": "保养", "is_correct": false, "explanation": "搭配：「保养」用于机器、皮肤等，不能和「速度」搭配。"}], "explanations": {"欣赏": "搭配：「欣赏」一般用于风景、艺术，不能和「速度」搭配。", "加快": "语义：「加快」是变快，与后面的「不能太快」矛盾。", "降低": "正确：「降低」表示变慢，与「不能太快」一致。", "保养": "搭配：「保养」用于机器、皮肤等，不能和「速度」搭配。"}, "sentence_index": 6, "correct_answer": "降低"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个方法可以降低工作速度，让工作更快完成。", "explanation": "这里应该用〈提高〉。「降低」是变慢，与「让工作更快完成」矛盾；要提高效率应说〈提高〉。"}, {"text": "他太累了，降低在椅子上休息。", "explanation": "这里应该用〈坐〉。人坐到椅子上不能说“降低”，“降低”用于价格、温度、速度等变低。"}, {"text": "他降低了一个笑话，大家都笑了。", "explanation": "这里应该用〈讲〉。讲笑话要用“讲”，“降低”是使数量、程度变低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d7bb3b7-e085-46e5-b1a5-a7408cc8f010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20634, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂很降低了成本，产品更便宜了。", "corrected_sentence": "工厂大大降低了成本，产品更便宜了。", "error_description": "错误：「很降低了成本」；正确：「大大降低了成本」。「很」是程度副词，只修饰形容词，不能修饰动词「降低」；表示程度深的动作要用「大大」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d7bb3b7-e085-46e5-b1a5-a7408cc8f010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20634, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个月的油价降低地很快，司机都很高兴。", "corrected_sentence": "这个月的油价降低得很快，司机都很高兴。", "error_description": "错误：「降低地很快」；正确：「降低得很快」。「得」引出动词后面表示程度的补语，「地」用来修饰动词，这里要用「得」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d7bb3b7-e085-46e5-b1a5-a7408cc8f010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
