INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20636, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb117516-38ff-424b-bae1-ef068271afe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20636, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示变化很大，很多。", "primary_collocate": null, "pronunciation": "dà fú", "ipa": "ta˥˩ fu˧˥", "syllable_count": 2, "sentences": [{"text": "产量大幅上升。", "target_word": "大幅", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今年的雨水大幅增多。", "target_word": "大幅", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他大幅改变了计划。", "target_word": "大幅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工作时间大幅缩短了。", "target_word": "大幅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校大幅减少了作业。", "target_word": "大幅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房租大幅上涨，我只好搬家。", "target_word": "大幅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经过努力，他的体重大幅下降。", "target_word": "大幅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气变冷，冰淇淋的销量大幅下降。", "target_word": "大幅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春节期间，坐火车的人数大幅增加。", "target_word": "大幅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们把开会的次数大幅减少，大家轻松多了。", "target_word": "大幅", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "修饰动词，表示变化幅度很大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a7c30f6-37cc-4573-8a65-fd66c5bc2a97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20636, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "亲手", "is_correct": false, "explanation": "搭配：「亲手」表示用自己的手做事，修饰人的动作，不能修饰产量的上升。"}, {"text": "大幅", "is_correct": true, "explanation": "正确。「大幅上升」说明产量增长的幅度很大。"}, {"text": "紧紧", "is_correct": false, "explanation": "搭配：“紧紧”形容抓住或靠近，不修饰产量的上升。"}, {"text": "大声", "is_correct": false, "explanation": "搭配：“大声”形容声音，不修饰产量的上升。"}], "explanations": {"亲手": "搭配：「亲手」表示用自己的手做事，修饰人的动作，不能修饰产量的上升。", "大幅": "正确。「大幅上升」说明产量增长的幅度很大。", "紧紧": "搭配：“紧紧”形容抓住或靠近，不修饰产量的上升。", "大声": "搭配：“大声”形容声音，不修饰产量的上升。"}, "sentence_index": 0, "correct_answer": "大幅"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他大幅聪明，什么题都会做。", "explanation": "这里应该用〈很〉。「大幅」表示变化很大、很多，形容性质要用「很」。"}, {"text": "他大幅忘了这件事。", "explanation": "这里应该用〈全〉。「大幅」表示变化很大、很多，忘得彻底要用「全」。"}, {"text": "我大幅喜欢这首歌。", "explanation": "这里应该用〈非常〉。「大幅」表示变化很大、很多，表示喜欢的程度深要用「非常」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb117516-38ff-424b-bae1-ef068271afe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20636, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "白白", "is_correct": false, "explanation": "语义：「白白」是徒然、没有效果，与「经过努力」的正面结果相矛盾。"}, {"text": "大幅", "is_correct": true, "explanation": "正确。「大幅下降」说明体重减少的幅度很大，与「经过努力」的结果相符。"}, {"text": "亲自", "is_correct": false, "explanation": "搭配：「亲自」修饰人的动作，不修饰体重的变化。"}, {"text": "轻声", "is_correct": false, "explanation": "搭配：「轻声」形容说话的声音，不修饰体重的下降。"}], "explanations": {"白白": "语义：「白白」是徒然、没有效果，与「经过努力」的正面结果相矛盾。", "大幅": "正确。「大幅下降」说明体重减少的幅度很大，与「经过努力」的结果相符。", "亲自": "搭配：「亲自」修饰人的动作，不修饰体重的变化。", "轻声": "搭配：「轻声」形容说话的声音，不修饰体重的下降。"}, "sentence_index": 6, "correct_answer": "大幅"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师大幅批评了他的作业。", "explanation": "这里应该用〈严厉〉。大幅说的是变化的幅度，批评的力度要用「严厉」。"}, {"text": "他大幅高兴。", "explanation": "这里应该用〈十分〉。「大幅」表示变化很大、很多，高兴的程度深要用「十分」。"}, {"text": "这首歌大幅好听。", "explanation": "这里应该用〈很〉。「大幅」表示变化很大、很多，形容好听的程度要用「很」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb117516-38ff-424b-bae1-ef068271afe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20636, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今年的销量很大幅上升。", "corrected_sentence": "今年的销量大幅上升。", "error_description": "错误：「大幅」是副词，前面不能再加程度副词「很」。正确：去掉「很」，写作「今年的销量大幅上升」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb117516-38ff-424b-bae1-ef068271afe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20636, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校的作业量大幅了。", "corrected_sentence": "学校的作业量大幅减少了。", "error_description": "错误：名词「作业量」后面用「大幅」作谓语，缺少动词。正确：补上动词「减少」，写作「大幅减少了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb117516-38ff-424b-bae1-ef068271afe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
