INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20638, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做东西。", "primary_collocate": null, "pronunciation": "zhì zuò", "ipa": "ʈʂɻ̩˥˩ tsuo˥˩", "syllable_count": 2, "sentences": [{"text": "妈妈在厨房制作蛋糕。", "target_word": "制作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们正在制作一张生日卡片。", "target_word": "制作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影制作了三年。", "target_word": "制作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢自己制作玩具。", "target_word": "制作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们制作简单的纸花。", "target_word": "制作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个视频是谁制作的？", "target_word": "制作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "制作面包需要面粉和水。", "target_word": "制作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用木头制作了一把椅子。", "target_word": "制作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "制作这个模型花了一个星期。", "target_word": "制作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们高兴地制作着圣诞礼物。", "target_word": "制作", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "制作了", "label": "体标"}, {"form": "制作过", "label": "体标"}, {"form": "制作着", "label": "体标"}, {"form": "制作人", "label": "复合"}, {"form": "製作", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动手做出某种东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '842fb074-b13a-42dd-9ece-3ecc7134eb5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20638, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "制作", "is_correct": true, "explanation": "正确。“制作”表示动手做出蛋糕，与“在厨房”的语境相符。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”针对坏了的器物，蛋糕不能被修理。"}, {"text": "参观", "is_correct": false, "explanation": "语义：“参观”的对象是场所或展览，不能用于蛋糕。"}, {"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，不能带宾语“蛋糕”。"}], "explanations": {"制作": "正确。“制作”表示动手做出蛋糕，与“在厨房”的语境相符。", "修理": "搭配：“修理”针对坏了的器物，蛋糕不能被修理。", "参观": "语义：“参观”的对象是场所或展览，不能用于蛋糕。", "散步": "配价：“散步”是不及物动词，不能带宾语“蛋糕”。"}, "sentence_index": 0, "correct_answer": "制作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的粗心制作了很多麻烦。", "explanation": "这里应该用〈制造〉。“制作”指做出具体的物品；“制造麻烦、矛盾”要用“制造”。"}, {"text": "他制作了三个朋友。", "explanation": "这里应该用〈结交〉。“制作”指做出具体的物品，不能用于人；交朋友要用“结交”。"}, {"text": "两国制作了友好关系。", "explanation": "这里应该用〈建立〉。“制作”指做出具体的物品；“友好关系”是抽象的，要用“建立”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db5df177-4ea5-4b7f-9975-32ce13f139fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20638, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "制作", "is_correct": true, "explanation": "正确。“制作”表示做出面包，与“面粉和水”的语境相符。"}, {"text": "品尝", "is_correct": false, "explanation": "语义：品尝是吃的动作，不需要面粉和水，“品尝面包需要面粉和水”不合常理。"}, {"text": "购买", "is_correct": false, "explanation": "语义：购买是买的行为，不需要面粉和水，句子与语境冲突。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是房间、场所等，不能用于面包。"}], "explanations": {"制作": "正确。“制作”表示做出面包，与“面粉和水”的语境相符。", "品尝": "语义：品尝是吃的动作，不需要面粉和水，“品尝面包需要面粉和水”不合常理。", "购买": "语义：购买是买的行为，不需要面粉和水，句子与语境冲突。", "打扫": "搭配：“打扫”的对象是房间、场所等，不能用于面包。"}, "sentence_index": 6, "correct_answer": "制作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他制作了一阵笑声。", "explanation": "语义：这里把“制作”误用于声音，应说〈发出〉。“制作”只用于做出有形的物品。"}, {"text": "她制作了好心情。", "explanation": "语义：这里把“制作”误用于心情，应说〈保持〉。心情是抽象状态，不能“制作”。"}, {"text": "他们制作了美好的时光。", "explanation": "语义：这里把“制作”误用于时光，应说〈度过〉。时光不是可以做出来的物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db5df177-4ea5-4b7f-9975-32ce13f139fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20638, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她制作很精致。", "corrected_sentence": "她制作得很精致。", "error_description": "补语标记错误：“制作”后接程度补语时要用“得”，应说“制作得很精致”，“制作很精致”漏掉了“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db5df177-4ea5-4b7f-9975-32ce13f139fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20638, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前制作了过一个模型。", "corrected_sentence": "我以前制作过一个模型。", "error_description": "体标错误：“制作”后表示经历只用“过”，不能同时加“了”，应说“制作过”，“制作了过”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db5df177-4ea5-4b7f-9975-32ce13f139fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
