INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20641, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "基督教里一本很重要的书，讲上帝和人们的故事。", "primary_collocate": null, "pronunciation": "shèng jīng", "ipa": "ʂɤŋ˥˩ tɕiŋ˥", "syllable_count": 2, "sentences": [{"text": "这是一本圣经。", "target_word": "圣经", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他每周在教堂学圣经。", "target_word": "圣经", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "圣经讲上帝的故事。", "target_word": "圣经", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师给我们讲了圣经里的故事。", "target_word": "圣经", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "圣经是基督教最重要的书。", "target_word": "圣经", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从小就听妈妈讲圣经故事。", "target_word": "圣经", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "图书馆里有中文圣经，也有英文圣经。", "target_word": "圣经", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你读过圣经吗？", "target_word": "圣经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上放着一本圣经。", "target_word": "圣经", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把圣经放在床边，睡前读一段。", "target_word": "圣经", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "本", "label": "量词"}, {"form": "聖經", "label": "繁体"}], "register": "中性", "sense_fingerprint": "基督教中讲上帝与人的重要书籍", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a7c30f6-37cc-4573-8a65-fd66c5bc2a97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20641, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "圣经", "is_correct": true, "explanation": "正确答案。圣经是基督教里的重要经典。"}, {"text": "神经", "is_correct": false, "explanation": "shén 与 shèng 韵母不同（-n 与 -ng），声调也不同，意思是神经，不是圣经。"}, {"text": "政经", "is_correct": false, "explanation": "zhèng 与 shèng 声母不同（zh 与 sh），意思是政治与经济。"}, {"text": "胜景", "is_correct": false, "explanation": "第二音节 jǐng（第三声）与 jīng（第一声）声调不同，意思是美丽的景色。"}, {"text": "盛情", "is_correct": false, "explanation": "第二音节 qíng 与 jīng 声母不同（q 与 j），声调也不同，意思是热情的款待。"}], "explanations": {"圣经": "正确答案。圣经是基督教里的重要经典。", "神经": "shén 与 shèng 韵母不同（-n 与 -ng），声调也不同，意思是神经，不是圣经。", "政经": "zhèng 与 shèng 声母不同（zh 与 sh），意思是政治与经济。", "胜景": "第二音节 jǐng（第三声）与 jīng（第一声）声调不同，意思是美丽的景色。", "盛情": "第二音节 qíng 与 jīng 声母不同（q 与 j），声调也不同，意思是热情的款待。"}, "sentence_index": null, "correct_answer": "圣经"}, "level_3": {"options": [{"text": "圣经", "is_correct": true, "explanation": "正确答案。圣经是一本书，“一本”配书，句意通顺。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：“一本”只配书籍类，电脑应说“一台”。"}, {"text": "苹果", "is_correct": false, "explanation": "语义：苹果是水果，不是书，不能说“这是一本苹果”。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“一本”不能与汽车搭配，汽车应说“一辆”。"}], "explanations": {"圣经": "正确答案。圣经是一本书，“一本”配书，句意通顺。", "电脑": "搭配：“一本”只配书籍类，电脑应说“一台”。", "苹果": "语义：苹果是水果，不是书，不能说“这是一本苹果”。", "汽车": "搭配：“一本”不能与汽车搭配，汽车应说“一辆”。"}, "sentence_index": 0, "correct_answer": "圣经"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "奶奶每天晚上在圣经里找明天要做的菜谱。", "explanation": "这里应该用〈菜谱〉。圣经指基督教经典，不能用来找做菜的菜谱。"}, {"text": "皇帝写了一封圣经，寄给远方的大臣。", "explanation": "这里应该用〈圣旨〉。圣经指宗教经典，不能指皇帝写给大臣的命令，那要说圣旨。"}, {"text": "他写作文时总翻圣经，查找要用的生词。", "explanation": "这里应该用〈字典〉。圣经是宗教经典，查生词要用字典。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb117516-38ff-424b-bae1-ef068271afe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20641, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "圣经", "is_correct": true, "explanation": "正确答案。圣经是基督教里的重要书籍。"}, {"text": "盛行", "is_correct": false, "explanation": "第二音节 xíng（第二声）与 jīng（第一声）声母与声调都不同，意思是流行，不是圣经。"}, {"text": "肾经", "is_correct": false, "explanation": "shèn 与 shèng 声调相同，只差韵母（-n 与 -ng），意思是中医所说的肾经络。"}, {"text": "胜境", "is_correct": false, "explanation": "第二音节 jìng（第四声）与 jīng（第一声）声调不同，意思是优美的地方。"}], "explanations": {"圣经": "正确答案。圣经是基督教里的重要书籍。", "盛行": "第二音节 xíng（第二声）与 jīng（第一声）声母与声调都不同，意思是流行，不是圣经。", "肾经": "shèn 与 shèng 声调相同，只差韵母（-n 与 -ng），意思是中医所说的肾经络。", "胜境": "第二音节 jìng（第四声）与 jīng（第一声）声调不同，意思是优美的地方。"}, "sentence_index": null, "correct_answer": "圣经"}, "level_3": {"options": [{"text": "圣经", "is_correct": true, "explanation": "正确答案。“中文圣经”与“英文圣经”构成平行结构，句意通顺。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不是书，图书馆里不会有“中文椅子”。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“中文”只修饰语言或文本，不能修饰冰箱。"}, {"text": "西瓜", "is_correct": false, "explanation": "语义：西瓜是水果，不是可以用“中文”限定的书籍。"}], "explanations": {"圣经": "正确答案。“中文圣经”与“英文圣经”构成平行结构，句意通顺。", "椅子": "语义：椅子不是书，图书馆里不会有“中文椅子”。", "冰箱": "搭配：“中文”只修饰语言或文本，不能修饰冰箱。", "西瓜": "语义：西瓜是水果，不是可以用“中文”限定的书籍。"}, "sentence_index": 6, "correct_answer": "圣经"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天早上翻开圣经，看看今天是几号。", "explanation": "这里应该用〈日历〉。圣经是宗教典籍，不是用来查日期的，查日期要用日历。"}, {"text": "礼拜天大家在教堂里一起切圣经。", "explanation": "这里应该用〈蛋糕〉。圣经是书，不能切；教堂里大家分享的是蛋糕。"}, {"text": "她每天在圣经里查明天的天气预报。", "explanation": "这里应该用〈天气预报〉。圣经是宗教典籍，不能用来查天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb117516-38ff-424b-bae1-ef068271afe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20641, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她已经读完了一圣经。", "corrected_sentence": "她已经读完了一本圣经。", "error_description": "错误：「圣经」是书，计量时量词要用「本」，不能直接用「一」加「圣经」。正确：补上量词「本」，写作「她已经读完了一本圣经」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb117516-38ff-424b-bae1-ef068271afe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20641, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班有三本圣经们。", "corrected_sentence": "我们班有三本圣经。", "error_description": "“们”只用于指人的复数，“圣经”是书名，不能加“们”，应说“三本圣经”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb117516-38ff-424b-bae1-ef068271afe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
