INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20644, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "写出来的话或文章。", "primary_collocate": null, "pronunciation": "wén běn", "ipa": "wən˧˥ pən˨˩˦", "syllable_count": 2, "sentences": [{"text": "请把这段文本复制到新文件里。", "target_word": "文本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们先读一遍文本，再回答问题。", "target_word": "文本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份文本的内容太长，我没有看完。", "target_word": "文本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把文本从中文翻译成了英文。", "target_word": "文本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "文本里有一个错别字，请改一下。", "target_word": "文本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请在这里粘贴你的文本。", "target_word": "文本", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个软件可以把语音变成文本。", "target_word": "文本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师把文本发给每个同学，大家先自己读一遍。", "target_word": "文本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把文本发给你，你看看有没有问题。", "target_word": "文本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那篇文本很短，只有三百个字，一分钟就能读完。", "target_word": "文本", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "文本框", "label": "复合"}, {"form": "文本文件", "label": "复合"}], "register": "书面", "sense_fingerprint": "文本：写成文字的话或文章，可以复制、翻译、修改", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dab81e9-4fc4-4e85-8310-7a60964d0d47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20644, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "文本", "is_correct": true, "explanation": "正确：“请把这段文本复制到新文件里”中，“文本”指写成文字的内容。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：花朵是植物，不能复制到文件里。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是实物，不能复制到文件里。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“脚步”不是可以复制的内容，不能说复制脚步。"}], "explanations": {"文本": "正确：“请把这段文本复制到新文件里”中，“文本”指写成文字的内容。", "花朵": "语义：花朵是植物，不能复制到文件里。", "石头": "语义：石头是实物，不能复制到文件里。", "脚步": "搭配：“脚步”不是可以复制的内容，不能说复制脚步。"}, "sentence_index": 0, "correct_answer": "文本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师教我们唱这段文本。", "explanation": "这里应该用〈歌〉。文本是写成的文字内容，不能唱，要唱的是歌曲。"}, {"text": "这个老人每天晚上给孩子吃文本。", "explanation": "这里应该用〈饼干〉。文本是写出来的文字，不能吃；能吃的是饼干等食品。"}, {"text": "他把文本放进了冰箱。", "explanation": "这里应该用〈牛奶〉。文本是写出来的文字，不能放进冰箱保存；需要冷藏的是牛奶等食品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd9359b-cf22-4c0e-aaa5-1714749d82b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20644, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "文本", "is_correct": true, "explanation": "正确：“把语音变成文本”中，“文本”指转写后的文字内容。"}, {"text": "雨", "is_correct": false, "explanation": "语义：语音不能变成雨。"}, {"text": "冰", "is_correct": false, "explanation": "语义：语音不能变成冰。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“变成颜色”不用来描述语音的转化。"}], "explanations": {"文本": "正确：“把语音变成文本”中，“文本”指转写后的文字内容。", "雨": "语义：语音不能变成雨。", "冰": "语义：语音不能变成冰。", "颜色": "搭配：“变成颜色”不用来描述语音的转化。"}, "sentence_index": 6, "correct_answer": "文本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我用手机录了一段文本。", "explanation": "这里应该用〈视频〉。文本是写成的文字，不能用手机录，录下来的是视频或录音。"}, {"text": "他的文本很高，比父亲还高。", "explanation": "这里应该用〈个子〉。文本指写出来的文字，没有高矮；说人的高矮要用个子。"}, {"text": "他的文本拍得很清楚。", "explanation": "这里应该用〈照片〉。文本是文字，不能用拍；拍出来的是照片。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd9359b-cf22-4c0e-aaa5-1714749d82b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20644, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把这把文本打印出来了。", "corrected_sentence": "我把这份文本打印出来了。", "error_description": "错误：“文本”的量词用了“把”，“把”用于有柄的器具，文本应用“份”或“篇”。应为“这份文本”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd9359b-cf22-4c0e-aaa5-1714749d82b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20644, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我读了一只文本。", "corrected_sentence": "我读了一篇文本。", "error_description": "错误：“文本”的量词用了“只”，“只”用于动物等，文本应用“篇”。应为“一篇文本”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd9359b-cf22-4c0e-aaa5-1714749d82b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20646, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "微小", "is_correct": true, "explanation": "正确答案。“微小”与“庞大”在体积、规模上意思相反，是反义词。"}, {"text": "柔软", "is_correct": false, "explanation": "“柔软”形容质地松软，与“庞大”没有反义关系。"}, {"text": "甜美", "is_correct": false, "explanation": "“甜美”形容味道好或声音悦耳，与“庞大”没有反义关系。"}, {"text": "清脆", "is_correct": false, "explanation": "“清脆”形容声音清亮爽快，与“庞大”没有反义关系。"}], "correct_answer": "微小", "explanations": {"微小": "正确答案。“微小”与“庞大”在体积、规模上意思相反，是反义词。", "柔软": "“柔软”形容质地松软，与“庞大”没有反义关系。", "甜美": "“甜美”形容味道好或声音悦耳，与“庞大”没有反义关系。", "清脆": "“清脆”形容声音清亮爽快，与“庞大”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ef2fe60-f98c-491f-8c0c-773036b68860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20646, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "微小", "is_correct": true, "explanation": "正确答案。“微小”与“庞大”在体积、规模上意思相反，是反义词。"}, {"text": "凉爽", "is_correct": false, "explanation": "“凉爽”形容温度适宜、有凉意，与“庞大”没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”形容光线充足或颜色鲜明，与“庞大”没有反义关系。"}, {"text": "迅速", "is_correct": false, "explanation": "“迅速”形容速度快，与“庞大”的体积、规模义无关。"}], "correct_answer": "微小", "explanations": {"微小": "正确答案。“微小”与“庞大”在体积、规模上意思相反，是反义词。", "凉爽": "“凉爽”形容温度适宜、有凉意，与“庞大”没有反义关系。", "明亮": "“明亮”形容光线充足或颜色鲜明，与“庞大”没有反义关系。", "迅速": "“迅速”形容速度快，与“庞大”的体积、规模义无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ef2fe60-f98c-491f-8c0c-773036b68860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20646, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很大很大，比一般的东西都要大。", "primary_collocate": null, "pronunciation": "páng dà", "ipa": "pʰɑŋ˧˥ ta˥˩", "syllable_count": 2, "sentences": [{"text": "河边停着一艘庞大的船。", "target_word": "庞大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山洞里有一块庞大的石头。", "target_word": "庞大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只熊的身体特别庞大。", "target_word": "庞大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机场里有一架庞大的飞机。", "target_word": "庞大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看见一棵庞大的老树。", "target_word": "庞大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "庞大的鲸鱼从海面游过。", "target_word": "庞大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们住在一座庞大的房子里。", "target_word": "庞大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这头牛身体庞大，走得很慢。", "target_word": "庞大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "展览馆里放着一台庞大的机器。", "target_word": "庞大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上出现了一个庞大的影子。", "target_word": "庞大", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "具体事物的样子很大，比一般的东西大得多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e884783-3d98-4d71-90bb-6a5b56992bcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20646, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "庞大", "is_correct": true, "explanation": "正确答案。“河边停着一艘庞大的船”指船的体积很大。"}, {"text": "繁琐", "is_correct": false, "explanation": "搭配：“繁琐”多形容手续、程序，不能说“繁琐的船”。"}, {"text": "温柔", "is_correct": false, "explanation": "语义：“温柔”形容性情或态度，不能用来描述船。"}, {"text": "无形", "is_correct": false, "explanation": "语义：“无形”指看不见、没有形体，与“停着一艘……的船”的具体船只矛盾。"}], "explanations": {"庞大": "正确答案。“河边停着一艘庞大的船”指船的体积很大。", "繁琐": "搭配：“繁琐”多形容手续、程序，不能说“繁琐的船”。", "温柔": "语义：“温柔”形容性情或态度，不能用来描述船。", "无形": "语义：“无形”指看不见、没有形体，与“停着一艘……的船”的具体船只矛盾。"}, "sentence_index": 0, "correct_answer": "庞大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次的考试难度很庞大，我复习了一周。", "explanation": "这里应该用〈大〉。庞大只形容体积、规模或数量，不形容难度；难度高要说“大”。"}, {"text": "他的性格很庞大，大家都喜欢和他做朋友。", "explanation": "这里应该用〈开朗〉。庞大只形容体积、规模或数量，不能形容性格；性格外向要说“开朗”。"}, {"text": "他的胃口很庞大，一顿能吃三碗饭。", "explanation": "这里应该用〈大〉。胃口是食欲，庞大不能形容胃口，胃口大要说“大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ef2fe60-f98c-491f-8c0c-773036b68860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20646, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "庞大", "is_correct": true, "explanation": "正确答案。“他们住在一座庞大的房子里”指房子的规模很大。"}, {"text": "锋利", "is_correct": false, "explanation": "语义：“锋利”形容刀刃等尖锐，不能描述房子。"}, {"text": "勇敢", "is_correct": false, "explanation": "语义：“勇敢”形容人的品性，不能描述房子。"}, {"text": "迅速", "is_correct": false, "explanation": "搭配：“迅速”形容速度，不能说“迅速的房子”。"}], "explanations": {"庞大": "正确答案。“他们住在一座庞大的房子里”指房子的规模很大。", "锋利": "语义：“锋利”形容刀刃等尖锐，不能描述房子。", "勇敢": "语义：“勇敢”形容人的品性，不能描述房子。", "迅速": "搭配：“迅速”形容速度，不能说“迅速的房子”。"}, "sentence_index": 6, "correct_answer": "庞大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的眼神很庞大，让人感到安心。", "explanation": "这里应该用〈温和〉。庞大只形容体积、规模或数量，不能形容眼神；眼神柔和要说“温和”。"}, {"text": "她的微笑很庞大，我很喜欢。", "explanation": "这里应该用〈灿烂〉。庞大不能形容笑容，笑容明亮好看要说“灿烂”。"}, {"text": "他的年纪很庞大，已经八十岁了。", "explanation": "这里应该用〈大〉。庞大不形容年龄，年纪大要说“年纪很大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ef2fe60-f98c-491f-8c0c-773036b68860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20646, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座古城有一颗庞大的城墙。", "corrected_sentence": "这座古城有一道庞大的城墙。", "error_description": "量词错误。城墙是长条形的建筑，应说“一道城墙”；“颗”多用于粒状的小东西，错误的是量词“颗”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ef2fe60-f98c-491f-8c0c-773036b68860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20646, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所大学的图书馆是庞大，学生每天都去。", "corrected_sentence": "这所大学的图书馆很庞大，学生每天都去。", "error_description": "错误：“是庞大”。正确：“很庞大”。形容词作谓语前应用程度副词“很”，不用“是”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ef2fe60-f98c-491f-8c0c-773036b68860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20648, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "司空见惯", "is_correct": true, "explanation": "司空见惯：指常见而不足为奇，与“前所未有”的“从未出现过”正相反。"}, {"text": "精彩绝伦", "is_correct": false, "explanation": "精彩绝伦：形容好到极点，与“前所未有”没有反义关系。"}, {"text": "鸦雀无声", "is_correct": false, "explanation": "鸦雀无声：形容非常安静，与“前所未有”不构成反义关系。"}, {"text": "郁郁寡欢", "is_correct": false, "explanation": "郁郁寡欢：形容心情不好，与“前所未有”不构成反义关系。"}], "correct_answer": "司空见惯", "explanations": {"司空见惯": "司空见惯：指常见而不足为奇，与“前所未有”的“从未出现过”正相反。", "精彩绝伦": "精彩绝伦：形容好到极点，与“前所未有”没有反义关系。", "鸦雀无声": "鸦雀无声：形容非常安静，与“前所未有”不构成反义关系。", "郁郁寡欢": "郁郁寡欢：形容心情不好，与“前所未有”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eacca5e-114b-458c-b73b-212c17bea824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20648, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "司空见惯", "is_correct": true, "explanation": "司空见惯：指常见而不足为奇，与“前所未有”的“从未出现过”正相反。"}, {"text": "声名狼藉", "is_correct": false, "explanation": "声名狼藉：形容名声很坏，与“前所未有”没有反义关系。"}, {"text": "悠然自得", "is_correct": false, "explanation": "悠然自得：形容从容舒适的样子，与“前所未有”不构成反义关系。"}, {"text": "面目全非", "is_correct": false, "explanation": "面目全非：形容改变得认不出原样，与“前所未有”不构成反义关系。"}], "correct_answer": "司空见惯", "explanations": {"司空见惯": "司空见惯：指常见而不足为奇，与“前所未有”的“从未出现过”正相反。", "声名狼藉": "声名狼藉：形容名声很坏，与“前所未有”没有反义关系。", "悠然自得": "悠然自得：形容从容舒适的样子，与“前所未有”不构成反义关系。", "面目全非": "面目全非：形容改变得认不出原样，与“前所未有”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eacca5e-114b-458c-b73b-212c17bea824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20648, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "以前从来没有过。", "primary_collocate": null, "pronunciation": "qián suǒ wèi yǒu", "ipa": "tɕʰjɛn˧˥ swɔ˨˩ wei˥˩ joʊ̯˨˩", "syllable_count": 4, "sentences": [{"text": "今年夏天的雨前所未有地大。", "target_word": "前所未有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市出现了前所未有的变化。", "target_word": "前所未有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到这么多人，他感到前所未有的紧张。", "target_word": "前所未有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛的人数前所未有地多。", "target_word": "前所未有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机让我们的生活前所未有地方便。", "target_word": "前所未有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今天获得了前所未有的成功。", "target_word": "前所未有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场雪大得前所未有，学校都放假了。", "target_word": "前所未有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司今年遇到了前所未有的困难。", "target_word": "前所未有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们对这个游戏有着前所未有的兴趣。", "target_word": "前所未有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年的冬天冷得前所未有。", "target_word": "前所未有", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "前所未有的", "label": "定语形式"}, {"form": "前所未有地", "label": "状语形式"}], "register": "书面", "sense_fingerprint": "形容词：历史上从未出现过的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40c6bb68-9edb-4a24-ad31-cf0cde640a3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20648, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "前所未有", "is_correct": true, "explanation": "前所未有：修饰“大”，表示程度历来没有过，与句意相符。"}, {"text": "微不足道", "is_correct": false, "explanation": "语义：“微不足道”表示极小、不值一提，与描写雨大的句子相矛盾。"}, {"text": "屈指可数", "is_correct": false, "explanation": "搭配：“屈指可数”指数量很少，不能用来形容雨的大小。"}, {"text": "一文不值", "is_correct": false, "explanation": "语义：“一文不值”表示没有价值，与描写雨大的句子不符。"}], "explanations": {"前所未有": "前所未有：修饰“大”，表示程度历来没有过，与句意相符。", "微不足道": "语义：“微不足道”表示极小、不值一提，与描写雨大的句子相矛盾。", "屈指可数": "搭配：“屈指可数”指数量很少，不能用来形容雨的大小。", "一文不值": "语义：“一文不值”表示没有价值，与描写雨大的句子不符。"}, "sentence_index": 0, "correct_answer": "前所未有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天都前所未有地吃早饭。", "explanation": "这里应该用〈经常〉。前所未有指从未出现过，不能表示每天重复的习惯。"}, {"text": "我前所未有地住在北京。", "explanation": "这里应该用〈以前〉。前所未有表示从未出现过，不能用来说自己曾经住过某地。"}, {"text": "他前所未有地见过那个人很多次。", "explanation": "这里应该用〈屡次〉。前所未有表示从未出现过，不能修饰已经多次发生的见面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eacca5e-114b-458c-b73b-212c17bea824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20648, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "前所未有", "is_correct": true, "explanation": "前所未有：作“大得”的补语，表示雪大到历来没有过，与“学校都放假了”的结果相合。"}, {"text": "一目了然", "is_correct": false, "explanation": "搭配：“一目了然”形容情况清楚，不能作“大得”的补语。"}, {"text": "无足轻重", "is_correct": false, "explanation": "语义：“无足轻重”表示不重要，与“学校都放假了”的结果不符。"}, {"text": "默默无闻", "is_correct": false, "explanation": "语义：“默默无闻”表示不为人知，不能用来形容雪的程度。"}], "explanations": {"前所未有": "前所未有：作“大得”的补语，表示雪大到历来没有过，与“学校都放假了”的结果相合。", "一目了然": "搭配：“一目了然”形容情况清楚，不能作“大得”的补语。", "无足轻重": "语义：“无足轻重”表示不重要，与“学校都放假了”的结果不符。", "默默无闻": "语义：“默默无闻”表示不为人知，不能用来形容雪的程度。"}, "sentence_index": 6, "correct_answer": "前所未有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从小前所未有地喜欢画画。", "explanation": "这里应该用〈一直〉。前所未有表示以前从没有过，不能和表示持续的“从小”搭配。"}, {"text": "这种事情我们前所未有地常见。", "explanation": "这里应该用〈很〉。前所未有表示历史上从未出现，不能修饰反复发生的常见事情。"}, {"text": "这件事他前所未有地经历过三次了。", "explanation": "这里应该用〈已经〉。前所未有表示历史上从未出现过，与已经发生三次的事相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eacca5e-114b-458c-b73b-212c17bea824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20648, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次活动吸引了前所未有观众。", "corrected_sentence": "这次活动吸引了前所未有的观众。", "error_description": "“前所未有”修饰名词“观众”时要加“的”。缺少“的”是错误，正确形式是“前所未有的观众”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eacca5e-114b-458c-b73b-212c17bea824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20648, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个游戏前所未有好玩。", "corrected_sentence": "这个游戏前所未有地好玩。", "error_description": "“前所未有”作状语修饰形容词“好玩”时要加“地”。缺少“地”是错误，正确形式是“前所未有地好玩”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eacca5e-114b-458c-b73b-212c17bea824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
