INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20650, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "东西动得有多快，比如车跑得快就是速度大。", "primary_collocate": null, "pronunciation": "sù dù", "ipa": "su˥˩ tu˥˩", "syllable_count": 2, "sentences": [{"text": "小狗的速度比我快多了。", "target_word": "速度", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "汽车在高速路上的速度很快。", "target_word": "速度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "自行车的速度没有汽车快。", "target_word": "速度", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "雨太大了，司机只好把车的速度放慢。", "target_word": "速度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他骑车的速度越来越快。", "target_word": "速度", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "乌龟爬行的速度很慢。", "target_word": "速度", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "火车进站前，速度慢慢降下来了。", "target_word": "速度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你知道飞机飞行的速度是多少吗？", "target_word": "速度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们跑步的速度都不一样。", "target_word": "速度", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师让我们用同样的速度走到前面。", "target_word": "速度", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "平均速度", "label": "复合"}], "register": "中性", "sense_fingerprint": "东西移动的快慢程度，日常说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a7c30f6-37cc-4573-8a65-fd66c5bc2a97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20650, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "速度", "is_correct": true, "explanation": "正确。速度指东西移动的快慢程度，如“小狗的速度比我快多了”。"}, {"text": "速读", "is_correct": false, "explanation": "dú（第二声）与 dù（第四声）只是声调不同，意思是快速阅读，不是东西移动的快慢。"}, {"text": "数度", "is_correct": false, "explanation": "shù 与 sù 声母不同（sh 与 s），意思是多次，与快慢无关。"}, {"text": "四度", "is_correct": false, "explanation": "sì 与 sù 韵母不同（i 与 u），意思是音乐中的音程，不是快慢。"}, {"text": "速录", "is_correct": false, "explanation": "lù 与 dù 声母不同（l 与 d），意思是快速记录文字，不是东西移动的快慢。"}], "explanations": {"速度": "正确。速度指东西移动的快慢程度，如“小狗的速度比我快多了”。", "速读": "dú（第二声）与 dù（第四声）只是声调不同，意思是快速阅读，不是东西移动的快慢。", "数度": "shù 与 sù 声母不同（sh 与 s），意思是多次，与快慢无关。", "四度": "sì 与 sù 韵母不同（i 与 u），意思是音乐中的音程，不是快慢。", "速录": "lù 与 dù 声母不同（l 与 d），意思是快速记录文字，不是东西移动的快慢。"}, "sentence_index": null, "correct_answer": "速度"}, "level_3": {"options": [{"text": "速度", "is_correct": true, "explanation": "正确。“小狗的速度比我快多了”中，速度指跑得快慢，与“快”相配。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重说的是轻重，不能用“快”来比较，句子不成立。"}, {"text": "力气", "is_correct": false, "explanation": "搭配：“快”可以说速度，不能说力气快，这里搭配不当。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄没有快慢，句子说的是跑得快，年龄不能这样比较。"}], "explanations": {"速度": "正确。“小狗的速度比我快多了”中，速度指跑得快慢，与“快”相配。", "体重": "语义：体重说的是轻重，不能用“快”来比较，句子不成立。", "力气": "搭配：“快”可以说速度，不能说力气快，这里搭配不当。", "年龄": "语义：年龄没有快慢，句子说的是跑得快，年龄不能这样比较。"}, "sentence_index": 0, "correct_answer": "速度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这盏台灯的速度很高。", "explanation": "这里应该用〈亮度〉。亮度说光的明暗，台灯的明暗要说亮度；速度说的是移动的快慢，不能用来说灯。"}, {"text": "这杯咖啡的速度很高。", "explanation": "这里应该用〈浓度〉。浓度说饮料或溶液的浓淡，咖啡的浓淡要说浓度，不能说速度。"}, {"text": "这壶水的速度很高。", "explanation": "这里应该用〈温度〉。温度说冷热，水的冷热要说温度，不能说速度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb117516-38ff-424b-bae1-ef068271afe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20650, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "速度", "is_correct": true, "explanation": "正确。“火车进站前，速度慢慢降下来了”，说的是速度降低。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：乘客是人，不能“慢慢降下来”，句子说的是速度降低。"}, {"text": "车票", "is_correct": false, "explanation": "语义：车票是纸片，不能“慢慢降下来”，句子说的是速度的变化。"}, {"text": "车站", "is_correct": false, "explanation": "语义：车站是地点，不能慢慢降下来，句子说的是速度的变化。"}], "explanations": {"速度": "正确。“火车进站前，速度慢慢降下来了”，说的是速度降低。", "乘客": "语义：乘客是人，不能“慢慢降下来”，句子说的是速度降低。", "车票": "语义：车票是纸片，不能“慢慢降下来”，句子说的是速度的变化。", "车站": "语义：车站是地点，不能慢慢降下来，句子说的是速度的变化。"}, "sentence_index": 6, "correct_answer": "速度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试的速度很大。", "explanation": "这里应该用〈难度〉。难度说题目或考试的难易，不能用速度来说难易。"}, {"text": "病情的速度很严重。", "explanation": "这里应该用〈程度〉。程度说病情的轻重，病情的轻重要说程度，速度说的是快慢。"}, {"text": "金子的速度很高。", "explanation": "这里应该用〈纯度〉。纯度说物质的纯净程度，金子的纯净要说纯度，不能说速度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb117516-38ff-424b-bae1-ef068271afe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20650, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "汽车的一只速度慢下来了。", "corrected_sentence": "汽车的速度慢下来了。", "error_description": "错误：“速度”前多加了量词“一只”，“只”多用于动物等，抽象的速度前不加此量词。正确：“汽车的速度慢下来了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb117516-38ff-424b-bae1-ef068271afe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20650, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "火车的速度慢慢降下了来了。", "corrected_sentence": "火车的速度慢慢降下来了。", "error_description": "错误：补语“下来”被“了”隔开，写成“降下了来”，不成词。正确：动词后直接接“下来”，句末再加“了”，说“降下来了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb117516-38ff-424b-bae1-ef068271afe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20652, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ef2fe60-f98c-491f-8c0c-773036b68860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
