INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20652, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "先河指最先开始做某件事的人或事。", "primary_collocate": null, "pronunciation": "xiān hé", "ipa": "ɕjɛn˥ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "他们的发现成了这个领域的先河。", "target_word": "先河", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人种树的做法是村里的先河。", "target_word": "先河", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校办了第一个读书会，开了先河。", "target_word": "先河", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本小说可以说是网络文学的先河。", "target_word": "先河", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店开了送餐上门的先河。", "target_word": "先河", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她第一个上台讲话，为女同学开了先河。", "target_word": "先河", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛为本市开了先河。", "target_word": "先河", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写的歌开了校园音乐的先河。", "target_word": "先河", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥的设计开了先河，后来很多城市都学它。", "target_word": "先河", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司第一次让员工在家工作，开了先河。", "target_word": "先河", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "最先开始做某件事的人或事，可作“成为…先河”的宾语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e884783-3d98-4d71-90bb-6a5b56992bcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20652, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "先河", "is_correct": true, "explanation": "正确答案。xiānhé 指最先开始做某件事的人或事。"}, {"text": "仙鹤", "is_correct": false, "explanation": "hè（第四声）与 hé（第二声）声调不同，“仙鹤”指一种鸟，意思不同。"}, {"text": "显赫", "is_correct": false, "explanation": "声调：xiǎn hè 与 xiān hé 两个音节都只差声调，“显赫”指名声大、地位高。"}, {"text": "先喝", "is_correct": false, "explanation": "hē（第一声）与 hé（第二声）声调不同，“先喝”指先饮用。"}], "explanations": {"先河": "正确答案。xiānhé 指最先开始做某件事的人或事。", "仙鹤": "hè（第四声）与 hé（第二声）声调不同，“仙鹤”指一种鸟，意思不同。", "显赫": "声调：xiǎn hè 与 xiān hé 两个音节都只差声调，“显赫”指名声大、地位高。", "先喝": "hē（第一声）与 hé（第二声）声调不同，“先喝”指先饮用。"}, "sentence_index": null, "correct_answer": "先河"}, "level_3": {"options": [{"text": "先河", "is_correct": true, "explanation": "正确答案。“成了这个领域的先河”指最先开始做的事，符合句意。"}, {"text": "角落", "is_correct": false, "explanation": "语义：“角落”指空间位置，不能作为“发现”的身份。"}, {"text": "尾声", "is_correct": false, "explanation": "语义：“尾声”指结束的部分，与“最先开始”的意思相反。"}, {"text": "余热", "is_correct": false, "explanation": "搭配：“余热”指剩余的热量或退休后的发挥，不能说“成了……的余热”。"}], "explanations": {"先河": "正确答案。“成了这个领域的先河”指最先开始做的事，符合句意。", "角落": "语义：“角落”指空间位置，不能作为“发现”的身份。", "尾声": "语义：“尾声”指结束的部分，与“最先开始”的意思相反。", "余热": "搭配：“余热”指剩余的热量或退休后的发挥，不能说“成了……的余热”。"}, "sentence_index": 0, "correct_answer": "先河"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的书架上摆满了先河。", "explanation": "这里应该用〈书〉。先河指最先开始做的事，不是能摆放的东西，书架上摆的要说“书”。"}, {"text": "他的事业到达了先河。", "explanation": "这里应该用〈顶峰〉。先河指最先开始的做法，不是可以到达的位置；到达的最高点要说“顶峰”。"}, {"text": "这家餐厅的先河很好吃。", "explanation": "这里应该用〈菜〉。先河指最先开始做的事，不是能吃的东西，餐厅做的吃食要说“菜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ef2fe60-f98c-491f-8c0c-773036b68860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20652, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "先河", "is_correct": true, "explanation": "正确答案。“这次比赛为本市开了先河”指首次做了某事，符合句意。"}, {"text": "冷战", "is_correct": false, "explanation": "语义：“冷战”指对立或不和，与比赛的正面语境不合。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "语义：“鸡蛋”是食物，不能作为开启的对象。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“开”后接“脚步”不成立，应说“迈开脚步”。"}], "explanations": {"先河": "正确答案。“这次比赛为本市开了先河”指首次做了某事，符合句意。", "冷战": "语义：“冷战”指对立或不和，与比赛的正面语境不合。", "鸡蛋": "语义：“鸡蛋”是食物，不能作为开启的对象。", "脚步": "搭配：“开”后接“脚步”不成立，应说“迈开脚步”。"}, "sentence_index": 6, "correct_answer": "先河"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把先河放进冰箱里了。", "explanation": "这里应该用〈饮料〉。先河指最先开始的做法，不是能放进冰箱的东西。"}, {"text": "他每天早上都开先河。", "explanation": "这里应该用〈习惯〉。先河只指一次性的首创，不能用于每天重复的动作。"}, {"text": "电视台播放了一档先河。", "explanation": "这里应该用〈节目〉。先河指最先开始的做法，不是可以播放的东西，不能用“档”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ef2fe60-f98c-491f-8c0c-773036b68860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20652, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这项改革为城市管理做了先河。", "corrected_sentence": "这项改革为城市管理开了先河。", "error_description": "搭配错误。与“先河”搭配的动词是“开”，说“开了先河”；“做了先河”搭配不当。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ef2fe60-f98c-491f-8c0c-773036b68860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20652, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家书店率先推出网上预约，打了先河。", "corrected_sentence": "这家书店率先推出网上预约，开了先河。", "error_description": "搭配错误。与“先河”搭配的动词是“开”，说“开了先河”；“打了先河”搭配不当。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ef2fe60-f98c-491f-8c0c-773036b68860') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
