INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20656, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "说清楚规则是什么意思的权力。", "primary_collocate": null, "pronunciation": "jiě shì quán", "ipa": "tɕjɛ˨˩˦ ʂɻ̩˥˩ tɕʰɥɛn˧˥", "syllable_count": 3, "sentences": [{"text": "学校规则的解释权在老师手里。", "target_word": "解释权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次比赛的解释权归组委会。", "target_word": "解释权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁拥有这条规定的解释权？", "target_word": "解释权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商店把最终解释权写在了海报上。", "target_word": "解释权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们要求拥有规则的解释权。", "target_word": "解释权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "规则不清楚时，解释权很重要。", "target_word": "解释权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "优惠券背面写着解释权归商家。", "target_word": "解释权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小区规定的解释权属于业主委员会。", "target_word": "解释权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们为了解释权吵了一个下午。", "target_word": "解释权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游戏规则的解释权不能只属于一个人。", "target_word": "解释权", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "解釋權", "label": "繁体"}], "register": "书面", "sense_fingerprint": "说明规则含义的权力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46d76630-55e4-4191-b05f-0cc4fbf0c071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20656, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "解释权", "is_correct": true, "explanation": "正确：“解释权”指说明规则含义的权力，由老师掌握。"}, {"text": "厚度", "is_correct": false, "explanation": "语义：“厚度”是事物的属性，不是权力，不能“在老师手里”。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“规则”不与“颜色”构成搭配，句子不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”不是可以被掌握的权力，与句义不符。"}], "explanations": {"解释权": "正确：“解释权”指说明规则含义的权力，由老师掌握。", "厚度": "语义：“厚度”是事物的属性，不是权力，不能“在老师手里”。", "颜色": "搭配：“规则”不与“颜色”构成搭配，句子不通。", "年龄": "语义：“年龄”不是可以被掌握的权力，与句义不符。"}, "sentence_index": 0, "correct_answer": "解释权"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他拥有天气的解释权。", "explanation": "这里应该用〈预报〉。“解释权”指对规则作权威说明的权力，天气变化要用“预报”。"}, {"text": "祖父拥有孙子的解释权。", "explanation": "这里应该用〈监护权〉。对未成年人的监督保护属于“监护权”，“解释权”不能这样用。"}, {"text": "他对这件事的解释权很清楚。", "explanation": "这里应该用〈说明〉。“说明”指讲清楚的内容，“解释权”是对规则作权威说明的权力，不能用来形容说明清楚不清楚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f20db2b-ad1d-4235-9415-4a237e6b9018') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20656, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "解释权", "is_correct": true, "explanation": "正确：“解释权”指对优惠券条款作说明的权力，归商家所有。"}, {"text": "重量", "is_correct": false, "explanation": "语义：优惠券背面写的不能是“重量”归属，句子不通。"}, {"text": "面积", "is_correct": false, "explanation": "配价：“归”后接的应是权利主体，“面积”不是权利，不能“归商家”。"}, {"text": "湿度", "is_correct": false, "explanation": "语义：“湿度”与优惠券条款无关，句子不通。"}], "explanations": {"解释权": "正确：“解释权”指对优惠券条款作说明的权力，归商家所有。", "重量": "语义：优惠券背面写的不能是“重量”归属，句子不通。", "面积": "配价：“归”后接的应是权利主体，“面积”不是权利，不能“归商家”。", "湿度": "语义：“湿度”与优惠券条款无关，句子不通。"}, "sentence_index": 6, "correct_answer": "解释权"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这栋楼的解释权归开发商。", "explanation": "这里应该用〈所有权〉。房产归属要说“所有权”，“解释权”指对规则的权威说明。"}, {"text": "这份遗产的解释权归长子。", "explanation": "这里应该用〈继承权〉。遗产的承接属于“继承权”，“解释权”不能用于遗产。"}, {"text": "这间教室的解释权归学生。", "explanation": "这里应该用〈使用权〉。教室的使用安排是“使用权”，“解释权”只指对规则的权威说明。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f20db2b-ad1d-4235-9415-4a237e6b9018') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20656, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把解释权归管理员。", "corrected_sentence": "这项解释权归管理员。", "error_description": "“解释权”是抽象的权力，量词应用“项”，不能说“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f20db2b-ad1d-4235-9415-4a237e6b9018') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20656, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次活动的解释权很归商场。", "corrected_sentence": "这次活动的解释权归商场。", "error_description": "程度副词误用：“很”不能修饰动词“归”，应删去“很”，说“这次活动的解释权归商场。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f20db2b-ad1d-4235-9415-4a237e6b9018') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
