INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20658, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西碎了或者破了。", "primary_collocate": null, "pronunciation": "dǎ pò", "ipa": "ta˨˩˦ pʰwo˥˩", "syllable_count": 2, "sentences": [{"text": "弟弟不小心打破了一个杯子。", "target_word": "打破", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小心点，别把盘子打破了。", "target_word": "打破", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "球飞过来，打破了教室的玻璃。", "target_word": "打破", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把妈妈最爱的碗打破了。", "target_word": "打破", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小猫跳上桌子，打破了花瓶。", "target_word": "打破", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地上都是碎玻璃，是谁打破的？", "target_word": "打破", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我手滑了一下，打破了一个鸡蛋。", "target_word": "打破", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用石头打破了窗户。", "target_word": "打破", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个杯子很结实，不容易打破。", "target_word": "打破", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "打破镜子的人是我的同学。", "target_word": "打破", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "打破了", "label": "体标"}, {"form": "打破过", "label": "体标"}], "register": "中性", "sense_fingerprint": "使杯子、玻璃等具体物品碎裂或破损", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a7c30f6-37cc-4573-8a65-fd66c5bc2a97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20658, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打破", "is_correct": true, "explanation": "正确。“弟弟不小心打破了一个杯子”，打破指使杯子碎裂。"}, {"text": "吃", "is_correct": false, "explanation": "语义：杯子不能被吃，句子说的是杯子破了。"}, {"text": "唱", "is_correct": false, "explanation": "语义：杯子不能被唱，与“不小心”的意外损坏无关。"}, {"text": "骑", "is_correct": false, "explanation": "搭配：“骑”搭配车、马，不能说骑杯子。"}], "explanations": {"打破": "正确。“弟弟不小心打破了一个杯子”，打破指使杯子碎裂。", "吃": "语义：杯子不能被吃，句子说的是杯子破了。", "唱": "语义：杯子不能被唱，与“不小心”的意外损坏无关。", "骑": "搭配：“骑”搭配车、马，不能说骑杯子。"}, "sentence_index": 0, "correct_answer": "打破"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她去食堂打破了两份饭。", "explanation": "这里应该用〈打饭〉。打饭指从食堂把饭盛出来，这是“打”的盛取义，不能用“打破”。"}, {"text": "他不小心打破了一跤。", "explanation": "这里应该用〈摔〉。摔指跌倒或掉下，一跤要说摔，不能说打破。"}, {"text": "事故打破了他的身体。", "explanation": "这里应该用〈伤害〉。伤害指使身体或物品受损，身体受损要说伤害，不能说打破。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb117516-38ff-424b-bae1-ef068271afe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20658, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打破", "is_correct": true, "explanation": "正确。“我手滑了一下，打破了一个鸡蛋”，打破指鸡蛋碎了。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”搭配文字，不能说写鸡蛋。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”搭配帽子、眼镜等，不能说戴鸡蛋。"}, {"text": "讲", "is_correct": false, "explanation": "语义：鸡蛋不能讲，“手滑”说的是意外弄破东西。"}], "explanations": {"打破": "正确。“我手滑了一下，打破了一个鸡蛋”，打破指鸡蛋碎了。", "写": "搭配：“写”搭配文字，不能说写鸡蛋。", "戴": "搭配：“戴”搭配帽子、眼镜等，不能说戴鸡蛋。", "讲": "语义：鸡蛋不能讲，“手滑”说的是意外弄破东西。"}, "sentence_index": 6, "correct_answer": "打破"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他打破了那个谜语。", "explanation": "这里应该用〈破解〉。破解指解开谜底，谜语要说破解，“打破”只用于东西破损，不能用于谜语。"}, {"text": "他认真地打破了房间。", "explanation": "这里应该用〈打扫〉。打扫指清理，房间要说打扫，不能说打破。"}, {"text": "他打破了那个消息。", "explanation": "这里应该用〈打听〉。打听指询问，问到的消息不能说“打破”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb117516-38ff-424b-bae1-ef068271afe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20658, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "弟弟把那个杯子打破了了。", "corrected_sentence": "弟弟把那个杯子打破了。", "error_description": "错误：“打破了”后面多加了一个“了”，“了”在这里只能用一次。正确：“弟弟把那个杯子打破了。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb117516-38ff-424b-bae1-ef068271afe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20658, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他狠狠地打破了地窗户。", "corrected_sentence": "他狠狠地打破了窗户。", "error_description": "错误：多余的“地”出现在动词“打破了”与名词“窗户”之间，状语“地”只应紧跟在修饰的“狠狠”之后。正确：“他狠狠地打破了窗户。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb117516-38ff-424b-bae1-ef068271afe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
