INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20660, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "“得以”表示有机会做某事，或者能够做成某事。", "primary_collocate": null, "pronunciation": "dé yǐ", "ipa": "tɤ˧˥ i˨˩", "syllable_count": 2, "sentences": [{"text": "经过努力，问题终于得以解决。", "target_word": "得以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了朋友的帮助，他得以完成学业。", "target_word": "得以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨停了以后，比赛得以继续进行。", "target_word": "得以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为大家的支持，这个计划得以实现。", "target_word": "得以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修好路以后，山里的人得以走出大山。", "target_word": "得以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多亏医生及时赶到，病人得以保住生命。", "target_word": "得以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "放假期间，我得以回家看望父母。", "target_word": "得以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的好办法使公司得以度过难关。", "target_word": "得以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争结束后，人们才得以安心生活。", "target_word": "得以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了这笔钱，学校得以建起新教室。", "target_word": "得以", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "因条件具备而能够或有机会做成某事，后接动词；书面语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd392b4f9-49cb-42d5-83fd-145c61c00b83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20660, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "得以", "is_correct": true, "explanation": "得以：dé yǐ，表示条件具备而能够做成某事。"}, {"text": "得意", "is_correct": false, "explanation": "得意：dé yì，第二音节 yì（第四声）与 yǐ（第三声）声调不同，意思是称心如意。"}, {"text": "得益", "is_correct": false, "explanation": "得益：dé yì，第二音节 yì（第四声）与 yǐ（第三声）声调不同，意思是从某事中获得好处。"}, {"text": "得宜", "is_correct": false, "explanation": "得宜：dé yí，第二音节 yí（第二声）与 yǐ（第三声）声调不同，意思是恰当。"}], "explanations": {"得以": "得以：dé yǐ，表示条件具备而能够做成某事。", "得意": "得意：dé yì，第二音节 yì（第四声）与 yǐ（第三声）声调不同，意思是称心如意。", "得益": "得益：dé yì，第二音节 yì（第四声）与 yǐ（第三声）声调不同，意思是从某事中获得好处。", "得宜": "得宜：dé yí，第二音节 yí（第二声）与 yǐ（第三声）声调不同，意思是恰当。"}, "sentence_index": null, "correct_answer": "得以"}, "level_3": {"options": [{"text": "得以", "is_correct": true, "explanation": "得以：表示条件具备后能够做成某事，「经过努力」后问题终于得以解决。"}, {"text": "放弃", "is_correct": false, "explanation": "配价：“放弃”的施事须是人，“问题”不能放弃解决。"}, {"text": "拖延", "is_correct": false, "explanation": "语义：“拖延”表示故意推迟，与“终于”及“经过努力”的结果相反。"}, {"text": "懒得", "is_correct": false, "explanation": "语义：“懒得”表示不愿做，与“经过努力”后问题得到解决的意思相矛盾。"}], "explanations": {"得以": "得以：表示条件具备后能够做成某事，「经过努力」后问题终于得以解决。", "放弃": "配价：“放弃”的施事须是人，“问题”不能放弃解决。", "拖延": "语义：“拖延”表示故意推迟，与“终于”及“经过努力”的结果相反。", "懒得": "语义：“懒得”表示不愿做，与“经过努力”后问题得到解决的意思相矛盾。"}, "sentence_index": 0, "correct_answer": "得以"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他因为迟到，得以被罚站。", "explanation": "这里“得以”用错了。“得以”表示能够做成的好事或有机会做某事，被罚站是不利的结果，二者相矛盾；此处应去掉“得以”。"}, {"text": "这次地震让很多人得以遭受损失。", "explanation": "这里“得以”用错了。“得以”表示能够做成的好事，而受到损失属于不利的结果，二者相矛盾；此处应去掉“得以”。"}, {"text": "这次台风让渔民得以失去了家园。", "explanation": "这里“得以”用错了。“得以”表示能够做成的好事，失去家园属于不利的结果，二者相矛盾；此处应去掉“得以”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbd57905-2a75-4732-b296-47278eecfe97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20660, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "得以", "is_correct": true, "explanation": "得以：表示有机会或条件允许而能够回家，与“放假期间”的空闲情境相符。"}, {"text": "门票", "is_correct": false, "explanation": "语法：「门票」是名词，不能放在「回家看望父母」这个动词短语前作状语。"}, {"text": "错过", "is_correct": false, "explanation": "搭配：“错过”接的是机会或事件，不能直接接“回家看望父母”这类动作。"}, {"text": "禁止", "is_correct": false, "explanation": "语义：「禁止」表示不许做，与「放假期间」可以回家的情境相反。"}], "explanations": {"得以": "得以：表示有机会或条件允许而能够回家，与“放假期间”的空闲情境相符。", "门票": "语法：「门票」是名词，不能放在「回家看望父母」这个动词短语前作状语。", "错过": "搭配：“错过”接的是机会或事件，不能直接接“回家看望父母”这类动作。", "禁止": "语义：「禁止」表示不许做，与「放假期间」可以回家的情境相反。"}, "sentence_index": 6, "correct_answer": "得以"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司倒闭后，他得以陷入困境。", "explanation": "这里“得以”用错了。“得以”表示能够做成的好事，陷入困境是不利的结果，二者相矛盾；此处应去掉“得以”。"}, {"text": "他去年得以患上严重的感冒。", "explanation": "这里“得以”用错了。“得以”表示能够做成的好事，生病属于不利的结果，不能与“得以”搭配；此处应去掉“得以”。"}, {"text": "他最后得以沦为乞丐。", "explanation": "这里“得以”用错了。“得以”表示能够做成的好事，沦为乞丐是悲惨的结局，与“得以”的意思相反；此处应去掉“得以”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbd57905-2a75-4732-b296-47278eecfe97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20660, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "经过大家的努力，桥终于被得以修好。", "corrected_sentence": "经过大家的努力，桥终于得以修好。", "error_description": "“得以”本身已表示能够做成，前面不能再加“被”。错句中的“被得以”重复表达，应删去“被”，写作“桥终于得以修好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbd57905-2a75-4732-b296-47278eecfe97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20660, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "多亏朋友的帮助，他终于得以的出国留学。", "corrected_sentence": "多亏朋友的帮助，他终于得以出国留学。", "error_description": "“得以”后直接接动词短语，不能再加“的”。错句中“得以的出国留学”多出了“的”，应删去，写作“他终于得以出国留学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbd57905-2a75-4732-b296-47278eecfe97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20662, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "集中", "is_correct": true, "explanation": "反义：扩散是向外散布，集中是聚拢到一处，二者互为反义。"}, {"text": "维持", "is_correct": false, "explanation": "无关：维持是保持某种状态，与“扩散”的任何义项都不构成反义。"}, {"text": "等待", "is_correct": false, "explanation": "无关：等待是停下来等候，与“扩散”没有反义关系。"}, {"text": "运输", "is_correct": false, "explanation": "无关：运输是把货物从一处送到另一处，与“扩散”没有反义关系。"}], "correct_answer": "集中", "explanations": {"集中": "反义：扩散是向外散布，集中是聚拢到一处，二者互为反义。", "维持": "无关：维持是保持某种状态，与“扩散”的任何义项都不构成反义。", "等待": "无关：等待是停下来等候，与“扩散”没有反义关系。", "运输": "无关：运输是把货物从一处送到另一处，与“扩散”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f20db2b-ad1d-4235-9415-4a237e6b9018') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20662, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "集中", "is_correct": true, "explanation": "反义：扩散是向外散布，集中是聚拢到一处，二者互为反义。"}, {"text": "掩盖", "is_correct": false, "explanation": "无关：掩盖是遮住某物使其不被看见，与“扩散”没有反义关系。"}, {"text": "煮沸", "is_correct": false, "explanation": "无关：煮沸是把液体加热至沸腾，与“扩散”没有反义关系。"}, {"text": "栽培", "is_correct": false, "explanation": "无关：栽培是种植培育植物，与“扩散”之间没有反义关系。"}], "correct_answer": "集中", "explanations": {"集中": "反义：扩散是向外散布，集中是聚拢到一处，二者互为反义。", "掩盖": "无关：掩盖是遮住某物使其不被看见，与“扩散”没有反义关系。", "煮沸": "无关：煮沸是把液体加热至沸腾，与“扩散”没有反义关系。", "栽培": "无关：栽培是种植培育植物，与“扩散”之间没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f20db2b-ad1d-4235-9415-4a237e6b9018') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20662, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西向四周散开。", "primary_collocate": null, "pronunciation": "kuò sàn", "ipa": "kʰwɔ˥˩ sɑn˥˩", "syllable_count": 2, "sentences": [{"text": "红墨水在水里慢慢扩散。", "target_word": "扩散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "烟从窗口向外扩散。", "target_word": "扩散", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "油滴在水面上扩散开来。", "target_word": "扩散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "香水的味道在房间里扩散。", "target_word": "扩散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "石头掉进水里，波纹向四周扩散。", "target_word": "扩散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "热量从火炉向四周扩散。", "target_word": "扩散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雾气在山谷里慢慢扩散。", "target_word": "扩散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "咖啡的香味扩散到了楼下。", "target_word": "扩散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蓝色的颜料在纸上扩散开来。", "target_word": "扩散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "声波在空气中向四周扩散。", "target_word": "扩散", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "扩散了", "label": "完成体"}, {"form": "扩散着", "label": "持续体"}, {"form": "扩散开来", "label": "复合"}, {"form": "擴散", "label": "繁体"}], "register": "中性", "sense_fingerprint": "物质向四周散开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46d76630-55e4-4191-b05f-0cc4fbf0c071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20662, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "扩散", "is_correct": true, "explanation": "正确。“扩散”指东西向四周散开，红墨水在水中慢慢散开，语义相合。"}, {"text": "凝固", "is_correct": false, "explanation": "语义：墨水在水里不会凝固，句子语义不通。"}, {"text": "生长", "is_correct": false, "explanation": "配价：“生长”要求有生命的主语，墨水没有生命，不能生长。"}, {"text": "发芽", "is_correct": false, "explanation": "语义：只有种子才能发芽，红墨水不能发芽。"}], "explanations": {"扩散": "正确。“扩散”指东西向四周散开，红墨水在水中慢慢散开，语义相合。", "凝固": "语义：墨水在水里不会凝固，句子语义不通。", "生长": "配价：“生长”要求有生命的主语，墨水没有生命，不能生长。", "发芽": "语义：只有种子才能发芽，红墨水不能发芽。"}, "sentence_index": 0, "correct_answer": "扩散"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个公园的面积扩散了三倍。", "explanation": "这里应该用〈扩大〉。扩散指东西向四周散开，面积、范围的扩大要用扩大。"}, {"text": "今年班里的人数扩散了不少。", "explanation": "这里应该用〈增加〉。扩散指向四周散开，人数这类数量的增长要用增加。"}, {"text": "这条公路扩散到了山顶。", "explanation": "这里应该用〈延伸〉。公路是线状向前伸展，扩散强调由中心向四周散开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f20db2b-ad1d-4235-9415-4a237e6b9018') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20662, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "扩散", "is_correct": true, "explanation": "正确。“扩散”指雾气向四周散开，在山谷里慢慢散开，语义相合。"}, {"text": "装订", "is_correct": false, "explanation": "语义：装订是把纸张整理成册，雾气不能被装订。"}, {"text": "批发", "is_correct": false, "explanation": "语义：批发是大批量售卖商品，雾气不能被批发。"}, {"text": "咀嚼", "is_correct": false, "explanation": "配价：咀嚼要求有嘴的主体和食物作宾语，“雾气”不能咀嚼。"}], "explanations": {"扩散": "正确。“扩散”指雾气向四周散开，在山谷里慢慢散开，语义相合。", "装订": "语义：装订是把纸张整理成册，雾气不能被装订。", "批发": "语义：批发是大批量售卖商品，雾气不能被批发。", "咀嚼": "配价：咀嚼要求有嘴的主体和食物作宾语，“雾气”不能咀嚼。"}, "sentence_index": 6, "correct_answer": "扩散"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在新班级扩散了很多朋友。", "explanation": "这里应该用〈结交〉。扩散指东西向四周散布，结识朋友要用结交。"}, {"text": "我们在市中心扩散了一座新图书馆。", "explanation": "这里应该用〈建造〉。扩散指东西向四周散开，建造建筑要用建造。"}, {"text": "老板决定扩散一个新部门。", "explanation": "这里应该用〈设立〉。扩散强调向四周散开，设立机构、部门要用设立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f20db2b-ad1d-4235-9415-4a237e6b9018') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20662, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "墨水慢慢向扩散开了。", "corrected_sentence": "墨水慢慢扩散开了。", "error_description": "介词误用：“向”后须接处所宾语，不能直接放在动词“扩散”前，应删去“向”，说“墨水慢慢扩散开了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f20db2b-ad1d-4235-9415-4a237e6b9018') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20662, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "蒸汽很快向四周很扩散了。", "corrected_sentence": "蒸汽很快向四周扩散了。", "error_description": "程度副词误用：“很”不能修饰动作动词“扩散”，应删去“很”，说“蒸汽很快向四周扩散了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f20db2b-ad1d-4235-9415-4a237e6b9018') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20664, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "竞争", "is_correct": true, "explanation": "竞争与垄断相对：垄断是一家独揽买卖，竞争是多方争夺同一市场。"}, {"text": "生产", "is_correct": false, "explanation": "生产是制造产品，与“垄断”不构成反义关系。"}, {"text": "建设", "is_correct": false, "explanation": "建设是修建、创立，与“垄断”不构成反义关系。"}, {"text": "保护", "is_correct": false, "explanation": "保护是护卫、维护，与“垄断”不构成反义关系。"}], "correct_answer": "竞争", "explanations": {"竞争": "竞争与垄断相对：垄断是一家独揽买卖，竞争是多方争夺同一市场。", "生产": "生产是制造产品，与“垄断”不构成反义关系。", "建设": "建设是修建、创立，与“垄断”不构成反义关系。", "保护": "保护是护卫、维护，与“垄断”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20664, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "竞争", "is_correct": true, "explanation": "竞争与垄断相对：垄断是一家独揽买卖，竞争是多方争夺同一市场。"}, {"text": "合作", "is_correct": false, "explanation": "合作是协同做事，与“垄断”不构成反义关系。"}, {"text": "发明", "is_correct": false, "explanation": "发明是创造新事物，与“垄断”不构成反义关系。"}, {"text": "运输", "is_correct": false, "explanation": "运输是运送货物，与“垄断”不构成反义关系。"}], "correct_answer": "竞争", "explanations": {"竞争": "竞争与垄断相对：垄断是一家独揽买卖，竞争是多方争夺同一市场。", "合作": "合作是协同做事，与“垄断”不构成反义关系。", "发明": "发明是创造新事物，与“垄断”不构成反义关系。", "运输": "运输是运送货物，与“垄断”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20664, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一个人或一家公司把某种东西的全部买卖都包下来，不让别人做。", "primary_collocate": null, "pronunciation": "lǒng duàn", "ipa": "lʊŋ˨˩ tu̯an˥˩", "syllable_count": 2, "sentences": [{"text": "这家公司想垄断整个市场。", "target_word": "垄断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一家大公司垄断了这里的牛奶生意。", "target_word": "垄断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们垄断了这个城市的水果买卖。", "target_word": "垄断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家药厂想垄断当地的药品买卖。", "target_word": "垄断", "complexity_tier": "T3", "furigana": "zhè jiā yào chǎng xiǎng lǒng duàn dāng dì de yào pǐn mǎi mai", "sentence_source": "generated"}, {"text": "这个行业只有一家公司，它垄断了全部生意。", "target_word": "垄断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想垄断这条街上的所有生意。", "target_word": "垄断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "垄断市场对买东西的人不好。", "target_word": "垄断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家公司垄断电话生意很多年了。", "target_word": "垄断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小店做不过垄断市场的大公司。", "target_word": "垄断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家不允许公司垄断大米的买卖。", "target_word": "垄断", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "动词垄断：一家独占某种买卖，不让别人做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63681715-008c-4ce4-9cde-53c69200fb5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20664, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "垄断", "is_correct": true, "explanation": "“垄断”指独占某种买卖，可以带宾语“市场”，句意通顺。"}, {"text": "参加", "is_correct": false, "explanation": "搭配：“参加”后接的是活动、会议，不能说“参加整个市场”。"}, {"text": "倒闭", "is_correct": false, "explanation": "配价：“倒闭”是不及物动词，不能带宾语“整个市场”。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”后接的是歌曲，不能说“唱整个市场”，句子不通。"}], "explanations": {"垄断": "“垄断”指独占某种买卖，可以带宾语“市场”，句意通顺。", "参加": "搭配：“参加”后接的是活动、会议，不能说“参加整个市场”。", "倒闭": "配价：“倒闭”是不及物动词，不能带宾语“整个市场”。", "唱": "搭配：“唱”后接的是歌曲，不能说“唱整个市场”，句子不通。"}, "sentence_index": 0, "correct_answer": "垄断"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他垄断了整个沙发，别人都没地方坐。", "explanation": "这里应该用〈霸占〉。垄断指一家独揽某种买卖，不用于沙发这类物品。"}, {"text": "他的车垄断了门口的停车位，我们的车停不进去。", "explanation": "这里应该用〈占用〉。垄断指一家独揽某种买卖，不用来说车停在车位上。"}, {"text": "这些家务都由我一个人垄断了。", "explanation": "这里应该用〈包揽〉。垄断指独揽买卖，不用于家务这类日常事务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20664, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "垄断", "is_correct": true, "explanation": "“垄断”指独揽买卖，作主语时表示这种行为，句意通顺。"}, {"text": "包括", "is_correct": false, "explanation": "语义：“包括”表示包含某些内容，与“市场对买东西的人不好”的意思对不上。"}, {"text": "批准", "is_correct": false, "explanation": "搭配：“批准”的对象是申请、方案，不能说“批准市场”。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”表示乐于接受，与后面“不好”的评价相矛盾。"}], "explanations": {"垄断": "“垄断”指独揽买卖，作主语时表示这种行为，句意通顺。", "包括": "语义：“包括”表示包含某些内容，与“市场对买东西的人不好”的意思对不上。", "批准": "搭配：“批准”的对象是申请、方案，不能说“批准市场”。", "欢迎": "语义：“欢迎”表示乐于接受，与后面“不好”的评价相矛盾。"}, "sentence_index": 6, "correct_answer": "垄断"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块蛋糕他一个人垄断了。", "explanation": "这里应该用〈独享〉。垄断只指独揽买卖，不用于一个人享用食物。"}, {"text": "这个房间他垄断了一整天，别人没法进来。", "explanation": "这里应该用〈占用〉。垄断指独揽某种买卖，不用来说房间被占用的时间。"}, {"text": "这顿饭的菜都是他垄断的。", "explanation": "这里应该用〈包办〉。垄断指独揽买卖，不用于一个人负责安排饭菜这类事情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20664, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司把市场垄断。", "corrected_sentence": "这家公司把市场垄断了。", "error_description": "“把”字句中动词后要有“了”或其他补语，“把市场垄断”语义不完整，应为“把市场垄断了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20664, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司曾经垄断了过这个市场。", "corrected_sentence": "这家公司曾经垄断过这个市场。", "error_description": "“过”已表示经历，动词后不能再加“了”，应为“垄断过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
