INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20666, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人们一起学的好东西，比如故事、歌、节日。", "primary_collocate": null, "pronunciation": "wén huà", "ipa": "wən˧˥ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "我喜欢中国文化。", "target_word": "文化", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "不同国家的文化不一样。", "target_word": "文化", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "每个国家都有自己的文化。", "target_word": "文化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春节是中国文化的一部分。", "target_word": "文化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在学校学习汉语和中国文化。", "target_word": "文化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去外国旅行，也能看到不同的文化。", "target_word": "文化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家博物馆介绍了很多古代文化。", "target_word": "文化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给我们讲了中国的传统文化。", "target_word": "文化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在中国住过两年，很喜欢那里的文化。", "target_word": "文化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班有很多国家的同学，大家常常分享各自的文化。", "target_word": "文化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "传统文化", "label": "复合"}], "register": "中性", "sense_fingerprint": "文化|一个群体共同拥有的故事、歌、节日等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3e7fa8c-7e28-4a9f-9f73-de782ccd99f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20666, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "文化", "is_correct": true, "explanation": "文化：人们共同拥有的故事、歌、节日等，可以说“喜欢中国文化”。"}, {"text": "面积", "is_correct": false, "explanation": "语义：面积指土地的大小，人不能“喜欢”一个国家的面积，句子说不通。"}, {"text": "人口", "is_correct": false, "explanation": "语义：人口指人数，不是可以喜欢的对象，句子说不通。"}, {"text": "高度", "is_correct": false, "explanation": "搭配：“高度”说高低，不能和“喜欢中国”搭配。"}], "explanations": {"文化": "文化：人们共同拥有的故事、歌、节日等，可以说“喜欢中国文化”。", "面积": "语义：面积指土地的大小，人不能“喜欢”一个国家的面积，句子说不通。", "人口": "语义：人口指人数，不是可以喜欢的对象，句子说不通。", "高度": "搭配：“高度”说高低，不能和“喜欢中国”搭配。"}, "sentence_index": 0, "correct_answer": "文化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把文化放进了冰箱。", "explanation": "这里应该用〈饭菜〉。“文化”指人们共同的生活方式，不是能放进冰箱的东西；要放进冰箱的是〈饭菜〉。"}, {"text": "他跑得很文化，一下子就到了学校。", "explanation": "这里应该用〈快〉。“文化”是名词，指人们共同拥有的故事、歌、节日等，不能用来形容跑得快慢；说跑得快要用〈快〉。"}, {"text": "这件文化很贵，是爷爷留下的。", "explanation": "这里应该用〈文物〉。“文化”指共同的生活方式，不是具体的物件；说有价值的老东西要用〈文物〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20666, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "文化", "is_correct": true, "explanation": "文化：人们共同拥有的生活方式，可以说“介绍古代文化”。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重指重量，博物馆不能“介绍”古代的体重，句子说不通。"}, {"text": "速度", "is_correct": false, "explanation": "语义：速度指快慢，博物馆不能“介绍”古代的速度，句子说不通。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”说的是岁数，不能说“古代年龄”，与“古代”搭配不通。"}], "explanations": {"文化": "文化：人们共同拥有的生活方式，可以说“介绍古代文化”。", "体重": "语义：体重指重量，博物馆不能“介绍”古代的体重，句子说不通。", "速度": "语义：速度指快慢，博物馆不能“介绍”古代的速度，句子说不通。", "年龄": "搭配：“年龄”说的是岁数，不能说“古代年龄”，与“古代”搭配不通。"}, "sentence_index": 6, "correct_answer": "文化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的文化很好，阳光也很明媚。", "explanation": "这里应该用〈天气〉。“文化”指人们共同的生活方式，不能用来形容天气；说天气好要用〈天气〉。"}, {"text": "这位画家的文化很有名，很多人都喜欢他的画。", "explanation": "这里应该用〈作品〉。“文化”指人们共同拥有的故事、歌、节日等，不是一个人画的画；说某人的画有名要用〈作品〉。"}, {"text": "我们班上周看了一场文化，很感动。", "explanation": "这里把“文化”当成“演出”来用。“文化”指人们共同的生活方式，不是可以观看的演出；看演出要说〈演出〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20666, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我觉得不同的民族都有一条文化。", "corrected_sentence": "我觉得不同的民族都有一种文化。", "error_description": "错误：“一条文化”。正确：“一种文化”。“条”用于细长的东西，不能用来计量“文化”；表示一种文化要用“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20666, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些文化们很有意思。", "corrected_sentence": "这些文化很有意思。", "error_description": "错误：“文化们”。正确：“文化”。“文化”是抽象名词，不能加“们”表示复数。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
