INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20670, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20670, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "动植物和人类一起生活的环境。", "primary_collocate": null, "pronunciation": "shēng tài", "ipa": "ʂɤŋ˥ tʰaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这里的生态很好，有很多鸟和鱼。", "target_word": "生态", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂排出脏水，破坏了河边的生态。", "target_word": "生态", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要保护生态，不能乱砍树。", "target_word": "生态", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这片湿地的生态很特别，住着许多少见的鸟。", "target_word": "生态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们乱捕鱼，海里的生态会出问题。", "target_word": "生态", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个公园很注意保护生态。", "target_word": "生态", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农药用得太多，会影响田里的生态。", "target_word": "生态", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专家说，这里的生态比十年前好多了。", "target_word": "生态", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "动物、植物和人一起生活，生态才能平衡。", "target_word": "生态", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他研究湖里的生态，常常去湖边看鱼和草。", "target_word": "生态", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生態", "label": "繁体"}, {"form": "生态环境", "label": "复合"}, {"form": "生态系统", "label": "复合"}], "register": "中性", "sense_fingerprint": "动植物与人类共同生活的自然环境", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e373b1f0-8529-4f99-bdb4-29789ab94d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20670, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生态", "is_correct": true, "explanation": "生态：指鸟、鱼等生物与环境共同构成的状况，与“很好”及“鸟和鱼”的语境相符。"}, {"text": "发音", "is_correct": false, "explanation": "语义：“发音”指说话的声音，不能用来形容地方。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形，不能用来形容一个地方。"}, {"text": "嗓子", "is_correct": false, "explanation": "体貌：“嗓子”指人的发声器官，不能用来形容地方的状况。"}], "explanations": {"生态": "生态：指鸟、鱼等生物与环境共同构成的状况，与“很好”及“鸟和鱼”的语境相符。", "发音": "语义：“发音”指说话的声音，不能用来形容地方。", "身材": "体貌：“身材”指人的体形，不能用来形容一个地方。", "嗓子": "体貌：“嗓子”指人的发声器官，不能用来形容地方的状况。"}, "sentence_index": 0, "correct_answer": "生态"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间教室的生态很大。", "explanation": "这里应该用〈规模〉。生态指生物与环境的相互关系，不指范围的大小。"}, {"text": "这只猫的生态很可爱。", "explanation": "这里应该用〈样子〉。生态指生物与环境的关系，不指动物的外形。"}, {"text": "他的生态很好，是个老实人。", "explanation": "这里应该用〈性格〉。生态不指人的性情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20670, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生态", "is_correct": true, "explanation": "生态：指田里生物与环境的平衡状况，与“影响”搭配自然。"}, {"text": "人口", "is_correct": false, "explanation": "语义：“人口”指一地的人数，不是田里生态的组成部分。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不是田里的生物或环境，不能作为“影响”的对象。"}, {"text": "脸色", "is_correct": false, "explanation": "体貌：“脸色”指人的面部神情，不能用来说田里的状况。"}], "explanations": {"生态": "生态：指田里生物与环境的平衡状况，与“影响”搭配自然。", "人口": "语义：“人口”指一地的人数，不是田里生态的组成部分。", "汽车": "语义：汽车不是田里的生物或环境，不能作为“影响”的对象。", "脸色": "体貌：“脸色”指人的面部神情，不能用来说田里的状况。"}, "sentence_index": 6, "correct_answer": "生态"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块布料的生态很好，穿着很舒服。", "explanation": "这里应该用〈质量〉。生态指生物与环境的关系，不指布料的优劣。"}, {"text": "这道菜的生态很辣。", "explanation": "这里应该用〈味道〉。生态指生物与环境的关系，不指菜的口味。"}, {"text": "他的生态很高。", "explanation": "这里应该用〈身高〉。生态不指人体的高矮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20670, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个湖里有一只特别的生态。", "corrected_sentence": "这个湖里有一种特别的生态。", "error_description": "量词错误：“生态”要用“种”，“只”用于动物等，不能修饰“生态”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20670, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这片森林的一只生态很脆弱。", "corrected_sentence": "这片森林的生态很脆弱。", "error_description": "量词错误：“只”用于动物，不能修饰“生态”。应去掉“一只”，说“这片森林的生态”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
