INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20674, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "印刷工是印书的人。", "primary_collocate": null, "pronunciation": "yìn shuā gōng", "ipa": "in˥˩ ʂua˥˩ kʊŋ˥", "syllable_count": 3, "sentences": [{"text": "我的邻居是印刷工，每天印报纸。", "target_word": "印刷工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂需要三名印刷工。", "target_word": "印刷工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "印刷工小心地把纸放进机器里。", "target_word": "印刷工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "印刷工用黑墨水印出了课本。", "target_word": "印刷工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做了十年印刷工，很有经验。", "target_word": "印刷工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "印刷工今天要印一千本杂志。", "target_word": "印刷工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位印刷工的衬衫上都是墨点。", "target_word": "印刷工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王想跟老印刷工学印书。", "target_word": "印刷工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "印刷工看了看样书，说颜色不对。", "target_word": "印刷工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书店老板请印刷工再印一批书。", "target_word": "印刷工", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名", "label": "量词"}, {"form": "印刷工人", "label": "复合"}], "register": "中性", "sense_fingerprint": "以印书、印报为工作的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46d76630-55e4-4191-b05f-0cc4fbf0c071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20674, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "印刷工", "is_correct": true, "explanation": "正确。“印刷工”是以印书、印报为工作的人，与“每天印报纸”相合。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师的工作是做饭，不是印报纸，句中职业与动作不合。"}, {"text": "司机", "is_correct": false, "explanation": "语义：司机以驾驶为职业，不会每天印报纸。"}, {"text": "园丁", "is_correct": false, "explanation": "搭配：园丁的职业活动是养护植物，不与“每天印报纸”搭配。"}], "explanations": {"印刷工": "正确。“印刷工”是以印书、印报为工作的人，与“每天印报纸”相合。", "厨师": "语义：厨师的工作是做饭，不是印报纸，句中职业与动作不合。", "司机": "语义：司机以驾驶为职业，不会每天印报纸。", "园丁": "搭配：园丁的职业活动是养护植物，不与“每天印报纸”搭配。"}, "sentence_index": 0, "correct_answer": "印刷工"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器是印刷工，每天印三千张。", "explanation": "这里应该用〈印刷机〉。印刷工指人，指机器要用印刷机。"}, {"text": "我们厂每天要把三百本印刷工送到书店。", "explanation": "这里应该用〈书〉。印刷工指印书的人，不能指成品书，送去书店的应是书。"}, {"text": "我每天在印刷工上班，印书。", "explanation": "这里应该用〈印刷厂〉。印刷工指人，表示工作地点要用印刷厂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f20db2b-ad1d-4235-9415-4a237e6b9018') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20674, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "印刷工", "is_correct": true, "explanation": "正确。“印刷工”是人，衬衫上沾满墨点符合印刷工的工作情况。"}, {"text": "公路", "is_correct": false, "explanation": "语义：公路不是人，衬衫上不会沾墨点，句子语义不通。"}, {"text": "雨水", "is_correct": false, "explanation": "配价：“那位”要求后面的名词指人，“雨水”不能用“那位”修饰。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有衬衫，句子语义不通。"}], "explanations": {"印刷工": "正确。“印刷工”是人，衬衫上沾满墨点符合印刷工的工作情况。", "公路": "语义：公路不是人，衬衫上不会沾墨点，句子语义不通。", "雨水": "配价：“那位”要求后面的名词指人，“雨水”不能用“那位”修饰。", "石头": "语义：石头没有衬衫，句子语义不通。"}, "sentence_index": 6, "correct_answer": "印刷工"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "书店老板请印刷工在医院里做手术。", "explanation": "这里应该用〈医生〉。印刷工是印书的人，做手术要用医生。"}, {"text": "书店老板请印刷工在操场上教体育课。", "explanation": "这里应该用〈体育老师〉。印刷工负责印书，教体育课要用体育老师。"}, {"text": "书店老板请印刷工在理发店给他剪头发。", "explanation": "这里应该用〈理发师〉。印刷工是印书的人，在理发店剪头发要用理发师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f20db2b-ad1d-4235-9415-4a237e6b9018') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20674, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈是一只印刷工，每天印杂志。", "corrected_sentence": "妈妈是一名印刷工，每天印杂志。", "error_description": "量词错误：指人的“印刷工”应用量词“名”，不能用“只”（“只”多用于动物）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f20db2b-ad1d-4235-9415-4a237e6b9018') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20674, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姐姐每天印刷工画册。", "corrected_sentence": "姐姐每天印画册。", "error_description": "词性错误：“印刷工”是名词（指人），不能当动词用；此处应直接说“印画册”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f20db2b-ad1d-4235-9415-4a237e6b9018') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20678, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c79d472d-58c7-42b7-bc39-ab743fbaa44c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
