INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20682, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一个秘密的房间。", "primary_collocate": null, "pronunciation": "mì shì", "ipa": "mi˥˩ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这座老房子的地下有一个密室。", "target_word": "密室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明在书房里发现了一个密室。", "target_word": "密室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这间密室没有人知道，只有爷爷有钥匙。", "target_word": "密室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打开柜子后面的门，就能进入一间密室。", "target_word": "密室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的坏人把客人关进了密室。", "target_word": "密室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "密室里很黑，我们只好用手电筒照路。", "target_word": "密室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在城堡里找到了一个旧密室。", "target_word": "密室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个密室的门做成了墙的样子，很难找到。", "target_word": "密室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们走进密室，里面什么也没有。", "target_word": "密室", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她小时候常常躲在家里的密室看书。", "target_word": "密室", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个密室", "label": "量词"}, {"form": "密室逃脱", "label": "复合"}], "register": "中性", "sense_fingerprint": "不为人知的秘密房间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09b46612-8cc8-4c8a-ad20-a3f56ae151b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20682, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "密室", "is_correct": true, "explanation": "密室 mì shì，意思是秘密的房间，不为人知。"}, {"text": "秘书", "is_correct": false, "explanation": "秘书 mì shū 与 密室 mì shì 第二个音节韵母不同（ū 与 ì），意思是协助领导处理事务的人。"}, {"text": "密使", "is_correct": false, "explanation": "密使 mì shǐ 与 密室 mì shì 第二个音节声调不同（第三声与第四声），意思是秘密派遣的使者。"}, {"text": "密实", "is_correct": false, "explanation": "密实 mì shí 与 密室 mì shì 第二个音节声调不同（第二声与第四声），意思是紧密结实。"}, {"text": "闭市", "is_correct": false, "explanation": "闭市 bì shì 与 密室 mì shì 声母不同（b 与 m），意思是市场关门。"}], "explanations": {"密室": "密室 mì shì，意思是秘密的房间，不为人知。", "秘书": "秘书 mì shū 与 密室 mì shì 第二个音节韵母不同（ū 与 ì），意思是协助领导处理事务的人。", "密使": "密使 mì shǐ 与 密室 mì shì 第二个音节声调不同（第三声与第四声），意思是秘密派遣的使者。", "密实": "密实 mì shí 与 密室 mì shì 第二个音节声调不同（第二声与第四声），意思是紧密结实。", "闭市": "闭市 bì shì 与 密室 mì shì 声母不同（b 与 m），意思是市场关门。"}, "sentence_index": null, "correct_answer": "密室"}, "level_3": {"options": [{"text": "密室", "is_correct": true, "explanation": "密室是不为人知的秘密房间，可以设在老房子的地下，符合句意。"}, {"text": "阳台", "is_correct": false, "explanation": "语义：阳台在房屋外侧，不可能在地下。"}, {"text": "屋顶", "is_correct": false, "explanation": "搭配：“地下”不能和“屋顶”搭配。"}, {"text": "天台", "is_correct": false, "explanation": "语义：天台在楼顶，与“地下”矛盾。"}], "explanations": {"密室": "密室是不为人知的秘密房间，可以设在老房子的地下，符合句意。", "阳台": "语义：阳台在房屋外侧，不可能在地下。", "屋顶": "搭配：“地下”不能和“屋顶”搭配。", "天台": "语义：天台在楼顶，与“地下”矛盾。"}, "sentence_index": 0, "correct_answer": "密室"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "运动员们在密室里比赛，观众坐满了看台。", "explanation": "这里应该用〈体育馆〉。密室是隐蔽的小房间，容不下比赛和观众。"}, {"text": "旅客们在密室里等车，准备去北京。", "explanation": "这里应该用〈车站〉。密室是隐蔽的房间，等车要去车站。"}, {"text": "孩子们在密室里玩跷跷板。", "explanation": "这里应该用〈游乐场〉。密室是隐蔽的房间，玩跷跷板要去游乐场。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c79d472d-58c7-42b7-bc39-ab743fbaa44c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20682, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "密室", "is_correct": true, "explanation": "密室是古老城堡里常见的隐蔽房间，符合“旧”的说法。"}, {"text": "超市", "is_correct": false, "explanation": "语义：超市是近代才有的，与古老城堡里找到“旧”东西的情境不符。"}, {"text": "地铁站", "is_correct": false, "explanation": "语义：地铁是现代交通设施，不会出现在古老的城堡里。"}, {"text": "航天器", "is_correct": false, "explanation": "语义：航天器是现代科技设备，不会出现在古老的城堡里。"}], "explanations": {"密室": "密室是古老城堡里常见的隐蔽房间，符合“旧”的说法。", "超市": "语义：超市是近代才有的，与古老城堡里找到“旧”东西的情境不符。", "地铁站": "语义：地铁是现代交通设施，不会出现在古老的城堡里。", "航天器": "语义：航天器是现代科技设备，不会出现在古老的城堡里。"}, "sentence_index": 6, "correct_answer": "密室"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爸爸每天走进密室做饭。", "explanation": "这里应该用〈厨房〉。密室是隐蔽的小房间，做饭要在厨房。"}, {"text": "同学们在密室里游泳，玩得很开心。", "explanation": "这里应该用〈游泳池〉。密室不能游泳，游泳要去游泳池。"}, {"text": "老师在密室里给全班讲课。", "explanation": "这里应该用〈教室〉。密室是隐蔽的房间，上课要去教室。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c79d472d-58c7-42b7-bc39-ab743fbaa44c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20682, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座老房子的墙后面藏着一条密室。", "corrected_sentence": "这座老房子的墙后面藏着一个密室。", "error_description": "量词错误：“密室”是房间，应用“个”或“间”，不用“条”（“条”多用于细长的东西）。正确形式是“一个密室”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c79d472d-58c7-42b7-bc39-ab743fbaa44c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20682, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们密室里发现了一本旧书。", "corrected_sentence": "我们在密室里发现了一本旧书。", "error_description": "介词错误：表示地点的“密室里”前漏掉了介词“在”。正确应为“在密室里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c79d472d-58c7-42b7-bc39-ab743fbaa44c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
