INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20684, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把金属加热化成水，倒进模子里做成东西。", "primary_collocate": null, "pronunciation": "zhù zào", "ipa": "ʈʂu˥˩ tsaʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他把铜加热，倒进模子里铸造硬币。", "target_word": "铸造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂用钢铁铸造大桥上的零件。", "target_word": "铸造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这口钟是用青铜铸造的。", "target_word": "铸造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在博物馆看过古人铸造的铜镜。", "target_word": "铸造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们正忙着铸造新的轮子。", "target_word": "铸造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铸造奖牌前，要先做好模子。", "target_word": "铸造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年轻时在工厂里铸造过铁门。", "target_word": "铸造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想铸造一座高大的铜像。", "target_word": "铸造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅把热铁水倒进模子，开始铸造。", "target_word": "铸造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铸造出来的勺子还很烫。", "target_word": "铸造", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "铸造了", "label": "体标"}, {"form": "铸造过", "label": "体标"}, {"form": "铸造着", "label": "体标"}], "register": "中性", "sense_fingerprint": "铸造：金属加热化开，倒进模子做成东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba171e17-0e71-47fc-bc45-dc66a5f33e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20684, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "雕刻", "is_correct": false, "explanation": "语义：雕刻要用刀具刻出形状，与“倒进模子里”的做法矛盾。"}, {"text": "烘烤", "is_correct": false, "explanation": "搭配：烘烤多用于食物，不说“烘烤硬币”。"}, {"text": "铸造", "is_correct": true, "explanation": "铸造：把铜加热后倒进模子里做成硬币，前后语境完全一致。"}, {"text": "印刷", "is_correct": false, "explanation": "语义：印刷是用油墨把图文印在纸上，与“倒进模子里”的做法不合。"}], "explanations": {"雕刻": "语义：雕刻要用刀具刻出形状，与“倒进模子里”的做法矛盾。", "烘烤": "搭配：烘烤多用于食物，不说“烘烤硬币”。", "铸造": "铸造：把铜加热后倒进模子里做成硬币，前后语境完全一致。", "印刷": "语义：印刷是用油墨把图文印在纸上，与“倒进模子里”的做法不合。"}, "sentence_index": 0, "correct_answer": "铸造"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在博物馆看过古人铸造的玉器。", "explanation": "这里应该用〈雕刻〉。玉要用刀雕刻，玉不能熔化，铸造只用于熔化后的金属。"}, {"text": "师傅用锤子铸造了一把刀。", "explanation": "这里应该用〈锻造〉。锻造是用锤子敲打金属成型，铸造是把熔化的金属倒入模子里。"}, {"text": "工匠铸造了一个陶罐。", "explanation": "这里应该用〈烧制〉。陶罐是用窑火烧制的，陶土不是金属，不能铸造。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c8f0eb-19a2-4e09-a76b-b723b0105203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20684, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "种植", "is_correct": false, "explanation": "语义：种植是栽培植物，不能用来制作铁门，与“工厂里”的语境不合。"}, {"text": "缝纫", "is_correct": false, "explanation": "语义：缝纫用针线做衣物，与金属铁门的制作不相关。"}, {"text": "游泳", "is_correct": false, "explanation": "配价：“游泳”是不及物动词，不能带“铁门”这样的宾语。"}, {"text": "铸造", "is_correct": true, "explanation": "铸造：把铁熔化后倒进模子里做成铁门，符合工厂里制作金属器物的语境。"}], "explanations": {"种植": "语义：种植是栽培植物，不能用来制作铁门，与“工厂里”的语境不合。", "缝纫": "语义：缝纫用针线做衣物，与金属铁门的制作不相关。", "游泳": "配价：“游泳”是不及物动词，不能带“铁门”这样的宾语。", "铸造": "铸造：把铁熔化后倒进模子里做成铁门，符合工厂里制作金属器物的语境。"}, "sentence_index": 6, "correct_answer": "铸造"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人把铁块铸造成了铁水。", "explanation": "这里应该用〈熔化〉。铸造是把金属做成器物，让固体变成液体要用熔化。"}, {"text": "工人用电焊铸造铁门。", "explanation": "这里应该用〈焊接〉。电焊是把金属接在一起，不是熔化后倒进模子成型。"}, {"text": "机器把石头铸造成了沙子。", "explanation": "这里应该用〈粉碎〉。粉碎是把物体弄碎，铸造是把金属做成器物，石头也不能铸造。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c8f0eb-19a2-4e09-a76b-b723b0105203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20684, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人铸造得三口铁锅。", "corrected_sentence": "工人铸造了三口铁锅。", "error_description": "错误在于动态助词：表示动作已经完成，应用“了”，说“铸造了三口铁锅”；“得”用于动词后引出补语，这里不能用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c8f0eb-19a2-4e09-a76b-b723b0105203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20684, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把铁门铸造了好。", "corrected_sentence": "工人把铁门铸造好了。", "error_description": "体标位置错误：“了”应放在结果补语“好”之后，说“铸造好了”，不说“铸造了好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c8f0eb-19a2-4e09-a76b-b723b0105203') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
