INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20686, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "像什么一样。", "primary_collocate": null, "pronunciation": "rú", "ipa": "ʐu˧˥", "syllable_count": 1, "sentences": [{"text": "她的眼睛亮如星星。", "target_word": "如", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座城市夜里灯火如海。", "target_word": "如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的手冷如冰。", "target_word": "如", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天上的云朵白如棉花。", "target_word": "如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山间的小路细如丝线。", "target_word": "如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水如一条长长的带子。", "target_word": "如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的笑容如阳光一样温暖。", "target_word": "如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友的帮助如雪中送炭。", "target_word": "如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的脾气急如火。", "target_word": "如", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人的头发白如雪。", "target_word": "如", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "如同", "label": "复合"}], "register": "书面语", "sense_fingerprint": "表示像某物一样，用于形容状态或性质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T1: 3 words above tier T1 (max 2): 河水 (Zipf 3.84), 长长的 (Zipf 3.52), 带子 (Zipf 3.33)']::text[], '46d76630-55e4-4191-b05f-0cc4fbf0c071') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20686, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "如", "is_correct": true, "explanation": "如（rú，第二声）表示像某物一样，用于形容状态或性质。"}, {"text": "入", "is_correct": false, "explanation": "rù（第四声）与 rú（第二声）声调不同，意思是进入。"}, {"text": "乳", "is_correct": false, "explanation": "rǔ（第三声）与 rú（第二声）声调不同，意思是乳汁。"}, {"text": "辱", "is_correct": false, "explanation": "rǔ（第三声）与 rú（第二声）声调不同，意思是侮辱。"}, {"text": "炉", "is_correct": false, "explanation": "lú 与 rú 声母不同（l／r），意思是炉子。"}], "explanations": {"如": "如（rú，第二声）表示像某物一样，用于形容状态或性质。", "入": "rù（第四声）与 rú（第二声）声调不同，意思是进入。", "乳": "rǔ（第三声）与 rú（第二声）声调不同，意思是乳汁。", "辱": "rǔ（第三声）与 rú（第二声）声调不同，意思是侮辱。", "炉": "lú 与 rú 声母不同（l／r），意思是炉子。"}, "sentence_index": null, "correct_answer": "如"}, "level_3": {"options": [{"text": "如", "is_correct": true, "explanation": "如表示像某物一样，“她的眼睛亮如星星”即眼睛亮得像星星一样。"}, {"text": "具有", "is_correct": false, "explanation": "搭配：“具有”后面接抽象的属性，不能接“星星”这样的具体事物，句子不通。"}, {"text": "买", "is_correct": false, "explanation": "语义：“买”需要买的人和所买的东西，不能用来形容眼睛。"}, {"text": "关", "is_correct": false, "explanation": "语义：“关”指关闭，与“亮”的意思相反，句子矛盾。"}], "explanations": {"如": "如表示像某物一样，“她的眼睛亮如星星”即眼睛亮得像星星一样。", "具有": "搭配：“具有”后面接抽象的属性，不能接“星星”这样的具体事物，句子不通。", "买": "语义：“买”需要买的人和所买的东西，不能用来形容眼睛。", "关": "语义：“关”指关闭，与“亮”的意思相反，句子矛盾。"}, "sentence_index": 0, "correct_answer": "如"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小弟长得如哥哥，一看就是兄弟。", "explanation": "这里应该用〈像〉（长得像，表示外貌相似）。“如”不用于“长得”之后表示外貌相似，口语中不说“长得如”。"}, {"text": "他如我高，一眼就看得出来。", "explanation": "这里应该用〈比〉（比我高）。“如”不表示高低比较，此处只能用“比”。"}, {"text": "这件衣服如那件好看。", "explanation": "这里应该用〈比〉（比那件好看）。“如”不用于比较优劣，比较时用“比”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f20db2b-ad1d-4235-9415-4a237e6b9018') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20686, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "如", "is_correct": true, "explanation": "如（rú，第二声）表示像某物一样，用于形容状态或性质。"}, {"text": "奴", "is_correct": false, "explanation": "nú 与 rú 声母不同（n／r），意思是奴隶。"}, {"text": "芦", "is_correct": false, "explanation": "lú 与 rú 声母不同（l／r），意思是芦苇。"}, {"text": "褥", "is_correct": false, "explanation": "rù（第四声）与 rú（第二声）声调不同，意思是褥子。"}, {"text": "辱", "is_correct": false, "explanation": "rǔ（第三声）与 rú（第二声）声调不同，意思是侮辱。"}], "explanations": {"如": "如（rú，第二声）表示像某物一样，用于形容状态或性质。", "奴": "nú 与 rú 声母不同（n／r），意思是奴隶。", "芦": "lú 与 rú 声母不同（l／r），意思是芦苇。", "褥": "rù（第四声）与 rú（第二声）声调不同，意思是褥子。", "辱": "rǔ（第三声）与 rú（第二声）声调不同，意思是侮辱。"}, "sentence_index": null, "correct_answer": "如"}, "level_3": {"options": [{"text": "如", "is_correct": true, "explanation": "如表示像某物一样，“她的笑容如阳光一样温暖”即笑容像阳光一样温暖。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”搭配帽子、眼镜等物品，不能说笑容“戴”阳光。"}, {"text": "用", "is_correct": false, "explanation": "语义：“用”表示使用某物，笑容不能被“用”来形容温暖。"}, {"text": "抢", "is_correct": false, "explanation": "语义：“抢”指争夺，与“温暖”的描述完全不搭。"}], "explanations": {"如": "如表示像某物一样，“她的笑容如阳光一样温暖”即笑容像阳光一样温暖。", "戴": "搭配：“戴”搭配帽子、眼镜等物品，不能说笑容“戴”阳光。", "用": "语义：“用”表示使用某物，笑容不能被“用”来形容温暖。", "抢": "语义：“抢”指争夺，与“温暖”的描述完全不搭。"}, "sentence_index": 6, "correct_answer": "如"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她看上去如是很累。", "explanation": "这里应该用〈像是〉表示推测（看上去像很累）。“如”只用于比喻，不能表示推测。"}, {"text": "天空如要放晴了。", "explanation": "这里应该用〈好像〉表示推测（看起来要放晴）。“如”只用于比喻，不能表示推测。"}, {"text": "他如没有生气。", "explanation": "这里应该用〈似乎〉表示推测（看起来没有生气）。“如”不能表示推测。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f20db2b-ad1d-4235-9415-4a237e6b9018') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20686, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的皮肤白如了雪。", "corrected_sentence": "她的皮肤白如雪。", "error_description": "错误：“如”后面加了“了”，写成“白如了雪”。正确：“白如雪”，比喻句中“如”后直接接名词，不能带“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f20db2b-ad1d-4235-9415-4a237e6b9018') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20686, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "河边的柳枝细如果丝线。", "corrected_sentence": "河边的柳枝细如丝线。", "error_description": "错误：“如”后多加了“果”，写成“细如果丝线”。“如果”表示假设，不能用于比喻；应删去“果”，写作“细如丝线”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f20db2b-ad1d-4235-9415-4a237e6b9018') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
