INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20690, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指很多东西中不同的样子或类型。", "primary_collocate": null, "pronunciation": "zhǒng lèi", "ipa": "ʈʂʊŋ˨˩˦ lei˥˩", "syllable_count": 2, "sentences": [{"text": "这家店的水果种类很多。", "target_word": "种类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆里书的种类很多。", "target_word": "种类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你喜欢哪个种类的音乐？", "target_word": "种类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物园里动物的种类不少。", "target_word": "种类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菜单上的种类太多，我选不好。", "target_word": "种类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了很多种类不同的茶。", "target_word": "种类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个超市的牛奶种类最多。", "target_word": "种类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花的种类这么多，我都不认识。", "target_word": "种类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店里面包的种类不一样，价钱也不一样。", "target_word": "种类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，你们店里的手机有哪些种类？", "target_word": "种类", "complexity_tier": "T3", "furigana": "zhǒnglèi", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "种类繁多", "label": "复合"}], "register": "中性", "sense_fingerprint": "事物按样子或性质分出的类别", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd55c2c29-17cd-4734-b3f1-6a6d294a15a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20690, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "种类", "is_correct": true, "explanation": "正确。种类指事物的不同样子或类型，这里说水果的类型很多。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：「年龄」一般用于人或动物，不说水果的年龄。"}, {"text": "温度", "is_correct": false, "explanation": "语义：「温度」指冷热程度，不能用来说水果的类别很多。"}, {"text": "天气", "is_correct": false, "explanation": "语义：「天气」指大气状况，与水果的类别无关。"}], "explanations": {"种类": "正确。种类指事物的不同样子或类型，这里说水果的类型很多。", "年龄": "搭配：「年龄」一般用于人或动物，不说水果的年龄。", "温度": "语义：「温度」指冷热程度，不能用来说水果的类别很多。", "天气": "语义：「天气」指大气状况，与水果的类别无关。"}, "sentence_index": 0, "correct_answer": "种类"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条绳子的种类很长。", "explanation": "这里应该用〈长度〉。种类指类别，不能说长短；绳子的长短要说长度。"}, {"text": "这个水库的种类很大，夏天不缺水。", "explanation": "这里应该用〈水量〉。种类是类别，不能说大小；水的多少要说水量。"}, {"text": "这箱货物的种类很重。", "explanation": "这里应该用〈重量〉。种类不能说轻重，货物的轻重要说重量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2512b206-61b6-47f3-a7d1-2353d2b9f1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20690, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "种类", "is_correct": true, "explanation": "正确。种类指牛奶的不同类型，这里说牛奶的类型最多。"}, {"text": "身高", "is_correct": false, "explanation": "语义：「身高」指人或动物的高矮，不能用来说牛奶。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：「体重」一般说人或动物的重量，牛奶不说体重。"}, {"text": "长度", "is_correct": false, "explanation": "语义：「长度」指长短，不能用来说牛奶的类别最多。"}], "explanations": {"种类": "正确。种类指牛奶的不同类型，这里说牛奶的类型最多。", "身高": "语义：「身高」指人或动物的高矮，不能用来说牛奶。", "体重": "搭配：「体重」一般说人或动物的重量，牛奶不说体重。", "长度": "语义：「长度」指长短，不能用来说牛奶的类别最多。"}, "sentence_index": 6, "correct_answer": "种类"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位老人的种类很大了。", "explanation": "这里应该用〈年龄〉。种类指类别，不能说大小；人的岁数要说年龄。"}, {"text": "这个孩子的种类很高。", "explanation": "这里应该用〈身高〉。种类不能说高矮，人的高矮要说身高。"}, {"text": "这台电脑的种类很高。", "explanation": "这里应该用〈价格〉。种类不能说高低，东西的贵贱要说价格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2512b206-61b6-47f3-a7d1-2353d2b9f1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20690, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家超市的饮料种类了很齐全。", "corrected_sentence": "这家超市的饮料种类很齐全。", "error_description": "错误：「种类了」。「种类」是名词，后面不能加「了」，「了」会打断名词短语。正确说法是「饮料种类很齐全」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2512b206-61b6-47f3-a7d1-2353d2b9f1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20690, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家书店的书种类的很丰富。", "corrected_sentence": "这家书店的书种类很丰富。", "error_description": "错误：「种类的很丰富」。「的」要放在名词前面修饰名词，「种类」后面不能加「的」再接「很丰富」。正确说法是「书种类很丰富」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2512b206-61b6-47f3-a7d1-2353d2b9f1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
