INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20692, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在教堂里工作的人。", "primary_collocate": null, "pronunciation": "shén zhí rén yuán", "ipa": "ʂən˧˥ ʈʂɻ̩˧˥ ɻən˧˥ ɥɛn˧˥", "syllable_count": 4, "sentences": [{"text": "教堂的神职人员在门口欢迎我们。", "target_word": "神职人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神职人员每天早上都会打扫教堂。", "target_word": "神职人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位神职人员给孩子们讲了一个故事。", "target_word": "神职人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周日，神职人员在教堂里带大家唱歌。", "target_word": "神职人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我认识一位年轻的神职人员，他很友好。", "target_word": "神职人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神职人员给游客介绍教堂的历史。", "target_word": "神职人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小镇的教堂里有三位神职人员。", "target_word": "神职人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神职人员穿着长袍，站在台上说话。", "target_word": "神职人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天，神职人员让没有伞的人进教堂。", "target_word": "神职人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神职人员每个星期都去医院看望病人。", "target_word": "神职人员", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "神職人員", "label": "繁体"}], "register": "中性", "sense_fingerprint": "在教堂里工作的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c5209d6-189a-4b08-9be6-981d2b1ec05c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20692, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "神职人员", "is_correct": true, "explanation": "神职人员在教堂工作，负责接待和欢迎来访的人，与“教堂的……在门口欢迎我们”相符。"}, {"text": "游客", "is_correct": false, "explanation": "语义：游客是来参观的人，不会在门口“欢迎我们”。"}, {"text": "钟楼", "is_correct": false, "explanation": "搭配：“欢迎”的主语必须是人，不能说“钟楼欢迎我们”。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑构件，不会在门口欢迎人。"}], "explanations": {"神职人员": "神职人员在教堂工作，负责接待和欢迎来访的人，与“教堂的……在门口欢迎我们”相符。", "游客": "语义：游客是来参观的人，不会在门口“欢迎我们”。", "钟楼": "搭配：“欢迎”的主语必须是人，不能说“钟楼欢迎我们”。", "窗户": "语义：窗户是建筑构件，不会在门口欢迎人。"}, "sentence_index": 0, "correct_answer": "神职人员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上骑神职人员去公司。", "explanation": "这里应该用〈自行车〉。「骑」用于车辆，神职人员指在教堂工作的人，不是交通工具。"}, {"text": "我早饭吃了神职人员，又喝了一杯牛奶。", "explanation": "这里应该用〈面包〉。神职人员是人的职务，不是食物，不能拿来吃。"}, {"text": "他是这家工厂的神职人员，负责修理机器。", "explanation": "这里应该用〈技工〉。神职人员指在教堂工作的人，不指工厂里负责修理机器的技术工人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04f4198-0e70-444a-ac7f-4836aea97a90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20692, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "神职人员", "is_correct": true, "explanation": "神职人员是在教堂工作的人，小镇教堂里可以有三位，与“三位”的计数相符。"}, {"text": "长椅", "is_correct": false, "explanation": "搭配：长椅不用量词“位”计数，“三位长椅”不成立。"}, {"text": "钟", "is_correct": false, "explanation": "搭配：钟用“座”或“口”计数，不用“位”。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：钢琴用「架」计数，不用量词「位」。"}], "explanations": {"神职人员": "神职人员是在教堂工作的人，小镇教堂里可以有三位，与“三位”的计数相符。", "长椅": "搭配：长椅不用量词“位”计数，“三位长椅”不成立。", "钟": "搭配：钟用“座”或“口”计数，不用“位”。", "钢琴": "搭配：钢琴用「架」计数，不用量词「位」。"}, "sentence_index": 6, "correct_answer": "神职人员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天坐神职人员去学校。", "explanation": "这里应该用〈公交车〉。“坐”用于车辆，神职人员指在教堂工作的人，不是交通工具。"}, {"text": "我用神职人员量了一下桌子的长度。", "explanation": "这里应该用〈尺子〉。“量”需要测量工具，神职人员指在教堂工作的人，不是测量工具。"}, {"text": "我每天早上读神职人员，了解天气。", "explanation": "这里应该用〈报纸〉。“读”用于报刊，神职人员指在教堂工作的人，不是报纸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04f4198-0e70-444a-ac7f-4836aea97a90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20692, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只神职人员在教堂里为大家讲道。", "corrected_sentence": "一位神职人员在教堂里为大家讲道。", "error_description": "量词错误：指人的神职人员应用量词“位”，不用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04f4198-0e70-444a-ac7f-4836aea97a90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20692, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只神职人员每个星期都在教堂里讲道。", "corrected_sentence": "这位神职人员每个星期都在教堂里讲道。", "error_description": "量词错误：指人的神职人员应用量词“位”，不用动物量词“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a04f4198-0e70-444a-ac7f-4836aea97a90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
