INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20694, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人们相信有神，并一起做礼拜。", "primary_collocate": null, "pronunciation": "zōng jiào", "ipa": "tsʊŋ˥ tɕiɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这个国家有很多种宗教。", "target_word": "宗教", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的家人都信一种宗教。", "target_word": "宗教", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宗教对一些人的生活很重要。", "target_word": "宗教", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对不同的宗教很有兴趣。", "target_word": "宗教", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座老房子是宗教活动的地方。", "target_word": "宗教", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每种宗教都有自己的节日。", "target_word": "宗教", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我朋友研究世界上的宗教。", "target_word": "宗教", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不信宗教，但很尊重别人。", "target_word": "宗教", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的人有不同的宗教。", "target_word": "宗教", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了三大宗教的故事。", "target_word": "宗教", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "宗教信仰", "label": "复合"}], "register": "中性", "sense_fingerprint": "信仰神灵并有共同仪式的社会信仰体系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '578a203d-4358-4a88-a532-6eee781a844a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20694, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "宗教", "is_correct": true, "explanation": "“宗教”指信仰体系，与“很多种”搭配，能正确填入空格。"}, {"text": "首都", "is_correct": false, "explanation": "语义：一个国家只有一个首都，不能说“很多种首都”。"}, {"text": "总统", "is_correct": false, "explanation": "语义：一个国家一般只有一位总统，不能说“很多种总统”。"}, {"text": "人口", "is_correct": false, "explanation": "搭配：“人口”是总量概念，不能用“很多种”来计数。"}], "explanations": {"宗教": "“宗教”指信仰体系，与“很多种”搭配，能正确填入空格。", "首都": "语义：一个国家只有一个首都，不能说“很多种首都”。", "总统": "语义：一个国家一般只有一位总统，不能说“很多种总统”。", "人口": "搭配：“人口”是总量概念，不能用“很多种”来计数。"}, "sentence_index": 0, "correct_answer": "宗教"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位老人每天都吃宗教。", "explanation": "这里应该用〈饭〉。宗教是信仰体系，不能拿来吃。"}, {"text": "这座城市有一本宗教。", "explanation": "这里应该用〈种〉。宗教不能用量词“本”，“本”用于书籍等。"}, {"text": "他是一位虔诚的宗教。", "explanation": "这里应该用〈信徒〉。宗教是信仰体系，指人要用“信徒”；此处把体系说成人，是错误的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a181211-58db-4cd8-92c1-c013be897e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20694, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宗教", "is_correct": true, "explanation": "“宗教”是研究对象，与“研究世界上的”搭配，能正确填入空格。"}, {"text": "邻居", "is_correct": false, "explanation": "语义：邻居住在身边，与“世界上的”的范围相矛盾。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“研究”的对象是学问或事物，不能说“研究作业”。"}, {"text": "同桌", "is_correct": false, "explanation": "语义：同桌是同班的邻座同学，不是可以放在“世界上”范围内研究的对象。"}], "explanations": {"宗教": "“宗教”是研究对象，与“研究世界上的”搭配，能正确填入空格。", "邻居": "语义：邻居住在身边，与“世界上的”的范围相矛盾。", "作业": "搭配：“研究”的对象是学问或事物，不能说“研究作业”。", "同桌": "语义：同桌是同班的邻座同学，不是可以放在“世界上”范围内研究的对象。"}, "sentence_index": 6, "correct_answer": "宗教"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们家是一个大宗教，有几百人。", "explanation": "这里应该用〈宗族〉。宗族指同姓的家族，宗教指信仰体系，不是人群的组织。"}, {"text": "我们周末去宗教做礼拜。", "explanation": "这里应该用〈教堂〉。宗教是信仰体系，不是场所，去做礼拜要说“教堂”。"}, {"text": "他每天向宗教祷告。", "explanation": "这里应该用〈神〉。祷告的对象是神，宗教是体系，不能作为祷告的对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a181211-58db-4cd8-92c1-c013be897e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20694, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他说他不信任何一本宗教。", "corrected_sentence": "他说他不信任何一种宗教。", "error_description": "量词错误：宗教应用量词“种”，“本”用于书籍，不能修饰宗教。正确说法：他说他不信任何一种宗教。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a181211-58db-4cd8-92c1-c013be897e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20694, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本书介绍了世界上主要的宗教们。", "corrected_sentence": "这本书介绍了世界上主要的宗教。", "error_description": "“宗教”是非人名词，不能加“们”表示复数。正确说法：这本书介绍了世界上主要的宗教。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a181211-58db-4cd8-92c1-c013be897e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
