INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20698, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "技能就是你会做的事情，比如画画或骑车。", "primary_collocate": null, "pronunciation": "jì néng", "ipa": "tɕi˥˩ nɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "画画是一项很有用的技能。", "target_word": "技能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学会游泳是一种重要的生活技能。", "target_word": "技能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份工作需要电脑技能。", "target_word": "技能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有很多技能，会开车也会做饭。", "target_word": "技能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在学校学到了不少新技能。", "target_word": "技能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多练习才能提高你的技能。", "target_word": "技能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次培训让工人们学会了新技能。", "target_word": "技能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想找有技能的年轻人。", "target_word": "技能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骑车是孩子们要学的基本技能。", "target_word": "技能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有什么特别的技能吗？", "target_word": "技能", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "通过学习和练习掌握的本领", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '083b86a6-9f7b-4d1f-ab6f-174ff48943e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20698, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "技能", "is_correct": true, "explanation": "正确。“技能”指通过练习掌握的本领，“一项很有用的”修饰它正合适。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“一项”是抽象事项的量词，不能用来数房子。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是事物的属性，不是可以学会、练习的本领。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果是食物，不能作为一项活动或本领。"}], "explanations": {"技能": "正确。“技能”指通过练习掌握的本领，“一项很有用的”修饰它正合适。", "房子": "搭配：“一项”是抽象事项的量词，不能用来数房子。", "颜色": "语义：颜色是事物的属性，不是可以学会、练习的本领。", "水果": "语义：水果是食物，不能作为一项活动或本领。"}, "sentence_index": 0, "correct_answer": "技能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台冰箱的技能很多，能制冰也能保鲜。", "explanation": "这里应该用〈功能〉。技能指人掌握的本领，冰箱的用途要说〈功能〉。"}, {"text": "他有一根很厉害的技能，会游泳。", "explanation": "这里应该用〈项〉或〈种〉。根是细长物的量词，不能用来数技能。"}, {"text": "他是一个技能，会开车也会做饭。", "explanation": "这里应该用〈能手〉。技能指本领，不能用来指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20698, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "技能", "is_correct": true, "explanation": "正确。“学会了新技能”指掌握了新的本领，与“培训”的语境相符。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑部件，不是可以学会的本领。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“学会”的对象是技能、知识，空气不能学会。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能学会，也与“培训”无关。"}], "explanations": {"技能": "正确。“学会了新技能”指掌握了新的本领，与“培训”的语境相符。", "窗户": "语义：窗户是建筑部件，不是可以学会的本领。", "空气": "搭配：“学会”的对象是技能、知识，空气不能学会。", "天气": "语义：天气是自然现象，不能学会，也与“培训”无关。"}, "sentence_index": 6, "correct_answer": "技能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他有一个好技能，每天都早起。", "explanation": "这里应该用〈习惯〉。技能指通过练习掌握的本领，每天早起是习惯。"}, {"text": "这部电影的技能非常精彩，观众都很激动。", "explanation": "这里应该用〈特技〉。电影中的动作效果叫特技，技能指人掌握的本领。"}, {"text": "这张桌子有很好的技能。", "explanation": "这里应该用〈功能〉。桌子没有“掌握本领”的能力，技能只用于人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20698, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一台很实用的技能。", "corrected_sentence": "他有一项很实用的技能。", "error_description": "错误在量词“台”。技能应搭配“项”或“种”；“台”是机器等物品的量词，不能用于技能。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20698, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她掌握了很多实用的技能们。", "corrected_sentence": "她掌握了很多实用的技能。", "error_description": "错误在“们”。“技能”指抽象的本领，不能加“们”表示复数；“很多”已表示数量，应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
