INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20702, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大家，很多人。", "primary_collocate": null, "pronunciation": "gōng zhòng", "ipa": "kʊŋ˥ ʈʂʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这家公司向公众道歉了。", "target_word": "公众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公众都很关心空气的质量。", "target_word": "公众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园周末向公众开放。", "target_word": "公众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察把这个消息告诉了公众。", "target_word": "公众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆每天向公众免费开放。", "target_word": "公众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府要听听公众的意见。", "target_word": "公众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位明星很受公众欢迎。", "target_word": "公众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公众对这个新规定有不同的看法。", "target_word": "公众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长在电视上对公众说话。", "target_word": "公众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作家希望公众多读好书。", "target_word": "公众", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "公众号", "label": "复合"}], "register": "正式", "sense_fingerprint": "社会上的大多数人，普通大众", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c5fcf5b-556e-47e4-b003-813f3f632225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20702, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公众", "is_correct": true, "explanation": "正确。“向公众道歉”指向社会上的人群致歉，符合句意。"}, {"text": "空气", "is_correct": false, "explanation": "语义：道歉的对象必须是能接受歉意的人，空气不能接受道歉。"}, {"text": "众生", "is_correct": false, "explanation": "语域：“众生”是佛教或书面用语，这句是口语叙述，不用“众生”。"}, {"text": "错误", "is_correct": false, "explanation": "搭配：“向……道歉”后面要接人或机构，不说“向错误道歉”。"}], "explanations": {"公众": "正确。“向公众道歉”指向社会上的人群致歉，符合句意。", "空气": "语义：道歉的对象必须是能接受歉意的人，空气不能接受道歉。", "众生": "语域：“众生”是佛教或书面用语，这句是口语叙述，不用“众生”。", "错误": "搭配：“向……道歉”后面要接人或机构，不说“向错误道歉”。"}, "sentence_index": 0, "correct_answer": "公众"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座城市新建了一座公众厕所，方便大家使用。", "explanation": "这里应该用〈公共〉。“公共”修饰场所和设施，如公共厕所；“公众”指社会上的人，不修饰设施。"}, {"text": "我的同事都是公众，我们每天一起工作。", "explanation": "这里不这么用。“公众”指社会上的人，不指同事这一特定群体，不能用来称呼某个单位的人。"}, {"text": "我的一个公众朋友昨天来家里做客。", "explanation": "这里不这么用。“公众”指社会上大多数人，是集合概念，不能指某一个朋友。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20702, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公众", "is_correct": true, "explanation": "正确。“很受公众欢迎”指受到社会上大多数人的喜爱，符合句意。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“受……欢迎”的主体要是人或群体，桌子不能受欢迎。"}, {"text": "空调", "is_correct": false, "explanation": "语义：空调不是能表示喜爱的主体，“很受空调欢迎”不成立。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“受……欢迎”的主体要是人或群体，考试不能受欢迎。"}], "explanations": {"公众": "正确。“很受公众欢迎”指受到社会上大多数人的喜爱，符合句意。", "桌子": "语义：“受……欢迎”的主体要是人或群体，桌子不能受欢迎。", "空调": "语义：空调不是能表示喜爱的主体，“很受空调欢迎”不成立。", "考试": "语义：“受……欢迎”的主体要是人或群体，考试不能受欢迎。"}, "sentence_index": 6, "correct_answer": "公众"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们小区的公众都很热心，常常互相帮忙。", "explanation": "这里应该用〈居民〉。“公众”指社会上的人，不指住在某个小区的人；指同一小区的住户要用“居民”。"}, {"text": "我们公司的公众每天八点上班。", "explanation": "这里应该用〈员工〉。“公众”指社会上的人，不指某个单位的工作人员；公司里工作的人要用“员工”。"}, {"text": "这个班的公众都很用功。", "explanation": "这里应该用〈学生〉。“公众”指社会上的人，不指某个班的成员，不能用来形容班里的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20702, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一个公众都在关注这次事件。", "corrected_sentence": "广大公众都在关注这次事件。", "error_description": "量词错误：“公众”是集合概念，不能用“个”计数。应把“一个”改为“广大”，说“广大公众都在关注这次事件”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20702, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位歌手很公众喜爱。", "corrected_sentence": "这位歌手很受公众喜爱。", "error_description": "漏词错误：“受”漏掉。“受……喜爱”是固定格式，表示受到某类人的喜欢，应说“很受公众喜爱”，不能省去“受”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20704, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "狭窄", "is_correct": true, "explanation": "狭窄：范围小，与“广泛”在范围大小上形成反义。"}, {"text": "明显", "is_correct": false, "explanation": "明显指容易看出，与“广泛”的范围大小无关，没有反义关系。"}, {"text": "复杂", "is_correct": false, "explanation": "复杂指结构或情况多而乱，与“广泛”没有反义关系。"}, {"text": "漫长", "is_correct": false, "explanation": "漫长形容时间长，与“广泛”的范围含义无关。"}], "correct_answer": "狭窄", "explanations": {"狭窄": "狭窄：范围小，与“广泛”在范围大小上形成反义。", "明显": "明显指容易看出，与“广泛”的范围大小无关，没有反义关系。", "复杂": "复杂指结构或情况多而乱，与“广泛”没有反义关系。", "漫长": "漫长形容时间长，与“广泛”的范围含义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cd11993-5f59-45eb-b678-6470344c8f5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
