INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20704, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "表示范围很大，比如很多人或很多地方。", "primary_collocate": null, "pronunciation": "guǎng fàn", "ipa": "kwɑŋ˨˩ fan˥˩", "syllable_count": 2, "sentences": [{"text": "这本书受到广泛的欢迎。", "target_word": "广泛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的兴趣很广泛。", "target_word": "广泛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题引起了广泛的关注。", "target_word": "广泛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机的使用非常广泛。", "target_word": "广泛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她交友的范围很广泛。", "target_word": "广泛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种方法在学校里应用广泛。", "target_word": "广泛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他读书很广泛，什么都看。", "target_word": "广泛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个消息在网上广泛传播。", "target_word": "广泛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家对这件事有广泛的讨论。", "target_word": "广泛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的商品种类很广泛。", "target_word": "广泛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "广泛地", "label": "副词形式"}, {"form": "广泛性", "label": "复合"}, {"form": "廣泛", "label": "繁体"}], "register": "书面", "sense_fingerprint": "广泛：涉及的范围很大，人多、地方多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b37b86d-3dce-4b15-a8aa-9eaa55042092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20704, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "广泛", "is_correct": true, "explanation": "广泛：涉及的人多、范围大，修饰“欢迎”，指很多人欢迎。"}, {"text": "陡峭", "is_correct": false, "explanation": "语义：“陡峭”形容地势，不能修饰“欢迎”。"}, {"text": "寒冷", "is_correct": false, "explanation": "语义：“寒冷”指温度低，与“欢迎”的含义相悖。"}, {"text": "沉重", "is_correct": false, "explanation": "搭配：“欢迎”是一种态度，“沉重”不能与之搭配，句意不通。"}], "explanations": {"广泛": "广泛：涉及的人多、范围大，修饰“欢迎”，指很多人欢迎。", "陡峭": "语义：“陡峭”形容地势，不能修饰“欢迎”。", "寒冷": "语义：“寒冷”指温度低，与“欢迎”的含义相悖。", "沉重": "搭配：“欢迎”是一种态度，“沉重”不能与之搭配，句意不通。"}, "sentence_index": 0, "correct_answer": "广泛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间教室很广泛。", "explanation": "这里应该用〈宽敞〉。广泛指涉及的人或事物范围大，不用来形容房间等空间的面积。"}, {"text": "这片草原非常广泛。", "explanation": "这里应该用〈辽阔〉。辽阔形容地域广大，广泛不用来描述土地的面积。"}, {"text": "这个操场十分广泛。", "explanation": "这里应该用〈宽阔〉。宽阔形容空间面积大，广泛不能用于形容操场。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cd11993-5f59-45eb-b678-6470344c8f5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20704, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "广泛", "is_correct": true, "explanation": "广泛：涉及的范围大，与“什么都看”相合。"}, {"text": "炎热", "is_correct": false, "explanation": "语义：“炎热”指气温高，不能描述读书的范围。"}, {"text": "漆黑", "is_correct": false, "explanation": "语义：“漆黑”形容颜色或光线，与读书的范围无关。"}, {"text": "嘈杂", "is_correct": false, "explanation": "搭配：“嘈杂”多形容环境或声音，不用来形容人读书。"}], "explanations": {"广泛": "广泛：涉及的范围大，与“什么都看”相合。", "炎热": "语义：“炎热”指气温高，不能描述读书的范围。", "漆黑": "语义：“漆黑”形容颜色或光线，与读书的范围无关。", "嘈杂": "搭配：“嘈杂”多形容环境或声音，不用来形容人读书。"}, "sentence_index": 6, "correct_answer": "广泛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对这件事的印象很广泛。", "explanation": "这里应该用〈深刻〉。广泛说的是范围大，“印象”说的是程度深，要用深刻。"}, {"text": "他的脾气很广泛。", "explanation": "这里应该用〈大〉。广泛说的是范围大，脾气的程度要用“大”来说。"}, {"text": "他对家乡的思念很广泛。", "explanation": "这里应该用〈深切〉。广泛说的是涉及的范围，思念的程度要用深切。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cd11993-5f59-45eb-b678-6470344c8f5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20704, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事引起了广泛地注意。", "corrected_sentence": "这件事引起了广泛的注意。", "error_description": "错误：“广泛”修饰名词“注意”，应用“的”，不能用“地”。“地”用于修饰动词，应为“广泛的注意”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cd11993-5f59-45eb-b678-6470344c8f5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20704, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的爱好很的广泛，常常去看展览。", "corrected_sentence": "他的爱好很广泛，常常去看展览。", "error_description": "错误：“很”后不能接“的”再接形容词。“很”直接修饰“广泛”，应去掉“的”，说“很广泛”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6cd11993-5f59-45eb-b678-6470344c8f5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
