INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20706, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不绕弯子。", "primary_collocate": null, "pronunciation": "zhí jiē", "ipa": "ʈʂɻ̩˧˥ tɕjɛ˥", "syllable_count": 2, "sentences": [{"text": "有问题就直接说，别不好意思。", "target_word": "直接", "complexity_tier": "T3", "furigana": "yǒu wèn tí jiù zhí jiē shuō, bié bù hǎo yì si。", "sentence_source": "generated"}, {"text": "他说话很直接，有什么说什么。", "target_word": "直接", "complexity_tier": "T3", "furigana": "tā shuō huà hěn zhí jiē, yǒu shénme shuō shénme。", "sentence_source": "generated"}, {"text": "你可以直接说，不用客气。", "target_word": "直接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咱们别绕弯子，直接说吧。", "target_word": "直接", "complexity_tier": "T3", "furigana": "zán men bié rào wān zi, zhí jiē shuō ba。", "sentence_source": "generated"}, {"text": "他没有直接回答我的问题。", "target_word": "直接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我直接说吧，你的方案不太行。", "target_word": "直接", "complexity_tier": "T3", "furigana": "wǒ zhí jiē shuō ba, nǐ de fāng àn bú tài xíng。", "sentence_source": "generated"}, {"text": "他问得很直接，让我有点尴尬。", "target_word": "直接", "complexity_tier": "T3", "furigana": "tā wèn de hěn zhí jiē, ràng wǒ yǒu diǎn gān gà。", "sentence_source": "generated"}, {"text": "你有意见就直接提，别藏在心里。", "target_word": "直接", "complexity_tier": "T3", "furigana": "nǐ yǒu yì jiàn jiù zhí jiē tí, bié cáng zài xīn lǐ。", "sentence_source": "generated"}, {"text": "他的回答很直接，让人印象深刻。", "target_word": "直接", "complexity_tier": "T3", "furigana": "tā de huí dá hěn zhí jiē, ràng rén yìn xiàng shēn kè。", "sentence_source": "generated"}, {"text": "她直接说出了自己的想法。", "target_word": "直接", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "不经过中间环节，不绕弯子，径直做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '578a203d-4358-4a88-a532-6eee781a844a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20706, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "直接", "is_correct": true, "explanation": "“有问题就直接说”表示不绕弯子地说，能正确填入空格。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示已完成，与“有问题就”的假设相矛盾。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”表示从未如此，与“有问题就”的假设不搭。"}, {"text": "仍然", "is_correct": false, "explanation": "搭配：“仍然”要接已成立的状态，不能接“有问题就”这样的假设。"}], "explanations": {"直接": "“有问题就直接说”表示不绕弯子地说，能正确填入空格。", "已经": "语义：“已经”表示已完成，与“有问题就”的假设相矛盾。", "从来": "语义：“从来”表示从未如此，与“有问题就”的假设不搭。", "仍然": "搭配：“仍然”要接已成立的状态，不能接“有问题就”这样的假设。"}, "sentence_index": 0, "correct_answer": "直接"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他通过朋友直接认识了她。", "explanation": "这里应该用〈间接〉。“通过朋友”说明经过了中间人，与“直接”矛盾。"}, {"text": "我们直接工作到了晚上。", "explanation": "这里应该用〈一直〉。“直接”指不经过中间环节，不能表示持续，持续要用“一直”。"}, {"text": "他说话一向很直接，总是绕来绕去。", "explanation": "这里应该用〈委婉〉。“绕来绕去”说明说话绕弯子，与“直接”（不绕弯子）矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a181211-58db-4cd8-92c1-c013be897e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20706, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "直接", "is_correct": true, "explanation": "“问得很直接”指问话不绕弯子，能正确填入空格。"}, {"text": "亲切", "is_correct": false, "explanation": "语义：“亲切”表示态度温和，与“让我有点尴尬”的语境不搭。"}, {"text": "温和", "is_correct": false, "explanation": "语义：“温和”表示性子柔和，与“让我有点尴尬”的语境不搭。"}, {"text": "安静", "is_correct": false, "explanation": "搭配：“安静”形容环境或状态，不能用来修饰“问得”的方式。"}], "explanations": {"直接": "“问得很直接”指问话不绕弯子，能正确填入空格。", "亲切": "语义：“亲切”表示态度温和，与“让我有点尴尬”的语境不搭。", "温和": "语义：“温和”表示性子柔和，与“让我有点尴尬”的语境不搭。", "安静": "搭配：“安静”形容环境或状态，不能用来修饰“问得”的方式。"}, "sentence_index": 6, "correct_answer": "直接"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他经过三次转手，直接买到了这本书。", "explanation": "这里应该用〈辗转〉。“经过三次转手”说明有中间环节，与“直接”矛盾。"}, {"text": "他拐弯抹角，直接说出了想法。", "explanation": "这里应该用〈含蓄〉。“直接”指不绕弯子、直说，与“含蓄”的说话方式相反，两者不能描述同一次说话。"}, {"text": "这件事他没告诉我，我是直接从别人那里听说的。", "explanation": "这里应该用〈间接〉。“从别人那里听说”经过了中间人，与“直接”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a181211-58db-4cd8-92c1-c013be897e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20706, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我直接直接告诉你吧。", "corrected_sentence": "我直接告诉你吧。", "error_description": "重复错误：副词“直接”只需用一次，不能连续重复。正确说法：我直接告诉你吧。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a181211-58db-4cd8-92c1-c013be897e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20706, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他直接了给我答案。", "corrected_sentence": "他直接给了我答案。", "error_description": "体标错误：副词“直接”后面不能直接接“了”。“了”应放在动词“给”后面。正确说法：他直接给了我答案。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a181211-58db-4cd8-92c1-c013be897e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20708, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "缓慢", "is_correct": true, "explanation": "缓慢：速度慢，与“迅速”相反。"}, {"text": "安静", "is_correct": false, "explanation": "安静指声音小或没有声响，与“迅速”没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮形容光线或颜色，与“迅速”没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚形容看得分明，与“迅速”没有反义关系。"}], "correct_answer": "缓慢", "explanations": {"缓慢": "缓慢：速度慢，与“迅速”相反。", "安静": "安静指声音小或没有声响，与“迅速”没有反义关系。", "明亮": "明亮形容光线或颜色，与“迅速”没有反义关系。", "清楚": "清楚形容看得分明，与“迅速”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
