INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20708, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "动作很快，马上就能做完。", "primary_collocate": null, "pronunciation": "xùn sù", "ipa": "ɕyn˥˩ su˥˩", "syllable_count": 2, "sentences": [{"text": "他迅速地跑到了门口。", "target_word": "迅速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "消防员迅速赶到了现场。", "target_word": "迅速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他听到消息后迅速收拾好行李。", "target_word": "迅速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到电话声，她迅速拿起手机。", "target_word": "迅速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生的动作很迅速，一会儿就做完了。", "target_word": "迅速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他迅速把作业写完了。", "target_word": "迅速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫迅速跳上了桌子。", "target_word": "迅速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警报响起后，大家迅速撤离了大楼。", "target_word": "迅速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师迅速回答了我的问题。", "target_word": "迅速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察迅速地抓住了那个小偷。", "target_word": "迅速", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "速度快，动作或变化很快", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '083b86a6-9f7b-4d1f-ab6f-174ff48943e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20708, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "迅速", "is_correct": true, "explanation": "迅速：动作很快，与“很快跑到门口”相符。"}, {"text": "静止", "is_correct": false, "explanation": "语义：静止指不动，与“跑”的动作矛盾。"}, {"text": "漫长", "is_correct": false, "explanation": "搭配：漫长形容时间或距离，不能修饰“跑”的方式。"}, {"text": "陈旧", "is_correct": false, "explanation": "语义：陈旧指过时，不能描述跑的动作。"}], "explanations": {"迅速": "迅速：动作很快，与“很快跑到门口”相符。", "静止": "语义：静止指不动，与“跑”的动作矛盾。", "漫长": "搭配：漫长形容时间或距离，不能修饰“跑”的方式。", "陈旧": "语义：陈旧指过时，不能描述跑的动作。"}, "sentence_index": 0, "correct_answer": "迅速"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他迅速地学了三年汉语。", "explanation": "迅速强调动作很快，不能与“三年”这样的长时段连用。这里应该用〈慢慢〉。"}, {"text": "我们迅速地在这里住了十年。", "explanation": "迅速只说动作快，不能描述“住了十年”这种持续的状态。这里应该用〈长期〉。"}, {"text": "他迅速地思考了一整个下午。", "explanation": "迅速与“一整个下午”的长时间矛盾。这里应该用〈仔细〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20708, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "迅速", "is_correct": true, "explanation": "迅速：动作很快，与“小猫跳上桌子”相符。"}, {"text": "墨绿", "is_correct": false, "explanation": "语义：墨绿是颜色，不能修饰跳的动作。"}, {"text": "方正", "is_correct": false, "explanation": "语义：方正形容形状端正，不能修饰跳的动作。"}, {"text": "忧郁", "is_correct": false, "explanation": "语义：忧郁形容心情，不能修饰跳的动作。"}], "explanations": {"迅速": "迅速：动作很快，与“小猫跳上桌子”相符。", "墨绿": "语义：墨绿是颜色，不能修饰跳的动作。", "方正": "语义：方正形容形状端正，不能修饰跳的动作。", "忧郁": "语义：忧郁形容心情，不能修饰跳的动作。"}, "sentence_index": 6, "correct_answer": "迅速"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他坐上了迅速的火车。", "explanation": "这里应该用〈快速〉。迅速强调动作完成得及时、马上，形容列车行驶的速度要用〈快速〉。"}, {"text": "警察迅速地在街上散步，很悠闲。", "explanation": "语义矛盾：“迅速”强调动作很快，不能用来形容“散步”这种悠闲的动作。这里应该用〈缓缓〉。"}, {"text": "警察迅速地慢慢走过了街道。", "explanation": "迅速强调动作很快，不能用来形容“慢慢”走过这种缓慢的动作。这里应该用〈快步〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20708, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他迅速得关上了窗户。", "corrected_sentence": "他迅速地关上了窗户。", "error_description": "错误：“迅速得”；正确：“迅速地”。“迅速”修饰动词时要用结构助词“地”，“得”用于动词或形容词之后引出补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20708, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子迅速的跑回了家。", "corrected_sentence": "孩子迅速地跑回了家。", "error_description": "错误：“迅速的跑”；正确：“迅速地跑”。“的”用于名词前，“迅速”修饰动词时要用“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434cc1e-0024-4e4d-aa99-228994ce5157') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
