INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20710, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人们写的故事、诗歌等。", "primary_collocate": null, "pronunciation": "wén xué zuò pǐn", "ipa": "wən˧˥ ɕɥe˧˥ tsuɔ˥˩ pʰin˨˩˦", "syllable_count": 4, "sentences": [{"text": "故事和诗歌都是文学作品。", "target_word": "文学作品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最喜欢读中国的古代文学作品。", "target_word": "文学作品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书里有很多有名的文学作品。", "target_word": "文学作品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写过一部很长的文学作品。", "target_word": "文学作品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们写一篇关于这部文学作品的短文。", "target_word": "文学作品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小说是一种文学作品，里面有人物和故事。", "target_word": "文学作品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些诗歌和故事都是很美的文学作品。", "target_word": "文学作品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我在家读文学作品，不看电视。", "target_word": "文学作品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部文学作品有中文和英文两种版本。", "target_word": "文学作品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把喜欢的文学作品都放在书架上。", "target_word": "文学作品", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "部", "label": "量词"}, {"form": "文學作品", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人们写的故事、诗歌等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a75c456c-0a28-4657-b2af-ed1ca1e72345') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20710, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乐器", "is_correct": false, "explanation": "语义：“乐器”是演奏用的器具，不是人写的故事或诗歌，与句意不符。"}, {"text": "文学作品", "is_correct": true, "explanation": "填入〈文学作品〉：人们写的故事、诗歌等，与“故事和诗歌”同属一类，符合句意。"}, {"text": "家具", "is_correct": false, "explanation": "语义：“家具”是有形的实物，不是人写的故事或诗歌，不能与它们归为同类。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：“蔬菜”是食物，不是人写的故事或诗歌，与句意不符。"}], "explanations": {"乐器": "语义：“乐器”是演奏用的器具，不是人写的故事或诗歌，与句意不符。", "文学作品": "填入〈文学作品〉：人们写的故事、诗歌等，与“故事和诗歌”同属一类，符合句意。", "家具": "语义：“家具”是有形的实物，不是人写的故事或诗歌，不能与它们归为同类。", "蔬菜": "语义：“蔬菜”是食物，不是人写的故事或诗歌，与句意不符。"}, "sentence_index": 0, "correct_answer": "文学作品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部文学作品是一辆跑得很快的汽车。", "explanation": "这里应该用〈交通工具〉。文学作品是人们写的故事、诗歌等，不是车辆，不能说是汽车。"}, {"text": "下雨了，我打开一部文学作品挡雨。", "explanation": "这里应该用〈雨伞〉。挡雨要用雨伞，文学作品是人们写的故事、诗歌等，不能挡雨。"}, {"text": "他是一部很有名的文学作品。", "explanation": "这里应该用〈作家〉。文学作品指作品本身，不能用来指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20710, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "饭菜", "is_correct": false, "explanation": "语义：“饭菜”是食物，不是人写的诗歌和故事，与“很美的”搭配不通。"}, {"text": "房子", "is_correct": false, "explanation": "语义：“房子”是建筑，不是人写的诗歌和故事，不能说“都是很美的房子”。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：“玩具”是用来玩耍的物品，与诗歌和故事的性质不符。"}, {"text": "文学作品", "is_correct": true, "explanation": "填入〈文学作品〉：人们写的故事、诗歌等，可以用“很美的”修饰，符合句意。"}], "explanations": {"饭菜": "语义：“饭菜”是食物，不是人写的诗歌和故事，与“很美的”搭配不通。", "房子": "语义：“房子”是建筑，不是人写的诗歌和故事，不能说“都是很美的房子”。", "玩具": "语义：“玩具”是用来玩耍的物品，与诗歌和故事的性质不符。", "文学作品": "填入〈文学作品〉：人们写的故事、诗歌等，可以用“很美的”修饰，符合句意。"}, "sentence_index": 6, "correct_answer": "文学作品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我渴了，想喝一杯文学作品。", "explanation": "这里应该用〈果汁〉。“喝”的对象是饮料，文学作品是人们写的故事、诗歌等，不能喝。"}, {"text": "我家的小狗是一部文学作品，它很会跑。", "explanation": "这里应该用〈动物〉。文学作品是人们写的故事、诗歌等，不是动物，不能当成宠物。"}, {"text": "这部文学作品是一顿很好吃的午饭。", "explanation": "这里应该用〈食物〉。文学作品是人们写的故事、诗歌等，不是食物，不能当午饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20710, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老人写了一只文学作品，讲的是一个老渔夫的故事。", "corrected_sentence": "这位老人写了一部文学作品，讲的是一个老渔夫的故事。", "error_description": "量词错误：“文学作品”应用“部”或“篇”计量，“只”用于动物等，不能说“一只文学作品”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20710, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把那座旧的文学作品借给了朋友。", "corrected_sentence": "我把那本旧的文学作品借给了朋友。", "error_description": "错误：“座”用于山、房屋等大型固定的东西，不能用于“文学作品”，应说“那本旧的文学作品”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9ec3490-8c32-4ad8-9366-0c4f41f90d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
