INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20712, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "复兴就是让一个东西重新变得很好。", "primary_collocate": null, "pronunciation": "fù xīng", "ipa": "fu˥˩ ɕiŋ˥", "syllable_count": 2, "sentences": [{"text": "这家老字号在新老板手里复兴了。", "target_word": "复兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个旧品牌想复兴，就得做新产品。", "target_word": "复兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷的小店生意不好，他想让它复兴。", "target_word": "复兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老歌最近又复兴了，年轻人也爱听。", "target_word": "复兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种旧式手表在去年复兴了。", "target_word": "复兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想让家里的小公司复兴。", "target_word": "复兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个球队多年不赢，现在终于复兴了。", "target_word": "复兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过去的老游戏，现在又复兴了。", "target_word": "复兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他花了两年让这家旧书店复兴。", "target_word": "复兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那种老式衣服在年轻人中复兴了。", "target_word": "复兴", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "复兴了", "label": "体标"}, {"form": "復興", "label": "繁体"}, {"form": "复兴运动", "label": "复合"}], "register": "通用", "sense_fingerprint": "事物或店铺品牌等沉寂后重新变好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a99ff1f-84fe-4580-9f45-814e6a0bd5f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20712, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "复兴", "is_correct": true, "explanation": "复兴（fù xīng）指事物沉寂后重新变好，是正确答案。"}, {"text": "福星", "is_correct": false, "explanation": "fú（第二声）与 fù（第四声）声调不同，福星意思是带来好运的人或物。"}, {"text": "复醒", "is_correct": false, "explanation": "xǐng（第三声）与 xīng（第一声）声调不同，复醒意思是再次醒来。"}, {"text": "复姓", "is_correct": false, "explanation": "xìng（第四声）与 xīng（第一声）声调不同，复姓指两个字的姓。"}, {"text": "赋性", "is_correct": false, "explanation": "xìng（第四声）与 xīng（第一声）声调不同，赋性意思是天生的性情。"}], "explanations": {"复兴": "复兴（fù xīng）指事物沉寂后重新变好，是正确答案。", "福星": "fú（第二声）与 fù（第四声）声调不同，福星意思是带来好运的人或物。", "复醒": "xǐng（第三声）与 xīng（第一声）声调不同，复醒意思是再次醒来。", "复姓": "xìng（第四声）与 xīng（第一声）声调不同，复姓指两个字的姓。", "赋性": "xìng（第四声）与 xīng（第一声）声调不同，赋性意思是天生的性情。"}, "sentence_index": null, "correct_answer": "复兴"}, "level_3": {"options": [{"text": "复兴", "is_correct": true, "explanation": "“在新老板手里复兴了”指老字号在新老板手中重新变好，与语境一致。"}, {"text": "辞职", "is_correct": false, "explanation": "搭配：“辞职”的主语须是人，老字号这样的店铺不能辞职。"}, {"text": "发言", "is_correct": false, "explanation": "搭配：“发言”需要有说话能力的主体，老字号不能发言。"}, {"text": "逃跑", "is_correct": false, "explanation": "语义：“逃跑”指有生命的主体离开，与老字号这样的事物不符。"}], "explanations": {"复兴": "“在新老板手里复兴了”指老字号在新老板手中重新变好，与语境一致。", "辞职": "搭配：“辞职”的主语须是人，老字号这样的店铺不能辞职。", "发言": "搭配：“发言”需要有说话能力的主体，老字号不能发言。", "逃跑": "语义：“逃跑”指有生命的主体离开，与老字号这样的事物不符。"}, "sentence_index": 0, "correct_answer": "复兴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "经过治疗，他的嗓子终于复兴了。", "explanation": "这里应该用〈恢复〉。复兴用于衰落的事物或品牌重新变好，人的身体机能好转要用恢复。"}, {"text": "那张被撕坏的老照片终于复兴了。", "explanation": "这里应该用〈复原〉。复原指恢复原样，多用于照片、文物，复兴不用于修复实物。"}, {"text": "他输了比赛以后，一直想复兴自己的面子。", "explanation": "这里应该用〈挽回〉。挽回指收回失去的面子或利益，复兴不能与面子搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2d5561a-5768-437b-a0a0-ef03d2a3b402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20712, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "复兴", "is_correct": true, "explanation": "复兴（fù xīng）指事物沉寂后重新变好，是正确答案。"}, {"text": "服刑", "is_correct": false, "explanation": "fú xíng 两个字都与 fù xīng 声调不同（第二声对第四声，第二声对第一声）。服刑意思是在监狱里接受刑罚。"}, {"text": "腐刑", "is_correct": false, "explanation": "fǔ xíng 两个字都与 fù xīng 声调不同（第三声对第四声，第二声对第一声）。腐刑是古代的一种刑罚。"}, {"text": "父兄", "is_correct": false, "explanation": "xiōng 与 xīng 韵母不同（iong 对 ing），声调相同。父兄意思是父亲和哥哥。"}], "explanations": {"复兴": "复兴（fù xīng）指事物沉寂后重新变好，是正确答案。", "服刑": "fú xíng 两个字都与 fù xīng 声调不同（第二声对第四声，第二声对第一声）。服刑意思是在监狱里接受刑罚。", "腐刑": "fǔ xíng 两个字都与 fù xīng 声调不同（第三声对第四声，第二声对第一声）。腐刑是古代的一种刑罚。", "父兄": "xiōng 与 xīng 韵母不同（iong 对 ing），声调相同。父兄意思是父亲和哥哥。"}, "sentence_index": null, "correct_answer": "复兴"}, "level_3": {"options": [{"text": "复兴", "is_correct": true, "explanation": "“现在终于复兴了”指球队从多年低迷中重新变好，与“多年不赢”形成前后对比。"}, {"text": "哭泣", "is_correct": false, "explanation": "语义：“哭泣”指人流泪，球队不会哭泣，与语境不符。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：“咳嗽”是人的生理行为，不能用于描述球队。"}, {"text": "思考", "is_correct": false, "explanation": "语义：“思考”指用脑子考虑问题，与球队“多年不赢”之后状态好转的语境不符。"}], "explanations": {"复兴": "“现在终于复兴了”指球队从多年低迷中重新变好，与“多年不赢”形成前后对比。", "哭泣": "语义：“哭泣”指人流泪，球队不会哭泣，与语境不符。", "咳嗽": "语义：“咳嗽”是人的生理行为，不能用于描述球队。", "思考": "语义：“思考”指用脑子考虑问题，与球队“多年不赢”之后状态好转的语境不符。"}, "sentence_index": 6, "correct_answer": "复兴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次比赛输了，教练努力让队员的伤腿复兴。", "explanation": "这里应该用〈痊愈〉。复兴用于衰落的事物重新兴盛，伤病的康复要用痊愈。"}, {"text": "他的病情慢慢复兴了。", "explanation": "这里应该用〈好转〉。复兴用于事物的重新兴盛，病情的变化要用好转。"}, {"text": "那台老机器修好以后，终于复兴了。", "explanation": "这里应该用〈修复〉。修复指把损坏的机器修好，复兴不用于机器的修理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2d5561a-5768-437b-a0a0-ef03d2a3b402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20712, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家旧饭店在新老板手里慢慢复兴下来了。", "corrected_sentence": "这家旧饭店在新老板手里慢慢复兴起来了。", "error_description": "补语错误：“复兴”后应接“起来”，表示由弱变强；“下来”表示向下，与“复兴”的向上之意相反，应说“复兴起来了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2d5561a-5768-437b-a0a0-ef03d2a3b402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20712, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个旧品牌正在复兴过。", "corrected_sentence": "这个旧品牌正在复兴。", "error_description": "体标错误：“正在”表示动作进行中，不能与表示经历的“过”同用，应去掉“过”，说“正在复兴”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2d5561a-5768-437b-a0a0-ef03d2a3b402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
